const String _orionPhotoCustomWidgetCode = r'''
import 'dart:convert';

import 'package:flutter/material.dart';

class AvarynOrionPhoto extends StatelessWidget {
  const AvarynOrionPhoto({
    super.key,
    this.width,
    this.height,
  });

  final double? width;
  final double? height;

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      width: width,
      height: height,
      child: ClipRRect(
        borderRadius: BorderRadius.circular(6),
        child: Image.memory(
          base64Decode(_orionJpegBase64),
          width: width,
          height: height,
          fit: BoxFit.cover,
          gaplessPlayback: true,
          filterQuality: FilterQuality.high,
        ),
      ),
    );
  }
}

