const String _horseshoeIconCustomWidgetCode = r'''
import 'dart:math' as math;

import 'package:flutter/material.dart';

class AvarynHorseshoeIcon extends StatelessWidget {
  const AvarynHorseshoeIcon({
    super.key,
    this.width,
    this.height,
    this.active = false,
  });

  final double? width;
  final double? height;
  final bool active;

  @override
  Widget build(BuildContext context) {
    final theme = FlutterFlowTheme.of(context);
    final color = active ? theme.secondary : theme.secondaryText;

    return SizedBox(
      width: width,
      height: height,
      child: CustomPaint(painter: _AvarynHorseshoePainter(color)),
    );
  }
}

class _AvarynHorseshoePainter extends CustomPainter {
  const _AvarynHorseshoePainter(this.color);

  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    final side = math.min(size.width, size.height);
    final dx = (size.width - side) / 2;
    final dy = (size.height - side) / 2;
    canvas.translate(dx, dy);

    final outline = Paint()
      ..color = color
      ..style = PaintingStyle.stroke
      ..strokeWidth = side * 0.085
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round;

    final outer = Path()
      ..moveTo(side * 0.22, side * 0.18)
      ..cubicTo(
        side * 0.10,
        side * 0.38,
        side * 0.14,
        side * 0.73,
        side * 0.34,
        side * 0.87,
      )
      ..cubicTo(
        side * 0.43,
        side * 0.94,
        side * 0.57,
        side * 0.94,
        side * 0.66,
        side * 0.87,
      )
      ..cubicTo(
        side * 0.86,
        side * 0.73,
        side * 0.90,
        side * 0.38,
        side * 0.78,
        side * 0.18,
      );
    canvas.drawPath(outer, outline);

    final inner = Path()
      ..moveTo(side * 0.34, side * 0.26)
      ..cubicTo(
        side * 0.27,
        side * 0.43,
        side * 0.29,
        side * 0.66,
        side * 0.41,
        side * 0.74,
      )
      ..cubicTo(
        side * 0.46,
        side * 0.78,
        side * 0.54,
        side * 0.78,
        side * 0.59,
        side * 0.74,
      )
      ..cubicTo(
        side * 0.71,
        side * 0.66,
        side * 0.73,
        side * 0.43,
        side * 0.66,
        side * 0.26,
      );
    final innerPaint = Paint()
      ..color = color
      ..style = PaintingStyle.stroke
      ..strokeWidth = side * 0.045
      ..strokeCap = StrokeCap.round;
    canvas.drawPath(inner, innerPaint);

    final nailPaint = Paint()..color = color;
    for (final point in <Offset>[
      Offset(side * 0.22, side * 0.42),
      Offset(side * 0.26, side * 0.67),
      Offset(side * 0.78, side * 0.42),
      Offset(side * 0.74, side * 0.67),
    ]) {
      canvas.drawCircle(point, side * 0.035, nailPaint);
    }
  }

  @override
  bool shouldRepaint(covariant _AvarynHorseshoePainter oldDelegate) =>
      oldDelegate.color != color;
}
''';

const String _horseAvatarCustomWidgetCode = r'''
import 'dart:convert';
import 'dart:math' as math;
import 'dart:typed_data';

import 'package:flutter/material.dart';

class AvarynHorseAvatar extends StatelessWidget {
  const AvarynHorseAvatar({
    super.key,
    this.width,
    this.height,
    this.photoState,
  });

  final double? width;
  final double? height;
  final String? photoState;

  static final Uint8List _sampleHorsePhotoBytes =
      base64Decode(_sampleHorseAvatarJpegBase64);

  bool get _showsSamplePhoto {
    final normalized = (photoState ?? '').trim().toLowerCase();
    return normalized == 'photo' || normalized == 'samplephoto';
  }

  Uint8List? get _uploadedPhotoBytes {
    final value = (photoState ?? '').trim();
    if (!value.startsWith('data:image/')) {
      return null;
    }
    final separator = value.indexOf(',');
    if (separator < 0 || separator == value.length - 1) {
      return null;
    }
    try {
      return base64Decode(value.substring(separator + 1));
    } catch (_) {
      return null;
    }
  }

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      width: width,
      height: height,
      child: LayoutBuilder(
        builder: (context, constraints) {
          final theme = FlutterFlowTheme.of(context);
          final requestedWidth = width ?? 48.0;
          final requestedHeight = height ?? 48.0;
          final resolvedWidth = constraints.maxWidth.isFinite
              ? constraints.maxWidth
              : requestedWidth;
          final resolvedHeight = constraints.maxHeight.isFinite
              ? constraints.maxHeight
              : requestedHeight;
          final shortestSide = math.min(resolvedWidth, resolvedHeight);

          final uploadedPhotoBytes = _uploadedPhotoBytes;

          return ClipRRect(
            borderRadius: BorderRadius.circular(
              math.min(18.0, math.max(6.0, shortestSide * 0.22)),
            ),
            child: uploadedPhotoBytes != null
                ? Image.memory(
                    uploadedPhotoBytes,
                    width: width,
                    height: height,
                    fit: BoxFit.cover,
                    alignment: Alignment.center,
                    gaplessPlayback: true,
                    filterQuality: FilterQuality.high,
                  )
                : _showsSamplePhoto
                    ? Image.memory(
                        _sampleHorsePhotoBytes,
                        width: width,
                        height: height,
                        fit: BoxFit.cover,
                        alignment: Alignment.center,
                        gaplessPlayback: true,
                        filterQuality: FilterQuality.high,
                      )
                    : CustomPaint(
                        painter: _AvarynHorseHeadPainter(
                          backgroundColor: theme.accent2,
                          silhouetteColor: theme.primaryText,
                        ),
                      ),
          );
        },
      ),
    );
  }
}

class _AvarynHorseHeadPainter extends CustomPainter {
  const _AvarynHorseHeadPainter({
    required this.backgroundColor,
    required this.silhouetteColor,
  });

  final Color backgroundColor;
  final Color silhouetteColor;

  @override
  void paint(Canvas canvas, Size size) {
    final side = math.min(size.width, size.height);
    final dx = (size.width - side) / 2;
    final dy = (size.height - side) / 2;
    canvas.translate(dx, dy);

    final background = Paint()..color = backgroundColor;
    canvas.drawRect(Rect.fromLTWH(0, 0, side, side), background);

    final silhouette = Paint()
      ..color = silhouetteColor
      ..isAntiAlias = true
      ..style = PaintingStyle.fill;
    final horse = Path()
      ..moveTo(side * 0.17, side * 0.92)
      ..cubicTo(side * 0.22, side * 0.82, side * 0.21, side * 0.73, side * 0.23, side * 0.64)
      ..cubicTo(side * 0.24, side * 0.59, side * 0.26, side * 0.55, side * 0.29, side * 0.51)
      ..cubicTo(side * 0.30, side * 0.48, side * 0.30, side * 0.45, side * 0.30, side * 0.42)
      ..cubicTo(side * 0.34, side * 0.43, side * 0.36, side * 0.40, side * 0.36, side * 0.36)
      ..cubicTo(side * 0.40, side * 0.37, side * 0.43, side * 0.32, side * 0.46, side * 0.27)
      ..cubicTo(side * 0.45, side * 0.22, side * 0.45, side * 0.16, side * 0.46, side * 0.12)
      ..cubicTo(side * 0.47, side * 0.09, side * 0.49, side * 0.06, side * 0.51, side * 0.07)
      ..cubicTo(side * 0.54, side * 0.11, side * 0.56, side * 0.18, side * 0.56, side * 0.24)
      ..cubicTo(side * 0.58, side * 0.21, side * 0.60, side * 0.16, side * 0.63, side * 0.12)
      ..cubicTo(side * 0.65, side * 0.09, side * 0.67, side * 0.08, side * 0.68, side * 0.11)
      ..cubicTo(side * 0.70, side * 0.16, side * 0.69, side * 0.23, side * 0.66, side * 0.29)
      ..cubicTo(side * 0.71, side * 0.34, side * 0.73, side * 0.39, side * 0.73, side * 0.46)
      ..cubicTo(side * 0.74, side * 0.53, side * 0.79, side * 0.58, side * 0.85, side * 0.61)
      ..cubicTo(side * 0.90, side * 0.63, side * 0.93, side * 0.65, side * 0.92, side * 0.69)
      ..cubicTo(side * 0.91, side * 0.73, side * 0.87, side * 0.75, side * 0.82, side * 0.75)
      ..cubicTo(side * 0.74, side * 0.76, side * 0.68, side * 0.72, side * 0.61, side * 0.67)
      ..cubicTo(side * 0.57, side * 0.75, side * 0.56, side * 0.84, side * 0.63, side * 0.92)
      ..close();
    canvas.drawPath(horse, silhouette);
  }

  @override
  bool shouldRepaint(covariant _AvarynHorseHeadPainter oldDelegate) =>
      oldDelegate.backgroundColor != backgroundColor ||
      oldDelegate.silhouetteColor != silhouetteColor;
}

