    final days = _visibleDays();
    final planned = _plannedActivities();
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        if (_isRange) ...[
          Row(
            children: [
              Expanded(
                child: _endpoint(
                  theme,
