          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                label,
                style: theme.labelSmall.copyWith(color: theme.secondary),
              ),
              const SizedBox(height: 3),
              Text(
                value,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
                style: theme.bodySmall,
              ),
            ],
          ),
        ),
      );

  Widget _dayCell(FlutterFlowTheme theme, DateTime day) {
    final start = _sameDay(day, _startDate);
    final end = _sameDay(day, _endDate);
    final inRange = _startDate != null &&
        _endDate != null &&
        day.isAfter(_startDate!) &&
        day.isBefore(_endDate!);
    final outside = day.month != _displayedMonth.month ||
        day.year != _displayedMonth.year;
    final selected = start || end;
    return Semantics(
      button: true,
      selected: selected,
      label: _dateLabel(day),
      child: InkWell(
        onTap: () => _selectDate(day),
        borderRadius: BorderRadius.circular(999),
        child: Container(
          alignment: Alignment.center,
          decoration: BoxDecoration(
            color: selected
                ? theme.secondary
                : inRange
                    ? theme.accent2
                    : Colors.transparent,
            borderRadius: BorderRadius.circular(selected ? 999 : 5),
          ),
          child: Text(
            '${day.day}',
            style: theme.bodySmall.copyWith(
              color: selected
                  ? theme.primary
                  : outside
                      ? theme.secondaryText
                      : inRange
                          ? theme.secondary
                          : theme.primaryText,
              fontWeight: selected ? FontWeight.w600 : FontWeight.w400,
            ),
          ),
        ),
      ),
    );
  }

