  Widget _calendarDay(
    FlutterFlowTheme theme,
    DateTime date,
    int count,
  ) {
    final today = _sameDay(date, DateTime.now());
    final selected = _sameDay(date, _selectedDate);
    final outside = date.month != _displayedMonth.month ||
        date.year != _displayedMonth.year;
    return Semantics(
      button: true,
      selected: selected,
      label: '${_dateLabel(date)}, $count activiteiten',
      child: InkWell(
        onTap: () => setState(() {
          _selectedDate = _day(date);
          if (outside) {
            _displayedMonth = DateTime(date.year, date.month);
          }
        }),
        borderRadius: BorderRadius.circular(9),
        child: Container(
          decoration: BoxDecoration(
            color: selected ? theme.secondary : Colors.transparent,
            borderRadius: BorderRadius.circular(9),
            border: Border.all(
              color: today
                  ? theme.secondary
                  : selected
                      ? theme.secondary
                      : Colors.transparent,
              width: today ? 1.2 : 0.8,
            ),
          ),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Text(
                '${date.day}',
                style: theme.labelMedium.copyWith(
                  color: selected
                      ? theme.primary
                      : outside
                          ? theme.secondaryText
                          : theme.primaryText,
                  fontWeight:
                      selected || today ? FontWeight.w700 : FontWeight.w500,
                ),
              ),
              const SizedBox(height: 2),
              if (count > 0)
                Container(
                  constraints: const BoxConstraints(minWidth: 16),
                  padding:
                      const EdgeInsets.symmetric(horizontal: 4, vertical: 1),
                  decoration: BoxDecoration(
                    color: selected ? theme.primary : theme.accent2,
                    borderRadius: BorderRadius.circular(999),
                  ),
                  child: Text(
                    '$count',
                    textAlign: TextAlign.center,
                    style: theme.labelSmall.copyWith(
                      fontSize: 9,
                      height: 1.1,
                      color: selected ? theme.accent1 : theme.secondary,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                )
              else
                const SizedBox(height: 12),
            ],
          ),
        ),
      ),
    );
  }

