                      ),
                    ),
                    const SizedBox(width: 10),
                    Expanded(
                      child: FilledButton(
                        onPressed: _submitting ? null : _submit,
                        style: FilledButton.styleFrom(
                          backgroundColor: theme.secondary,
                          foregroundColor: theme.primaryBackground,
                        ),
                        child: Text(
                          _submitting ? 'Opslaan…' : 'Opslaan',
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
