  Widget _dateEndpointButtons(FlutterFlowTheme theme) => Row(
        children: [
          Expanded(
            child: _dateEndpoint(
              theme,
              'start',
              'Datum van',
              _nutritionDateLabel(_startDate),
            ),
          ),
          const SizedBox(width: 8),
          Expanded(
            child: _dateEndpoint(
              theme,
              'end',
              'Tot en met',
              _nutritionDateLabel(_endDate),
            ),
          ),
        ],
      );

  Widget _dateEndpoint(
    FlutterFlowTheme theme,
    String value,
    String label,
    String date,
  ) {
    final selected = _rangeStep == value;
    return InkWell(
      borderRadius: BorderRadius.circular(11),
      onTap: () => setState(() => _rangeStep = value),
      child: Container(
        padding: const EdgeInsets.all(11),
        decoration: BoxDecoration(
          color: selected ? theme.accent2 : theme.primaryBackground,
          borderRadius: BorderRadius.circular(11),
          border: Border.all(
            color: selected ? theme.secondary : theme.alternate,
          ),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              label,
              style: theme.labelSmall.copyWith(
                color: selected ? theme.secondary : theme.secondaryText,
                fontWeight: FontWeight.w700,
              ),
            ),
            const SizedBox(height: 2),
            Text(
              date,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: theme.bodySmall.copyWith(color: theme.primaryText),
            ),
          ],
        ),
      ),
    );
  }

  Widget _calendar(FlutterFlowTheme theme) {
    final days = _nutritionVisibleDays(_displayedMonth);
    return Container(
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: theme.primaryBackground,
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: theme.alternate),
      ),
      child: Column(
        children: [
          Row(
            children: [
              IconButton(
                tooltip: 'Vorige maand',
                onPressed: () => setState(
                  () => _displayedMonth = DateTime(
                    _displayedMonth.year,
                    _displayedMonth.month - 1,
                  ),
                ),
                icon: const Icon(Icons.chevron_left),
                color: theme.secondary,
              ),
              Expanded(
                child: Text(
                  _nutritionMonthLabel(_displayedMonth),
                  textAlign: TextAlign.center,
                  style: theme.titleMedium.copyWith(
                    color: theme.primaryText,
                    fontWeight: FontWeight.w700,
                  ),
                ),
              ),
              IconButton(
                tooltip: 'Volgende maand',
                onPressed: () => setState(
                  () => _displayedMonth = DateTime(
                    _displayedMonth.year,
                    _displayedMonth.month + 1,
                  ),
                ),
                icon: const Icon(Icons.chevron_right),
                color: theme.secondary,
              ),
            ],
          ),
          const SizedBox(height: 6),
          Row(
            children: const ['Ma', 'Di', 'Wo', 'Do', 'Vr', 'Za', 'Zo']
                .map(
                  (label) => Expanded(
                    child: Text(
                      label,
                      textAlign: TextAlign.center,
                    ),
                  ),
                )
                .toList(),
          ),
          const SizedBox(height: 6),
          GridView.builder(
            shrinkWrap: true,
            physics: const NeverScrollableScrollPhysics(),
            itemCount: days.length,
            gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
              crossAxisCount: 7,
              mainAxisExtent: 40,
            ),
            itemBuilder: (context, index) => _dayCell(theme, days[index]),
          ),
        ],
      ),
    );
  }

  Widget _dayCell(FlutterFlowTheme theme, DateTime day) {
    final outside = day.month != _displayedMonth.month;
    final selectedStart =
        _startDate != null && _nutritionSameDay(day, _startDate!);
    final selectedEnd = _endDate != null && _nutritionSameDay(day, _endDate!);
    final inside = _startDate != null &&
        _endDate != null &&
        day.isAfter(_startDate!) &&
        day.isBefore(_endDate!);
    final selected = selectedStart || selectedEnd;
    return InkWell(
      borderRadius: BorderRadius.circular(9),
      onTap: () => _selectDay(day),
      child: Container(
        margin: const EdgeInsets.all(2),
        alignment: Alignment.center,
        decoration: BoxDecoration(
          color: selected
              ? theme.secondary
              : inside
                  ? theme.accent3
                  : Colors.transparent,
          borderRadius: BorderRadius.circular(9),
        ),
        child: Text(
          '${day.day}',
          style: theme.bodySmall.copyWith(
            color: selected
                ? theme.primaryBackground
                : outside
                    ? theme.secondaryText.withOpacity(0.55)
                    : theme.primaryText,
            fontWeight: selected ? FontWeight.w700 : FontWeight.w500,
          ),
        ),
      ),
    );
  }

  void _selectDay(DateTime raw) {
    final day = _nutritionDay(raw);
    setState(() {
      _error = null;
      _emptyConfirmation = false;
      if (_rangeStep == 'start') {
        _startDate = day;
        if (_endDate != null && _endDate!.isBefore(day)) _endDate = null;
        _rangeStep = 'end';
      } else {
        if (_startDate == null) {
          _startDate = day;
          _rangeStep = 'end';
        } else if (day.isBefore(_startDate!)) {
          _error = 'Tot en met mag niet vóór Datum van liggen.';
        } else {
          _endDate = day;
        }
      }
      if (day.month != _displayedMonth.month ||
          day.year != _displayedMonth.year) {
        _displayedMonth = DateTime(day.year, day.month);
      }
    });
  }

  Widget _roundChoice(FlutterFlowTheme theme, (String, String) round) {
    final selected = _selectedRounds.contains(round.$1);
    return FilterChip(
      selected: selected,
      label: Text(round.$2),
      avatar: Icon(
        selected ? Icons.check : Icons.add,
        size: 17,
        color: selected ? theme.primaryBackground : theme.secondary,
      ),
      selectedColor: theme.secondary,
      backgroundColor: theme.accent2,
      checkmarkColor: theme.primaryBackground,
      labelStyle: theme.labelMedium.copyWith(
        color: selected ? theme.primaryBackground : theme.primaryText,
        fontWeight: FontWeight.w700,
      ),
      onSelected: (value) => _toggleRound(round.$1, value),
    );
  }

  void _toggleRound(String roundId, bool selected) {
    setState(() {
      _error = null;
      _emptyConfirmation = false;
      if (selected) {
        _selectedRounds.add(roundId);
        if (!_rounds.containsKey(roundId)) {
          final source = widget.standardRounds.firstWhere(
            (round) => round.roundId == roundId,
            orElse: () => FeedingRoundSnapshotDataStruct(
              roundId: roundId,
              items: const <FeedingItemDataStruct>[],
            ),
          );
          _rounds[roundId] = _nutritionCopyRound(source);
        }
      } else {
        _selectedRounds.remove(roundId);
        _rounds.remove(roundId);
      }
    });
  }

  Widget _temporaryRoundEditor(FlutterFlowTheme theme, String roundId) {
    final round = _rounds[roundId] ??
        FeedingRoundSnapshotDataStruct(
          roundId: roundId,
          items: const <FeedingItemDataStruct>[],
        );
    return Container(
      padding: const EdgeInsets.all(13),
      decoration: BoxDecoration(
        color: theme.primaryBackground,
        borderRadius: BorderRadius.circular(13),
        border: Border.all(color: theme.alternate),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Text(
            _nutritionRoundLabel(roundId),
            style: theme.titleMedium.copyWith(
              color: theme.primaryText,
              fontWeight: FontWeight.w700,
            ),
          ),
          if (round.items.isEmpty) ...[
            const SizedBox(height: 6),
            Text(
              'Tijdelijk geen voeding ingesteld.',
              style: theme.bodySmall.copyWith(color: theme.secondaryText),
            ),
          ],
          ..._nutritionCategories.map((category) {
            final items = round.items
                .where((item) => item.categoryId == category.$1)
                .toList();
            return Padding(
              padding: const EdgeInsets.only(top: 10),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Row(
                    children: [
                      Icon(category.$3, size: 17, color: theme.secondary),
                      const SizedBox(width: 7),
                      Expanded(
                        child: Text(
                          category.$2,
                          style: theme.labelMedium.copyWith(
                            color: theme.primaryText,
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                      ),
                      IconButton(
                        tooltip: '${category.$2} toevoegen',
                        onPressed: _itemEditorOpen
                            ? null
                            : () => _editTemporaryItem(
                                  roundId,
                                  category.$1,
                                  null,
                                ),
                        icon: const Icon(Icons.add),
                        color: theme.secondary,
                      ),
                    ],
                  ),
                  if (items.isEmpty)
                    Padding(
                      padding: const EdgeInsets.only(left: 24),
                      child: Text(
                        'Nog niets ingesteld',
                        style:
                            theme.bodySmall.copyWith(color: theme.secondaryText),
                      ),
                    )
                  else
                    ...items.map(
                      (item) => ListTile(
                        dense: true,
                        contentPadding: const EdgeInsets.only(left: 20),
                        title: Text(
                          item.name,
                          style: theme.bodyMedium.copyWith(
                            color: theme.primaryText,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                        subtitle: item.instruction.trim().isEmpty
                            ? null
                            : Text(
                                item.instruction,
                                style: TextStyle(color: theme.secondaryText),
                              ),
                        onTap: _itemEditorOpen
                            ? null
                            : () => _editTemporaryItem(
                                  roundId,
                                  category.$1,
                                  item,
                                ),
                        trailing: IconButton(
                          tooltip: 'Verwijderen',
                          onPressed: () =>
                              _removeTemporaryItem(roundId, item.id),
                          icon: const Icon(Icons.delete_outline),
                          color: theme.error,
                        ),
                      ),
                    ),
                ],
              ),
            );
          }),
        ],
      ),
    );
  }

  Future<void> _editTemporaryItem(
    String roundId,
    String categoryId,
    FeedingItemDataStruct? existing,
  ) async {
    if (_itemEditorOpen || _saving) return;
    setState(() => _itemEditorOpen = true);
    try {
      final result = await _showFeedingItemEditor(
        context,
        roundId: roundId,
        categoryId: categoryId,
        existing: existing,
        proposedId: existing?.id ??
            'feed-item-temp-${DateTime.now().microsecondsSinceEpoch}',
      );
      if (!mounted || result == null) return;
      final round = _rounds[roundId]!;
      final items = List<FeedingItemDataStruct>.from(round.items);
      final index = items.indexWhere((item) => item.id == result.id);
      if (index >= 0) {
        items[index] = result;
      } else {
        items.add(result);
      }
      setState(() {
        _rounds[roundId] = FeedingRoundSnapshotDataStruct(
          roundId: roundId,
          items: items,
        );
        _emptyConfirmation = false;
      });
    } finally {
      if (mounted) setState(() => _itemEditorOpen = false);
    }
  }

  void _removeTemporaryItem(String roundId, String itemId) {
    final round = _rounds[roundId]!;
    setState(() {
      _rounds[roundId] = FeedingRoundSnapshotDataStruct(
        roundId: roundId,
        items: round.items.where((item) => item.id != itemId).toList(),
      );
      _emptyConfirmation = false;
    });
  }

  InputDecoration _tempInput(
    FlutterFlowTheme theme,
    String label,
    String hint,
  ) =>
      InputDecoration(
        labelText: label,
        hintText: hint,
        labelStyle: TextStyle(color: theme.secondaryText),
        filled: true,
        fillColor: theme.primaryBackground,
        border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(10),
          borderSide: BorderSide(color: theme.alternate),
        ),
        enabledBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(10),
          borderSide: BorderSide(color: theme.alternate),
        ),
        focusedBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(10),
          borderSide: BorderSide(color: theme.secondary, width: 1.5),
        ),
      );

  void _submit() {
    if (_saving) return;
    if (_startDate == null) {
      setState(() => _error = 'Kies Datum van.');
      return;
    }
    if (_endDate == null) {
      setState(() => _error = 'Kies Tot en met.');
      return;
    }
    if (_endDate!.isBefore(_startDate!)) {
      setState(() => _error = 'Tot en met mag niet vóór Datum van liggen.');
      return;
    }
    if (_selectedRounds.isEmpty) {
      setState(() => _error = 'Kies minimaal één voerbeurt.');
      return;
    }
    final conflict = _findConflict();
    if (conflict != null) {
      setState(() => _error = conflict);
      return;
    }
    final hasEmpty = _selectedRounds.any(
      (roundId) => (_rounds[roundId]?.items ?? const []).isEmpty,
    );
    if (hasEmpty && !_emptyConfirmation) {
      setState(() {
        _emptyConfirmation = true;
        _error = null;
      });
      return;
    }
    setState(() => _saving = true);
    final now = DateTime.now();
    final id = widget.existing?.id.isNotEmpty == true
        ? widget.existing!.id
        : 'temporary-feeding-${FFAppState().nextTemporaryFeedingScheduleId}';
    final orderedRounds = _nutritionRounds
        .where((definition) => _selectedRounds.contains(definition.$1))
        .map((definition) => _nutritionCopyRound(_rounds[definition.$1]!))
        .toList();
    Navigator.of(context).pop(
      TemporaryFeedingScheduleDataStruct(
        id: id,
        stableId: widget.stableId,
        horseId: widget.horseId,
        startDate: _nutritionDay(_startDate!),
        endDate: _nutritionDay(_endDate!),
        affectedRoundIds: _nutritionRounds
            .where((entry) => _selectedRounds.contains(entry.$1))
            .map((entry) => entry.$1)
            .toList(),
        roundSnapshots: orderedRounds,
        reason: _reason.text.trim(),
        note: _note.text.trim(),
        schemaVersion: 1,
        createdAt: widget.existing?.createdAt ?? now,
        updatedAt: now,
      ),
    );
  }

  String? _findConflict() {
    final start = _nutritionDay(_startDate!);
    final end = _nutritionDay(_endDate!);
    for (final schedule in widget.allSchedules) {
      if (schedule.id == widget.existing?.id) continue;
      if (schedule.horseId != widget.horseId ||
          schedule.stableId != widget.stableId ||
          schedule.startDate == null ||
          schedule.endDate == null) {
        continue;
      }
      final otherStart = _nutritionDay(schedule.startDate!);
      final otherEnd = _nutritionDay(schedule.endDate!);
      final overlapsDate =
          !end.isBefore(otherStart) && !start.isAfter(otherEnd);
      if (!overlapsDate) continue;
      final shared = _selectedRounds
          .where(schedule.affectedRoundIds.contains)
          .toList();
      if (shared.isEmpty) continue;
      final overlapStart = start.isAfter(otherStart) ? start : otherStart;
      final overlapEnd = end.isBefore(otherEnd) ? end : otherEnd;
      return 'Dit schema conflicteert met '
          '${_nutritionRangeLabel(schedule.startDate, schedule.endDate)}. '
          'Overlapping: ${_nutritionRangeLabel(overlapStart, overlapEnd)} '
          'voor ${shared.map(_nutritionRoundLabel).join(', ')}.';
    }
    return null;
  }
}
''';

Future<void> main(List<String> args) async {
  final options = _parseCliOptions(args);
  try {
    await flutterFlowAI(
      buildAvarynPhase4A,
      apiKey: options.apiKey,
      baseUrl: options.baseUrl,
      projectName: options.projectName,
      projectId: options.projectId,
      findOrCreate: options.findOrCreate,
      allowNewProject: options.allowNewProject,
      dryRun: options.dryRun,
      commitMessage: options.commitMessage,
    );
  } catch (error) {
    stderr.writeln('Error: ${formatFlutterFlowAIError(error)}');
    exit(1);
  }
}

const bool _agendaFunctionCheckpointOnly = false;
const bool _nutritionCustomCodeCheckpointOnly = false;
const bool _phase4ASchemaCheckpointOnly = true;

String _loadPhase4AAccountRuntimeWidgetCode() {
  final sourceFile = File.fromUri(
    Platform.script.resolve('avaryn_account_runtime.dart'),
  );
  if (!sourceFile.existsSync()) {
    throw StateError(
      'Missing Phase 4A custom-widget source: ${sourceFile.path}',
    );
  }
  return sourceFile
      .readAsLinesSync()
      .map(
        (line) =>
            line.contains(
                  "package:flutterflow_generated/backend/schema/structs/index.dart",
                )
                ? "import '/backend/schema/structs/index.dart';"
                : line.contains('package:flutterflow_generated/app_state.dart')
                ? "import '/app_state.dart';"
                : line.contains(
                  'package:flutterflow_generated/flutter_flow/flutter_flow_theme.dart',
                )
                ? "import '/flutter_flow/flutter_flow_theme.dart';"
                : line.contains(
                  'package:flutterflow_generated/flutter_flow/flutter_flow_util.dart',
                )
                ? "import '/flutter_flow/flutter_flow_util.dart';"
                : line,
      )
      .where((line) => !line.contains('package:flutterflow_generated/'))
      .join('\n');
}

String _loadDailyFeedingRuntimeWidgetCode() {
  final sourceFile = File.fromUri(
    Platform.script.resolve('avaryn_daily_feeding_runtime.dart'),
  );
  if (!sourceFile.existsSync()) {
    throw StateError(
      'Missing Phase 2 custom-widget source: ${sourceFile.path}',
    );
  }
  return sourceFile
      .readAsLinesSync()
      .map(
        (line) =>
            line.contains('package:flutterflow_generated/app_state.dart')
                ? "import '/app_state.dart';"
                : line,
      )
      .where((line) => !line.contains('package:flutterflow_generated/'))
      .join('\n');
}

/// Adds the persisted nutrition data foundation without changing existing
/// horse records or rebuilding the local persistence layer.
///
/// FlutterFlow regenerates typed struct handles after this checkpoint. The
/// nutrition page, shared editor and resolver are applied in the next run.
void buildHorseNutritionSchemaCheckpoint(App app) {
  _configureAvarynTheme(app, existingProject: true);
  app.raw((project) {
    FFIdentifier ensureStruct(
      String name,
      List<FFParameter> fields,
      String description,
    ) {
      final existing = findDataStruct(project, name: name);
      if (existing != null) return existing.identifier;
      return addDataStruct(
        project,
        name: name,
        fields: fields,
        description: description,
      );
    }

    final feedingItemId = ensureStruct(
      'FeedingItemData',
      [
        structField(
          'id',
          stringType,
          description: 'Unique stable identifier for this feeding item.',
        ),
        structField(
          'categoryId',
          stringType,
          description:
              'Stable feeding category identifier: feed, hay, supplements or medication.',
        ),
        structField(
          'name',
          stringType,
          description: 'User-entered product or feeding item name.',
        ),
        structField(
          'quantity',
          raw_types.doubleType,
          description:
              'Measured numeric quantity; ignored for unlimited quantity mode.',
        ),
        structField(
          'quantityMode',
          stringType,
          description: 'Explicit quantity mode: measured or unlimited.',
        ),
        structField(
          'unitId',
          stringType,
          description: 'Normalized feeding unit identifier.',
        ),
        structField(
          'customUnitLabel',
          stringType,
          description: 'Optional user-entered label when unitId is custom.',
        ),
        structField(
          'instruction',
          stringType,
          description: 'Optional preparation or administration instruction.',
        ),
        structField(
          'linkedProductId',
          stringType,
          description:
              'Optional future reference to an Equinutrition or stable product.',
        ),
        structField(
          'sortOrder',
          intType,
          description: 'Stable display order inside its round and category.',
        ),
      ],
      'Reusable, horse-scoped feeding item stored in a standard or temporary schedule snapshot.',
    );

    final roundSnapshotId = ensureStruct(
      'FeedingRoundSnapshotData',
      [
        structField(
          'roundId',
          stringType,
          description:
              'Stable feeding-round identifier such as morning, afternoon or evening.',
        ),
        structField(
          'items',
          raw_types.listOf(raw_types.dataStructType(feedingItemId)),
          description:
              'Self-contained items for this feeding round, including an intentionally empty list.',
        ),
      ],
      'One extensible feeding round and its ordered item snapshot.',
    );

    final feedingPlanId = ensureStruct(
      'HorseFeedingPlanData',
      [
        structField(
          'id',
          stringType,
          description: 'Unique identifier for the horse feeding plan.',
        ),
        structField(
          'stableId',
          stringType,
          description: 'Stable identifier that owns this feeding plan.',
        ),
        structField(
          'horseId',
          intType,
          description: 'Existing horse identifier that owns this feeding plan.',
        ),
        structField(
          'rounds',
          raw_types.listOf(raw_types.dataStructType(roundSnapshotId)),
          description:
              'Standard feeding rounds; supports future custom stable rounds.',
        ),
        structField(
          'schemaVersion',
          intType,
          description: 'Additive local nutrition schema version.',
        ),
        structField(
          'updatedAt',
          dateTimeType,
          description: 'Local timestamp of the most recent successful save.',
        ),
      ],
      'Persisted standard feeding schedule for one horse in one stable.',
    );

    final temporaryScheduleId = ensureStruct(
      'TemporaryFeedingScheduleData',
      [
        structField(
          'id',
          stringType,
          description: 'Unique identifier for this temporary schedule.',
        ),
        structField(
          'stableId',
          stringType,
          description: 'Stable identifier that owns this temporary schedule.',
        ),
        structField(
          'horseId',
          intType,
          description: 'Existing horse identifier affected by this schedule.',
        ),
        structField(
          'startDate',
          dateTimeType,
          description: 'Inclusive local first date of the temporary schedule.',
        ),
        structField(
          'endDate',
          dateTimeType,
          description: 'Inclusive local final date of the temporary schedule.',
        ),
        structField(
          'affectedRoundIds',
          raw_types.listOf(stringType),
          description:
              'Stable identifiers of every feeding round overridden by this schedule.',
        ),
        structField(
          'roundSnapshots',
          raw_types.listOf(raw_types.dataStructType(roundSnapshotId)),
          description:
              'Self-contained round snapshots copied and then edited as a draft.',
        ),
        structField(
          'reason',
          stringType,
          description: 'Optional user-entered reason for the temporary change.',
        ),
        structField(
          'note',
          stringType,
          description: 'Optional user-entered note for the temporary change.',
        ),
        structField(
          'schemaVersion',
          intType,
          description: 'Additive local nutrition schema version.',
        ),
        structField(
          'createdAt',
          dateTimeType,
          description: 'Local timestamp when this schedule was first saved.',
        ),
        structField(
          'updatedAt',
          dateTimeType,
          description: 'Local timestamp of the most recent successful save.',
        ),
      ],
      'Date-ranged, round-specific feeding overrides stored as independent snapshots.',
    );

    ensureStruct(
      'EffectiveFeedingScheduleData',
      [
        structField(
          'sourceType',
          stringType,
          description: 'Resolution source: standard or temporary.',
        ),
        structField(
          'temporaryScheduleId',
          stringType,
          description:
              'Applicable temporary schedule identifier, empty for standard fallback.',
        ),
        structField(
          'stableId',
          stringType,
          description: 'Resolved stable identifier.',
        ),
        structField(
          'horseId',
          intType,
          description: 'Resolved horse identifier.',
        ),
        structField(
          'date',
          dateTimeType,
          description: 'Local date used for schedule resolution.',
        ),
        structField(
          'roundId',
          stringType,
          description: 'Resolved stable feeding-round identifier.',
        ),
        structField(
          'items',
          raw_types.listOf(raw_types.dataStructType(feedingItemId)),
          description:
              'Applicable round items; an empty list remains an intentional override.',
        ),
      ],
      'Immutable result of resolving one horse, local date and feeding round.',
    );

    if (findDataStructField(
          project,
          structName: 'HorseProfileData',
          fieldName: 'stableId',
        ) ==
        null) {
      addDataStructField(
        project,
        structName: 'HorseProfileData',
        fieldName: 'stableId',
        type: stringType,
        description:
            'Optional stable identifier; older local horses safely fall back to the selected local stable.',
      );
    }

    void ensureLocalState(
      String name,
      FFDataTypeV2 type,
      String description, {
      String? defaultValue,
    }) {
      if (findAppStateField(project, name: name) != null) return;
      addAppStateField(
        project,
        name: name,
        type: type,
        description: description,
        defaultValue: defaultValue,
        persisted: true,
      );
    }

    ensureLocalState(
      'currentLocalStableId',
      stringType,
      'Stable identifier for the currently selected local prototype stable.',
      defaultValue: 'local-stable',
    );
    ensureLocalState(
      'horseFeedingPlans',
      raw_types.listOf(raw_types.dataStructType(feedingPlanId)),
      'Persisted standard feeding schedules scoped by stable and horse ID.',
    );
    ensureLocalState(
      'temporaryFeedingSchedules',
      raw_types.listOf(raw_types.dataStructType(temporaryScheduleId)),
      'Persisted temporary feeding schedule snapshots scoped by stable and horse ID.',
    );
    ensureLocalState(
      'nextFeedingItemId',
      intType,
      'Monotonic local identifier source for feeding items.',
      defaultValue: '1',
    );
    ensureLocalState(
      'nextTemporaryFeedingScheduleId',
      intType,
      'Monotonic local identifier source for temporary feeding schedules.',
      defaultValue: '1',
    );
  });
}

