        structField(
          'schemaVersion',
          intType,
          description: 'Additive local Phase 2 schema version.',
        ),
      ],
      'One immutable-snapshot execution result per stable, horse, local date and round.',
    );

    void ensureState(
      String name,
      FFDataTypeV2 type,
      String description, {
      String? defaultValue,
      bool persisted = true,
    }) {
      if (findAppStateField(project, name: name) != null) return;
      addAppStateField(
        project,
        name: name,
        type: type,
        description: description,
        defaultValue: defaultValue,
        persisted: persisted,
      );
    }

    ensureState(
      'feedingRoundConfigs',
      raw_types.listOf(raw_types.dataStructType(roundConfigId)),
      'Persisted stable-scoped feeding-round times and default assignees.',
    );
    ensureState(
      'feedingAssignmentExceptions',
      raw_types.listOf(raw_types.dataStructType(assignmentExceptionId)),
      'Persisted date-specific feeding-round responsibility exceptions.',
    );
    ensureState(
      'feedingExecutionRecords',
      raw_types.listOf(raw_types.dataStructType(executionRecordId)),
      'Persisted completion and deviation results with immutable schedule snapshots.',
    );
    ensureState(
      'nextFeedingAssignmentExceptionId',
      intType,
      'Monotonic local identifier source for assignment exceptions.',
      defaultValue: '1',
    );
    ensureState(
      'nextFeedingExecutionRecordId',
      intType,
      'Monotonic local identifier source for feeding execution results.',
      defaultValue: '1',
    );
    ensureState(
      'selectedFeedingDateKey',
      stringType,
      'Transient normalized yyyy-MM-dd date used between feeding pages.',
      defaultValue: '',
      persisted: false,
    );
    ensureState(
      'selectedFeedingRoundId',
      stringType,
      'Transient feeding-round identifier used by the execution page.',
      defaultValue: 'morning',
      persisted: false,
    );
  });
}

/// Adds the shared Phase 2 responsibility and logical-record-key resolvers
/// after FlutterFlow has regenerated the typed schema handles.
void buildHorseFeedingPhaseTwoResolverCheckpoint(App app) {
  _configureAvarynTheme(app, existingProject: true);
  app.customFunction(
    'resolveFeedingResponsibleUserV1',
    args: {
      'configs': listOf(ff.Structs.feedingRoundConfigData),
      'exceptions': listOf(ff.Structs.feedingAssignmentExceptionData),
      'stableId': string,
      'date': dateTime,
      'roundId': string,
    },
    returns: ff.Structs.resolvedFeedingResponsibleData,
    code: r'''
final targetStable = (stableId ?? '').trim();
final targetRound = (roundId ?? '').trim();
final rawDate = date ?? DateTime.now();
final targetDate = DateTime(rawDate.year, rawDate.month, rawDate.day);

bool sameDay(DateTime? value) =>
    value != null &&
    value.year == targetDate.year &&
    value.month == targetDate.month &&
    value.day == targetDate.day;

final matchingExceptions =
    (exceptions ?? const <FeedingAssignmentExceptionDataStruct>[])
        .where(
          (item) =>
              item.stableId == targetStable &&
              item.roundId == targetRound &&
              sameDay(item.date),
        )
        .toList()
      ..sort((a, b) {
        final updatedOrder = (b.updatedAt ??
                DateTime.fromMillisecondsSinceEpoch(0))
            .compareTo(
          a.updatedAt ?? DateTime.fromMillisecondsSinceEpoch(0),
        );
        return updatedOrder != 0 ? updatedOrder : a.id.compareTo(b.id);
      });

if (matchingExceptions.isNotEmpty) {
  final exception = matchingExceptions.first;
  final resolved = exception.explicitlyUnassigned
      ? ''
      : exception.replacementResponsibleUserId.trim();
  return ResolvedFeedingResponsibleDataStruct(
    stableId: targetStable,
    date: targetDate,
    roundId: targetRound,
    resolvedUserId: resolved,
    source: resolved.isEmpty ? 'unassigned' : 'dateException',
    exceptionId: exception.id,
  );
}

final matchingConfigs =
    (configs ?? const <FeedingRoundConfigDataStruct>[])
        .where(
          (candidate) =>
              candidate.stableId == targetStable &&
              candidate.roundId == targetRound &&
              (!candidate.hasEnabled() || candidate.enabled),
        )
        .toList()
      ..sort(
        (a, b) =>
            (b.updatedAt ?? DateTime.fromMillisecondsSinceEpoch(0)).compareTo(
              a.updatedAt ?? DateTime.fromMillisecondsSinceEpoch(0),
            ),
      );
final config = matchingConfigs.isEmpty ? null : matchingConfigs.first;
final defaultUserId = config?.defaultResponsibleUserId.trim() ?? '';
return ResolvedFeedingResponsibleDataStruct(
  stableId: targetStable,
  date: targetDate,
  roundId: targetRound,
  resolvedUserId: defaultUserId,
  source: defaultUserId.isEmpty ? 'unassigned' : 'default',
  exceptionId: '',
);
''',
    description:
        'Resolves one stable, local date and feeding round to a date exception, default responsible user or unassigned state.',
  );

  app.customFunction(
    'feedingExecutionLogicalKeyV1',
    args: {
      'stableId': string,
      'horseId': int_,
      'date': dateTime,
      'roundId': string,
    },
    returns: string,
    code: r'''
final rawDate = date ?? DateTime.now();
final year = rawDate.year.toString().padLeft(4, '0');
final month = rawDate.month.toString().padLeft(2, '0');
final day = rawDate.day.toString().padLeft(2, '0');
return '${(stableId ?? '').trim()}|${horseId ?? 0}|'
    '$year-$month-$day|${(roundId ?? '').trim()}';
''',
    description:
        'Builds the stable, horse, local-date and round key used to prevent duplicate feeding results.',
  );
}

/// Adds the Phase 4A identity boundary without converting legacy operational
/// stable members into authenticated accounts.
///
/// The first run is deliberately schema-only. FlutterFlow regenerates the
/// typed structs before the account runtime and protected routes are applied.
void buildAvarynPhase4A(App app) {
  _configureAvarynTheme(app, existingProject: true);

  app.raw((project) {
    if (!isSupabaseActive(project)) {
      throw StateError(
        'Phase 4A requires the FlutterFlow project Supabase connection to be active.',
      );
    }

    FFIdentifier ensureStruct(
      String name,
      List<FFParameter> fields,
      String description,
    ) {
      final existing = findDataStruct(project, name: name);
      if (existing != null) return existing.identifier;
      return addDataStruct(
        project,
        name: name,
        fields: fields,
        description: description,
      );
    }

    FFIdentifier requireStruct(String name) {
      final existing = findDataStruct(project, name: name);
      if (existing == null) {
        throw StateError(
          'Phase 4A requires the existing $name operational data struct.',
        );
      }
      return existing.identifier;
    }

    final horseId = requireStruct('HorseProfileData');
    final activityId = requireStruct('ActivityData');
    final feedingPlanId = requireStruct('HorseFeedingPlanData');
    final temporaryScheduleId = requireStruct('TemporaryFeedingScheduleData');
    final roundConfigId = requireStruct('FeedingRoundConfigData');
    final assignmentId = requireStruct('FeedingAssignmentExceptionData');
    final executionId = requireStruct('FeedingExecutionRecordData');

    final profileId = ensureStruct(
      'AuthProfileData',
      [
        structField(
          'id',
          stringType,
          description: 'Immutable Supabase Auth user UUID.',
        ),
        structField(
          'firstName',
          stringType,
          description: 'Optional first name.',
        ),
        structField('lastName', stringType, description: 'Optional last name.'),
        structField(
          'displayName',
          stringType,
          description: 'Safely resolved personal display name.',
        ),
        structField(
          'avatarObjectPath',
          stringType,
          description: 'Optional auth-UUID-owned avatar object path.',
        ),
        structField(
          'phoneE164',
          stringType,
          description: 'Optional E.164 telephone number.',
        ),
        structField(
          'locale',
          stringType,
          description: 'Personal interface locale.',
        ),
        structField(
          'themeMode',
          stringType,
          description: 'Personal system, light or dark preference.',
        ),
        structField(
          'onboardingIntent',
          stringType,
          description: 'Intent only; never a stable membership or role.',
        ),
        structField(
          'onboardingCompletedAt',
          dateTimeType,
          description: 'Server timestamp for idempotent onboarding completion.',
        ),
        structField(
          'createdAt',
          dateTimeType,
          description: 'Profile creation timestamp.',
        ),
        structField(
          'updatedAt',
          dateTimeType,
          description: 'Most recent profile update timestamp.',
        ),
      ],
      'Cached personal profile owned by one immutable Supabase Auth UUID; it contains no stable role or permission.',
    );

    final localScopeId = ensureStruct(
      'LocalAccountScopeData',
      [
        structField(
          'authUserId',
          stringType,
          description:
              'Immutable Supabase Auth UUID that owns this local namespace.',
        ),
        structField(
          'horses',
          raw_types.listOf(raw_types.dataStructType(horseId)),
          description: 'Account-scoped local horse records.',
        ),
        structField(
          'selectedHorse',
          raw_types.dataStructType(horseId),
          description: 'Account-scoped currently selected horse.',
        ),
        structField(
          'selectedHorseIndex',
          intType,
          description: 'Account-scoped selected horse index.',
        ),
        structField(
          'nextHorseId',
          intType,
          description: 'Existing monotonic local horse ID source.',
        ),
        structField(
          'nextHorseIndex',
          intType,
          description: 'Existing local horse ordering source.',
        ),
        structField(
          'horseSeedVersion',
          intType,
          description: 'Legacy sample-seed guard retained per account.',
        ),
        structField(
          'passportPrototypeVersion',
          intType,
          description: 'Legacy passport migration guard retained per account.',
        ),
        structField(
          'activities',
          raw_types.listOf(raw_types.dataStructType(activityId)),
          description: 'Account-scoped local Planning activities.',
        ),
        structField(
          'nextActivityId',
          intType,
          description: 'Existing monotonic local activity ID source.',
        ),
        structField(
          'currentLocalUserId',
          stringType,
          description:
              'Legacy Phase 1–3 operational performer ID; never rewritten to the auth UUID.',
