  );
  replaceNavigation(
    ff.Pages.horsesOverviewPage,
    desktopKey: 'Container_4cl4n3tq',
    mobileKey: 'Container_by1j5ikd',
    activeTab: 'Paarden',
  );
  replaceNavigation(
    ff.Pages.orionProfilePage,
    desktopKey: 'Container_cgwsrkng',
