  );
  replaceNavigation(
    ff.Pages.feedingRoundSettingsPage,
    desktopKey: 'Container_8ik9963j',
    mobileKey: 'Container_2ewo00nv',
    activeTab: 'Vandaag',
  );

  app.raw((project) {
    configureSupabaseAuth(
      project,
      providers: const [
        FFAuthProvider.EMAIL,
        FFAuthProvider.GOOGLE,
        FFAuthProvider.APPLE,
      ],
      homePageName: 'AuthGatePage',
      signInPageName: 'AuthWelcomePage',
    );

    const protectedPages = <String>[
      'TodayDashboardPage',
      'HorsesOverviewPage',
      'OrionProfilePage',
      'HorseFormPage',
      'HorseEditPage',
      'PlanningPage',
      'ActivityFormPage',
      'ActivityDetailPage',
      'HorseNutritionPage',
      'FeedingOverviewPage',
      'FeedingRoundExecutionPage',
      'FeedingRoundSettingsPage',
      'AuthGatePage',
      'OnboardingPage',
      'PersonalProfilePage',
    ];
    const publicPages = <String>[
      'AuthWelcomePage',
      'AuthEmailPage',
      'AuthCreateAccountPage',
      'AuthLoginPage',
      'AuthVerifyEmailPage',
      'AuthForgotPasswordPage',
      'AuthResetPasswordPage',
      'AuthCallbackPage',
    ];
    for (final pageName in protectedPages) {
      setPageRequiresAuth(project, pageName: pageName, requiresAuth: true);
    }
    for (final pageName in publicPages) {
      setPageRequiresAuth(project, pageName: pageName, requiresAuth: false);
    }

    final profilePage = findPage(project, name: 'PersonalProfilePage');
    if (profilePage == null) {
      throw StateError('Expected PersonalProfilePage to be present.');
    }
    FFNode named(String name) {
      final matches = findDescendants(
        profilePage.node,
        (node) => node.name == name,
      );
      if (matches.length != 1) {
        throw StateError(
          'Expected one $name in PersonalProfilePage, found ${matches.length}.',
        );
      }
      return matches.single;
    }

    setResponsiveVisibility(
      named('PersonalProfileDesktopSideNavigation'),
      phoneHidden: true,
      tabletHidden: true,
      tabletLandscapeHidden: true,
      desktopHidden: false,
    );
    setResponsiveVisibility(
      named('PersonalProfileMobileBottomNavigation'),
      phoneHidden: false,
      tabletHidden: false,
      tabletLandscapeHidden: false,
      desktopHidden: true,
    );
  });

  assert(authGate.name == 'AuthGatePage');
  assert(welcome.name == 'AuthWelcomePage');
  assert(personalProfile.name == 'PersonalProfilePage');
}

/// Completes Phase 2 with stable-scoped round settings, date-specific staff
/// assignments, a daily overview, feed-room execution and a compact Today
/// summary. The existing Phase 1 plan and temporary-schedule resolver remain
/// the single source of truth for what every horse receives.
void buildHorseFeedingPhaseTwo(App app) {
  _configureAvarynTheme(app, existingProject: true);

  final widgetCode = _loadDailyFeedingRuntimeWidgetCode();
  app.raw((project) {
    updateCustomWidget(
      project,
      name: 'AvarynDailyFeedingRuntime',
      code: widgetCode,
      description:
          'Stable-scoped AVARYN daily feeding overview, settings and feed-room execution.',
    );
  });

  final overviewPage = app.ensurePage(
    'FeedingOverviewPage',
    route: '/voeding',
    description:
        'Daily stable feeding overview using the effective Phase 1 schedules.',
    body: _dailyFeedingPageBody(
      pageName: 'FeedingOverview',
      mode: 'overview',
      planningTarget: ff.Pages.planningPage,
    ),
  );
  final executionPage = app.ensurePage(
    'FeedingRoundExecutionPage',
    route: '/voeding/ronde',
    description:
        'Fast feed-room execution for one stable, local date and feeding round.',
    body: _dailyFeedingPageBody(
      pageName: 'FeedingRoundExecution',
      mode: 'execution',
      planningTarget: ff.Pages.planningPage,
    ),
  );
  final settingsPage = app.ensurePage(
    'FeedingRoundSettingsPage',
    route: '/voeding/instellingen',
    description:
        'Stable feeding-round times and default responsible-user settings.',
    body: _dailyFeedingPageBody(
      pageName: 'FeedingRoundSettings',
      mode: 'settings',
      planningTarget: ff.Pages.planningPage,
    ),
  );

  app.editPage(ff.Pages.todayDashboardPage, (page) {
    page.ensureInsertedBefore(
      ff.Pages.todayDashboardPage.widgets.byKey('Column_r646vnfd').single,
      CustomWidget(
        name: 'TodayFeedingDesktopCard',
        widgetName: 'AvarynDailyFeedingRuntime',
        arguments: const {'mode': 'today'},
      ),
    );
    page.ensureInsertedBefore(
      ff.Pages.todayDashboardPage.widgets.byKey('Column_5iv3rs34').single,
      CustomWidget(
        name: 'TodayFeedingMobileCard',
        widgetName: 'AvarynDailyFeedingRuntime',
        arguments: const {'mode': 'today'},
      ),
    );
  });

  app.raw((project) {
    void configureResponsivePage(String pageName, String prefix, String route) {
      final page = findPage(project, name: pageName);
      if (page == null) {
        throw StateError('Expected $pageName to be present.');
      }
      FFNode named(String name) {
        final matches = findDescendants(page.node, (node) => node.name == name);
        if (matches.length != 1) {
          throw StateError(
            'Expected one $name in $pageName, found ${matches.length}.',
          );
        }
        return matches.single;
      }

      setResponsiveVisibility(
        named('${prefix}DesktopSideNavigation'),
        phoneHidden: true,
        tabletHidden: true,
        tabletLandscapeHidden: true,
        desktopHidden: false,
      );
      setResponsiveVisibility(
        named('${prefix}MobileBottomNavigation'),
        phoneHidden: false,
        tabletHidden: false,
        tabletLandscapeHidden: false,
        desktopHidden: true,
      );
      setPageRoute(project, pageName: pageName, route: route);
    }

    configureResponsivePage(
      'FeedingOverviewPage',
      'FeedingOverview',
      '/voeding',
    );
    configureResponsivePage(
      'FeedingRoundExecutionPage',
      'FeedingRoundExecution',
      '/voeding/ronde',
    );
    configureResponsivePage(
      'FeedingRoundSettingsPage',
      'FeedingRoundSettings',
      '/voeding/instellingen',
    );
  });

  assert(overviewPage.name == 'FeedingOverviewPage');
  assert(executionPage.name == 'FeedingRoundExecutionPage');
  assert(settingsPage.name == 'FeedingRoundSettingsPage');
}

/// Builds phase one of AVARYN horse nutrition on top of the additive schema.
void buildHorseNutritionPhaseOne(App app) {
  _configureAvarynTheme(app, existingProject: true);
  final formatHorseDate = CustomFunctionHandle(
    name: 'formatHorseDateDutch',
    args: {'date': dateTime},
    returnType: string,
  );
  final horseAgeLabel = CustomFunctionHandle(
    name: 'horseAgeLabel',
    args: {'date': dateTime},
    returnType: string,
  );

  app.customFunction(
    'resolveEffectiveFeedingScheduleV1',
    args: {
      'plans': listOf(ff.Structs.horseFeedingPlanData),
      'temporarySchedules': listOf(ff.Structs.temporaryFeedingScheduleData),
      'stableId': string,
      'horseId': int_,
      'date': dateTime,
      'roundId': string,
    },
    returns: ff.Structs.effectiveFeedingScheduleData,
    code: r'''
final targetStable = (stableId ?? '').trim();
final targetHorse = horseId ?? 0;
final targetRound = (roundId ?? '').trim();
final rawDate = date ?? DateTime.now();
final targetDate = DateTime(rawDate.year, rawDate.month, rawDate.day);

DateTime day(DateTime value) =>
    DateTime(value.year, value.month, value.day);

final matchingTemporary =
    (temporarySchedules ?? const <TemporaryFeedingScheduleDataStruct>[])
        .where((schedule) {
  if (schedule.stableId != targetStable ||
      schedule.horseId != targetHorse ||
      !schedule.affectedRoundIds.contains(targetRound) ||
      schedule.startDate == null ||
      schedule.endDate == null) {
    return false;
  }
  final start = day(schedule.startDate!);
  final end = day(schedule.endDate!);
  return !targetDate.isBefore(start) && !targetDate.isAfter(end);
}).toList()
      ..sort((a, b) {
        final updatedOrder = (b.updatedAt ??
                DateTime.fromMillisecondsSinceEpoch(0))
            .compareTo(
          a.updatedAt ?? DateTime.fromMillisecondsSinceEpoch(0),
        );
        return updatedOrder != 0 ? updatedOrder : a.id.compareTo(b.id);
      });

for (final schedule in matchingTemporary) {
  FeedingRoundSnapshotDataStruct? snapshot;
  for (final candidate in schedule.roundSnapshots) {
    if (candidate.roundId == targetRound) {
      snapshot = candidate;
      break;
    }
  }
  if (snapshot == null) continue;
  return EffectiveFeedingScheduleDataStruct(
    sourceType: 'temporary',
    temporaryScheduleId: schedule.id,
    stableId: targetStable,
    horseId: targetHorse,
    date: targetDate,
    roundId: targetRound,
    items: List<FeedingItemDataStruct>.from(
      snapshot.items,
    ),
  );
}

final matchingPlans =
    (plans ?? const <HorseFeedingPlanDataStruct>[])
        .where(
          (candidate) =>
              candidate.stableId == targetStable &&
              candidate.horseId == targetHorse,
        )
        .toList()
      ..sort(
        (a, b) =>
            (b.updatedAt ?? DateTime.fromMillisecondsSinceEpoch(0)).compareTo(
              a.updatedAt ?? DateTime.fromMillisecondsSinceEpoch(0),
            ),
      );
final plan = matchingPlans.isEmpty ? null : matchingPlans.first;
FeedingRoundSnapshotDataStruct? standardRound;
for (final candidate
    in plan?.rounds ?? const <FeedingRoundSnapshotDataStruct>[]) {
  if (candidate.roundId == targetRound) {
    standardRound = candidate;
    break;
  }
}
return EffectiveFeedingScheduleDataStruct(
  sourceType: 'standard',
  temporaryScheduleId: '',
  stableId: targetStable,
  horseId: targetHorse,
  date: targetDate,
  roundId: targetRound,
  items: List<FeedingItemDataStruct>.from(
    standardRound?.items ?? const <FeedingItemDataStruct>[],
  ),
);
''',
    description:
        'Resolves one horse, local date and feeding round to a temporary snapshot or standard fallback.',
  );

  app.raw((project) {
    final existing = findCustomWidget(
      project,
      name: 'AvarynHorseNutritionRuntime',
    );
    if (existing == null) {
      addCustomWidget(
        project,
        name: 'AvarynHorseNutritionRuntime',
        code: _horseNutritionRuntimeWidgetCode,
        description:
            'Responsive horse feeding plan editor with standard and temporary schedule snapshots.',
      );
    } else {
      updateCustomWidget(
        project,
        name: 'AvarynHorseNutritionRuntime',
        code: _horseNutritionRuntimeWidgetCode,
        description:
            'Responsive horse feeding plan editor with standard and temporary schedule snapshots.',
      );
    }
  });

  if (_nutritionCustomCodeCheckpointOnly) return;

  final nutritionPage = app.ensurePage(
    'HorseNutritionPage',
    route: '/paarden/voeding',
    description:
        'Horse-scoped AVARYN standard and temporary feeding schedule management.',
    body: _horseNutritionPageBody(planningTarget: ff.Pages.planningPage),
  );

  app.editPage(ff.Pages.orionProfilePage, (page) {
    page.ensureReplaced(
      ff.Pages.orionProfilePage.widgets
          .byPath('OrionProfilePage.body[0]')
          .single,
      _dataDrivenHorseDetailPageBody(
        profileSectionState:
            ff.Pages.orionProfilePage.state.activeProfileSection,
        formTarget: ff.Pages.horseEditPage,
        planningTarget: ff.Pages.planningPage,
        nutritionTarget: nutritionPage,
        formatHorseDate: formatHorseDate,
        horseAgeLabel: horseAgeLabel,
      ),
    );
  });

  // Replacing the responsive shell creates fresh nodes, so reapply the
  // mutually exclusive desktop/mobile breakpoint metadata to those nodes.
  _applyHorseDetailResponsiveVisibility(app);

  app.raw((project) {
    final nutrition = findPage(project, name: 'HorseNutritionPage');
    if (nutrition == null) {
      throw StateError('Expected HorseNutritionPage to be present.');
    }
    FFNode named(String name) {
      final matches = findDescendants(
        nutrition.node,
        (node) => node.name == name,
      );
      if (matches.length != 1) {
        throw StateError(
          'Expected one $name in HorseNutritionPage, found ${matches.length}.',
        );
      }
      return matches.single;
    }

    setResponsiveVisibility(
      named('HorseNutritionDesktopSideNavigation'),
      phoneHidden: true,
      tabletHidden: true,
      tabletLandscapeHidden: true,
      desktopHidden: false,
    );
    setResponsiveVisibility(
      named('HorseNutritionMobileBottomNavigation'),
      phoneHidden: false,
      tabletHidden: false,
      tabletLandscapeHidden: false,
      desktopHidden: true,
    );
    updatePage(
      project,
      name: 'HorseNutritionPage',
      description:
          'Horse-scoped AVARYN standard and temporary feeding schedule management.',
    );
    setPageRoute(
      project,
      pageName: 'HorseNutritionPage',
      route: '/paarden/voeding',
    );
  });
}

/// Adds only the reusable Agenda picker inputs and local draft fields.
///
/// FlutterFlow's typed SDK exposes newly added component state after a context
/// refresh, so the visual repair is intentionally applied in the next
/// checkpoint.
void buildAgendaPickerStateCheckpoint(App app) {
  final agendaPicker = ff.Components.avarynAgendaPickerSheet;
  app.editComponentState(agendaPicker, (state) {
    state.ensureField('agendaMode', string.withDefault('overview'));
    state.ensureField('agendaRangeStep', string.withDefault('start'));
    state.ensureField('agendaDraftStartDate', dateTime);
    state.ensureField('agendaDraftEndDate', dateTime);
    state.ensureField('agendaDraftStartTime', dateTime);
    state.ensureField('agendaDraftEndTime', dateTime);
    state.ensureField('agendaDisplayedMonth', dateTime);
    state.ensureField('agendaTimeTarget', string.withDefault('start'));
    state.ensureField('agendaTimeDraft', dateTime);
  });
  app.editPageState(ff.Pages.activityFormPage, (state) {
    state.ensureField('agendaOpening', bool_.withDefault(false));
  });
}

/// Extends the existing persisted ActivityData schema in place.
///
/// This is intentionally a schema-only checkpoint: the next run refreshes the
/// typed project SDK so the UI refinement can use the newly generated fields
/// without replacing or resetting existing local activity records.
void buildTargetedActivitySchemaExtension(App app) {
  app.raw((project) {
    void ensureActivityField(
      String name,
      FFDataTypeV2 type,
      String description, {
      bool isList = false,
    }) {
      if (findDataStructField(
            project,
            structName: 'ActivityData',
            fieldName: name,
          ) !=
          null) {
        return;
      }
      addDataStructField(
        project,
        structName: 'ActivityData',
        fieldName: name,
        type: type,
        description: description,
        isList: isList,
      );
    }

    ensureActivityField(
      'stableId',
      stringType,
      'Stable identifier when a stable context is available.',
    );
    ensureActivityField(
      'customTitle',
      stringType,
      'User-entered title used only for the Overig activity type.',
    );
    ensureActivityField(
      'assigneeUserIds',
      stringType,
      'Stable user identifiers assigned to this activity.',
      isList: true,
    );
    ensureActivityField(
      'startDate',
      dateTimeType,
      'Typed local start date for scheduling and agenda display.',
    );
    ensureActivityField(
      'endDate',
      dateTimeType,
      'Optional typed local end date for multi-day activities.',
    );
    ensureActivityField(
      'startTime',
      dateTimeType,
      'Optional typed local start time.',
    );
    ensureActivityField(
      'endTime',
      dateTimeType,
      'Optional typed local end time.',
    );
    ensureActivityField(
      'allDay',
      boolType,
      'Whether the activity occupies its selected calendar day or range.',
    );
    ensureActivityField(
      'durationMinutes',
      intType,
      'Optional duration used by care activities and schedule calculations.',
    );
    ensureActivityField(
      'locationType',
      stringType,
      'Semantic location choice such as Op stal or Op locatie.',
    );
    ensureActivityField(
      'locationName',
      stringType,
      'Optional external location or competition venue.',
    );
    ensureActivityField(
      'serviceProviderName',
      stringType,
      'Optional farrier or veterinarian name.',
    );
    ensureActivityField(
      'completionStatus',
      stringType,
      'Completion state stored independently from the legacy boolean field.',
    );

    void ensureDraftState(
      String name,
      FFDataTypeV2 type,
      String description, {
      String? defaultValue,
      bool persisted = false,
    }) {
      if (findAppStateField(project, name: name) != null) return;
      addAppStateField(
        project,
        name: name,
        type: type,
        description: description,
        defaultValue: defaultValue,
        persisted: persisted,
      );
    }

    ensureDraftState(
      'currentLocalUserId',
      stringType,
      'Stable identifier for the current locally registered prototype user.',
      defaultValue: 'local-current-user',
      persisted: true,
    );
    ensureDraftState(
      'activityDraftAssigneeUserIds',
      FFDataTypeV2(listType: stringType),
      'Transient assignee selection shared with the reusable picker.',
    );
    ensureDraftState(
      'activityDraftStartDate',
      dateTimeType,
      'Transient agenda start date shared with the reusable picker.',
    );
    ensureDraftState(
      'activityDraftEndDate',
      dateTimeType,
      'Transient agenda end date shared with the reusable picker.',
    );
    ensureDraftState(
      'activityDraftStartTime',
      dateTimeType,
      'Transient agenda start time shared with the reusable picker.',
    );
    ensureDraftState(
      'activityDraftEndTime',
      dateTimeType,
      'Transient agenda end time shared with the reusable picker.',
    );
    ensureDraftState(
      'activityDraftAllDay',
      boolType,
      'Transient all-day selection shared with the reusable picker.',
      defaultValue: 'false',
    );
    ensureDraftState(
      'activityDraftDurationMinutes',
      intType,
      'Transient duration in minutes for the activity form.',
      defaultValue: '0',
    );
    ensureDraftState(
      'activityDraftLocationType',
      stringType,
      'Transient semantic location selection for the activity form.',
    );
    ensureDraftState(
      'activityDraftPendingType',
      stringType,
      'Transient pending activity type used by the loss confirmation flow.',
    );
    ensureDraftState(
      'activitySaveInProgress',
      boolType,
      'Transient repeat-tap guard for activity saves.',
      defaultValue: 'false',
    );
  });
}

/// Refines the existing Planning flow against the extended ActivityData
/// schema without creating duplicate pages, models or persisted lists.
void buildTargetedActivityFlowRefinement(App app) {
  _configureAvarynTheme(app, existingProject: true);
  final activity = ff.Structs.activityData;

  // Normalize the previously double-encoded Planning literals before the
  // idempotent typed declarations below are resolved.
  app.raw((project) {
    for (final name in const <String>[
      'activityDisplayTitleV2',
      'activityDraftDisplayTitleV2',
      'activityDateRangeLabelV2',
      'activityScheduleLabelV2',
      'activityDraftAssigneeLabelV2',
      'activityMetaLabelV2',
      'agendaMarkedDatesLabelV2',
      'activityFormValidationV2',
      'activityConflictWarningV2',
    ]) {
      final existing = findCustomFunction(project, name: name);
      if (existing == null) continue;
      final normalized = existing.code
          .replaceAll('Ã‚Â·', '·')
          .replaceAll('Ã¢â‚¬â€œ', '–')
          .replaceAll('ÃƒÂ©ÃƒÂ©n', 'één')
          .replaceAll('Ã¢â‚¬Â¢', '');
      if (normalized != existing.code) {
        updateCustomFunction(project, name: name, code: normalized);
      }
    }
  });

  final defaultAssigneeIds = app.customFunction(
    'defaultAssigneeIdsV2',
    args: {'currentUserId': string},
    returns: listOf(string),
    code: r'''
final id = (currentUserId ?? '').trim();
return <String>[id.isEmpty ? 'local-current-user' : id];
''',
    description:
        'Returns only the current locally registered user until stable membership is connected.',
  );
  final effectiveAssigneeIds = app.customFunction(
    'activityEffectiveAssigneeIdsV2',
    args: {'activity': activity, 'currentUserId': string},
    returns: listOf(string),
    code: r'''
final existing = activity?.assigneeUserIds ?? const <String>[];
if (existing.isNotEmpty) return List<String>.from(existing);
final id = (currentUserId ?? '').trim();
return <String>[id.isEmpty ? 'local-current-user' : id];
''',
    description:
        'Preserves stored assignees and migrates previous activities to the current local user on edit.',
  );
  final locationNameFromDraft = app.customFunction(
    'activityLocationNameFromDraftV2',
    args: {
      'activityType': string,
      'locationType': string,
      'trainingLocation': string,
      'competitionLocation': string,
      'otherLocation': string,
    },
    returns: string,
    code: r'''
final type = (activityType ?? '').trim();
if (type == 'Training') {
  return locationType == 'Op locatie'
      ? (trainingLocation ?? '').trim()
      : '';
}
if (type == 'Wedstrijd') return (competitionLocation ?? '').trim();
if (type == 'Overig') return (otherLocation ?? '').trim();
return '';
''',
    description:
        'Keeps only the location field that belongs to the selected activity type.',
  );
  final providerFromDraft = app.customFunction(
    'activityProviderFromDraftV2',
    args: {'activityType': string, 'providerName': string},
    returns: string,
    code: r'''
final type = (activityType ?? '').trim();
return type == 'Hoefsmid' || type == 'Dierenarts'
    ? (providerName ?? '').trim()
    : '';
''',
    description:
        'Keeps a service-provider name only for farrier and veterinarian activities.',
  );
  final notesFromDraft = app.customFunction(
    'activityNotesFromDraftV2',
    args: {'activityType': string, 'notes': string},
    returns: string,
    code: r'''
return (activityType ?? '').trim() == 'Verzorging'
    ? ''
    : (notes ?? '').trim();
''',
    description: 'Ensures care activities do not retain a hidden notes value.',
  );
  final customTitleFromDraft = app.customFunction(
    'activityCustomTitleFromDraftV2',
    args: {'activityType': string, 'customTitle': string},
    returns: string,
    code: r'''
return (activityType ?? '').trim() == 'Overig'
    ? (customTitle ?? '').trim()
    : '';
''',
    description:
        'Keeps a custom title only for the flexible Overig activity type.',
  );
  final locationTypeFromDraft = app.customFunction(
    'activityLocationTypeFromDraftV2',
    args: {'activityType': string, 'locationType': string},
    returns: string,
    code: r'''
return (activityType ?? '').trim() == 'Training'
    ? (locationType ?? '').trim()
    : '';
''',
    description:
        'Keeps the semantic stable/external location choice only for training.',
  );
  final endDateFromDraft = app.customFunction(
    'activityEndDateFromDraftV2',
    args: {'activityType': string, 'startDate': dateTime, 'endDate': dateTime},
    returns: dateTime,
    code: r'''
return (activityType ?? '').trim() == 'Wedstrijd'
    ? (endDate ?? startDate)
    : startDate;
''',
    description:
        'Uses an inclusive range only for competitions and a single date otherwise.',
  );
  final allDayFromDraft = app.customFunction(
    'activityAllDayFromDraftV2',
    args: {'activityType': string, 'allDay': bool_},
    returns: bool_,
    code: r'''
final type = (activityType ?? '').trim();
return (type == 'Wedstrijd' || type == 'Overig') && (allDay ?? false);
''',
    description:
        'Keeps all-day state only for competition and flexible activities.',
  );
  final endTimeFromDraft = CustomFunctionHandle(
    name: 'activityEndTimeFromDraftV2',
    args: {
      'activityType': string,
      'startTime': dateTime,
      'endTime': dateTime,
      'allDay': bool_,
      'durationMinutes': int_,
    },
    returnType: dateTime,
  );
  final effectiveCustomTitle = app.customFunction(
    'activityEffectiveCustomTitleV2',
    args: {'activity': activity},
    returns: string,
    code: r'''
final custom = activity?.customTitle.trim() ?? '';
if (custom.isNotEmpty) return custom;
return activity?.activityType == 'Overig' ? activity?.title.trim() ?? '' : '';
''',
    description:
        'Migrates the previous generic title into Overig when editing an older activity.',
  );
  final durationChoiceForMinutes = app.customFunction(
    'activityDurationChoiceForMinutesV2',
    args: {'minutes': int_},
    returns: string,
    code: r'''
switch (minutes ?? 0) {
  case 15:
    return '15 minuten';
  case 30:
    return '30 minuten';
  case 45:
    return '45 minuten';
  case 60:
    return '1 uur';
  case 90:
    return '1,5 uur';
  case 120:
    return '2 uur';
  default:
    return (minutes ?? 0) > 0 ? 'Aangepast' : '';
}
''',
    description:
        'Maps stored duration minutes back to the practical care-duration selector.',
  );
  final durationCustomText = app.customFunction(
    'activityDurationCustomTextV2',
    args: {'minutes': int_},
    returns: string,
    code: r'''
final value = minutes ?? 0;
return const <int>[15, 30, 45, 60, 90, 120].contains(value) || value <= 0
    ? ''
    : value.toString();
''',
    description:
        'Returns a custom care duration only when it is not one of the preset choices.',
  );
  app.customFunction(
    'activityTypeIsServiceV2',
    args: {'activityType': string},
    returns: bool_,
    code: r'''
final type = (activityType ?? '').trim();
return type == 'Hoefsmid' || type == 'Dierenarts';
''',
    description:
        'Reports whether the selected activity uses a named equine service provider.',
  );
  app.customFunction(
    'activityTypeSupportsAllDayV2',
    args: {'activityType': string},
    returns: bool_,
    code: r'''
final type = (activityType ?? '').trim();
return type == 'Wedstrijd' || type == 'Overig';
''',
    description:
        'Reports whether the selected type supports an explicit all-day interval.',
  );
  app.customFunction(
    'activityTypeShowsNotesV2',
    args: {'activityType': string},
    returns: bool_,
    code: r'''
final type = (activityType ?? '').trim();
return type.isNotEmpty && type != 'Verzorging';
''',
    description:
        'Keeps notes hidden only for the intentionally compact care activity.',
  );
  app.customFunction(
    'activityTypeUsesEndTimeV2',
    args: {'activityType': string, 'allDay': bool_},
    returns: bool_,
    code: r'''
if (allDay ?? false) return false;
final type = (activityType ?? '').trim();
return type == 'Training' || type == 'Wedstrijd' || type == 'Overig';
''',
    description:
        'Reports whether the agenda picker should expose an editable end time.',
  );
  final activityDisplayTitle = CustomFunctionHandle(
    name: 'activityDisplayTitleV2',
    args: {'activity': activity},
    returnType: string,
  );
  final activityDraftTitle = CustomFunctionHandle(
    name: 'activityDraftDisplayTitleV2',
    args: {
      'activityType': string,
      'customTitle': string,
      'serviceProviderName': string,
    },
    returnType: string,
  );
  final effectiveStartDate = app.customFunction(
    'activityEffectiveStartDateV2',
    args: {'activity': activity},
    returns: dateTime,
    code: 'return activity?.startDate ?? activity?.date;',
    description:
        'Reads a typed start date with a safe fallback to the previous date field.',
  );
  final effectiveEndDate = app.customFunction(
    'activityEffectiveEndDateV2',
    args: {'activity': activity},
    returns: dateTime,
    code: 'return activity?.endDate ?? activity?.startDate ?? activity?.date;',
    description:
        'Reads a typed end date with backwards-compatible single-day fallbacks.',
  );
  final effectiveStartTime = app.customFunction(
    'activityEffectiveStartTimeV2',
    args: {'activity': activity},
    returns: dateTime,
    code: 'return activity?.startTime ?? activity?.time;',
    description:
        'Reads a typed start time with a safe fallback to the previous time field.',
  );
  final effectiveCompletion = app.customFunction(
    'activityIsCompletedV2',
    args: {'activity': activity},
    returns: bool_,
    code: r'''
final status = activity?.completionStatus.trim().toLowerCase() ?? '';
return status == 'completed' || status == 'voltooid' ||
    (activity?.isCompleted ?? false);
''',
    description:
        'Reads completion from the new status or the previous boolean field.',
  );
  app.customFunction(
    'activityCompletionStatusFromBoolV2',
    args: {'completed': bool_},
    returns: string,
    code: r'''
return (completed ?? false) ? 'completed' : 'open';
''',
    description:
        'Keeps the typed completion status synchronized with the legacy boolean.',
  );
  final activityDateLabel = CustomFunctionHandle(
    name: 'activityDateRangeLabelV2',
    args: {'activity': activity},
    returnType: string,
  );
  final activityScheduleLabel = CustomFunctionHandle(
    name: 'activityScheduleLabelV2',
    args: {'activity': activity},
    returnType: string,
  );
  final activityAssigneeLabel = app.customFunction(
    'activityAssigneeLabelV2',
    args: {'activity': activity, 'currentUserId': string},
    returns: string,
    code: r'''
final ids = activity?.assigneeUserIds ?? const <String>[];
if (ids.isEmpty) return 'Nog niet toegewezen';
final current = (currentUserId ?? '').trim();
final activeId = current.isEmpty ? 'local-current-user' : current;
final hasCurrent = ids.contains(activeId);
final unavailable = ids.where((id) => id != activeId).length;
if (hasCurrent && unavailable == 0) return 'Jij';
if (hasCurrent) return 'Jij + $unavailable niet meer actief';
return unavailable == 1
    ? '1 persoon niet meer actief'
    : '$unavailable personen niet meer actief';
''',
    description:
        'Shows the current local user and safely labels unavailable historical assignees.',
  );
  final draftAssigneeLabel = CustomFunctionHandle(
    name: 'activityDraftAssigneeLabelV2',
    args: {'assigneeUserIds': listOf(string), 'currentUserId': string},
    returnType: string,
  );
  final activityMetaLabel = CustomFunctionHandle(
    name: 'activityMetaLabelV2',
    args: {'activity': activity, 'currentUserId': string},
    returnType: string,
  );
  final sortedActivities = app.customFunction(
    'sortedActivitiesV2',
    args: {'activities': listOf(activity)},
    returns: listOf(activity),
    code: r'''
final result = List<ActivityDataStruct>.from(
  activities ?? const <ActivityDataStruct>[],
);
DateTime? dateOf(ActivityDataStruct item) => item.startDate ?? item.date;
DateTime? timeOf(ActivityDataStruct item) => item.startTime ?? item.time;
result.sort((a, b) {
  final ad = dateOf(a);
  final bd = dateOf(b);
  if (ad == null && bd == null) return a.id.compareTo(b.id);
  if (ad == null) return 1;
  if (bd == null) return -1;
  final dateCompare = DateTime(ad.year, ad.month, ad.day)
      .compareTo(DateTime(bd.year, bd.month, bd.day));
  if (dateCompare != 0) return dateCompare;
  final at = timeOf(a);
  final bt = timeOf(b);
  if (at == null && bt == null) return a.id.compareTo(b.id);
  if (at == null) return 1;
  if (bt == null) return -1;
  final timeCompare =
      (at.hour * 60 + at.minute).compareTo(bt.hour * 60 + bt.minute);
  return timeCompare != 0 ? timeCompare : a.id.compareTo(b.id);
});
return result;
''',
    description:
        'Sorts both previous and extended activities by their effective local start.',
  );
  final todayActivities = app.customFunction(
    'todayActivitiesV2',
    args: {'activities': listOf(activity)},
    returns: listOf(activity),
    code: r'''
final now = DateTime.now();
final today = DateTime(now.year, now.month, now.day);
final result = <ActivityDataStruct>[];
for (final item in activities ?? const <ActivityDataStruct>[]) {
  final rawStart = item.startDate ?? item.date;
  if (rawStart == null) continue;
  final rawEnd = item.endDate ?? rawStart;
  final start = DateTime(rawStart.year, rawStart.month, rawStart.day);
  final end = DateTime(rawEnd.year, rawEnd.month, rawEnd.day);
  if (!today.isBefore(start) && !today.isAfter(end)) result.add(item);
}
result.sort((a, b) {
  final at = a.startTime ?? a.time;
  final bt = b.startTime ?? b.time;
  if (at == null && bt == null) return a.id.compareTo(b.id);
  if (at == null) return 1;
  if (bt == null) return -1;
  return (at.hour * 60 + at.minute)
      .compareTo(bt.hour * 60 + bt.minute);
});
return result;
''',
