      endDate.day,
      endTime.hour,
      endTime.minute,
    );
    return endMoment.isAfter(startMoment);
  case 'Overig':
    if ((customTitle ?? '').trim().isEmpty) return false;
    if (allDay ?? false) return true;
    return startTime != null &&
        endTime != null &&
        minutes(endTime) > minutes(startTime);
}
