  return '${value.hour.toString().padLeft(2, '0')}:${value.minute.toString().padLeft(2, '0')}';
}
return matches.take(4).map((item) {
  final time = clock(item);
  return time.isEmpty ? title(item) : '$time - ${title(item)}';
}).join('\n');
''',
