  final discardSheetProject = ff.Components.activityDiscardSheetV2;
  final deleteSheetProject = ff.Components.activityDeleteSheetV2;
  final refinedActivityCard = ff.Components.avarynActivityCardV2;
  final agendaPickerProject = ff.Components.avarynAgendaPickerSheet;
  final assigneePickerProject = ff.Components.activityAssigneePickerSheet;
  final typeChangeSheetProject = ff.Components.activityTypeChangeSheet;
  final conflictSheetProject = ff.Components.activityConflictSheet;

  // Modal actions currently require the local declaration-handle shape. These
  // references point at existing components by name but are not registered as
  // new declarations, so the project remains free of duplicate components.
  ComponentHandle modalHandle(
    String name, {
    Map<String, DslType> params = const {},
  }) => ComponentHandle(
    ComponentDeclaration(
      name: name,
      params: params,
      body: Container(name: '${name}ModalReference'),
    ),
  );
  final horsePicker = modalHandle('ActivityHorsePickerSheetV2');
  final discardSheet = modalHandle('ActivityDiscardSheetV2');
  final deleteSheet = modalHandle(
    'ActivityDeleteSheetV2',
    params: {'title': string.withDefault('Activiteit')},
  );
  final agendaPicker = modalHandle(
    'AvarynAgendaPickerSheet',
    params: {
      'activityType': string.withDefault(''),
      'initialMode': string.withDefault('overview'),
    },
  );
  final assigneePicker = modalHandle('ActivityAssigneePickerSheet');
  final typeChangeSheet = modalHandle(
    'ActivityTypeChangeSheet',
    params: {'nextType': string.withDefault('')},
  );
  final conflictSheet = modalHandle(
    'ActivityConflictSheet',
    params: {
      'message': string.withDefault(''),
      'editMode': bool_.withDefault(false),
      'pendingActivity': activity.withDefault(null),
    },
  );
  assert(
    <Object>[
          horsePicker,
          discardSheet,
          assigneePicker,
          typeChangeSheet,
        ].length ==
        4,
  );

  app.editComponent(horsePickerProject, (component) {
    component.ensureReplaced(
      horsePickerProject.widgets
          .byPath('ActivityHorsePickerSheetV2.children[0]')
          .single,
      _activityHorsePickerSheet(
        activityHorseName: CustomFunctionHandle(
          name: 'activityHorseName',
          args: {
            'horses': listOf(ff.Structs.horseProfileData),
            'horseId': int_,
          },
          returnType: string,
        ),
        horseListIsEmpty: CustomFunctionHandle(
          name: 'horseListIsEmpty',
          args: {'horses': listOf(ff.Structs.horseProfileData)},
          returnType: bool_,
        ),
      ),
    );
  });
  app.editComponent(discardSheetProject, (component) {
    component.ensureReplaced(
      discardSheetProject.widgets
          .byPath('ActivityDiscardSheetV2.children[0]')
          .single,
      _activityDiscardSheetV2(),
    );
  });
  app.editComponent(deleteSheetProject, (component) {
    component.ensureReplaced(
      deleteSheetProject.widgets
          .byPath('ActivityDeleteSheetV2.children[0]')
          .single,
      _activityDeleteSheetV2(),
    );
  });
  app.editComponent(refinedActivityCard, (component) {
    component.ensureReplaced(
      refinedActivityCard.widgets
          .byPath('AvarynActivityCardV2.children[0]')
          .single,
      _activityCardBodyV2(),
    );
  });
  app.editComponentParams(agendaPickerProject, (params) {
    params.ensureParam(
      'initialMode',
      string.withDefault('overview'),
      description:
          'Initial agenda mode: overview, date, endDate, startTime or endTime.',
    );
  });
  app.editComponentState(agendaPickerProject, (state) {
    state.ensureField('agendaMode', string.withDefault('overview'));
    state.ensureField('agendaRangeStep', string.withDefault('start'));
    state.ensureField('agendaDraftStartDate', dateTime);
    state.ensureField('agendaDraftEndDate', dateTime);
    state.ensureField('agendaDraftStartTime', dateTime);
    state.ensureField('agendaDraftEndTime', dateTime);
    state.ensureField('agendaDisplayedMonth', dateTime);
    state.ensureField('agendaTimeTarget', string.withDefault('start'));
    state.ensureField('agendaTimeDraft', dateTime);
  });
  app.editComponent(agendaPickerProject, (component) {
    component.ensureReplaced(
      agendaPickerProject.widgets
          .byPath('AvarynAgendaPickerSheet.children[0]')
          .single,
      CustomWidget(
        widgetName: 'AvarynAgendaPickerRuntime',
        arguments: {
          'activityType': Param(
            ff.Components.avarynAgendaPickerSheet.params.activityType,
          ),
          'initialMode': Param('initialMode'),
        },
        name: 'AvarynAgendaPickerRuntime',
      ),
    );
  });
  app.editComponent(assigneePickerProject, (component) {
    component.ensureReplaced(
      assigneePickerProject.widgets
          .byPath('ActivityAssigneePickerSheet.children[0]')
          .single,
      _activityAssigneePickerSheetV2(defaultAssigneeIds),
    );
  });
  app.editComponent(typeChangeSheetProject, (component) {
    component.ensureReplaced(
      typeChangeSheetProject.widgets
          .byPath('ActivityTypeChangeSheet.children[0]')
          .single,
      _activityTypeChangeSheetV2(),
    );
  });
  app.editComponent(conflictSheetProject, (component) {
    component.ensureReplaced(
      conflictSheetProject.widgets
          .byPath('ActivityConflictSheet.children[0]')
          .single,
      _activityConflictSheetV2(activity),
    );
  });

  app.editPageState(ff.Pages.activityFormPage, (state) {
    state.ensureField('formValidationMessage', string.withDefault(''));
    state.ensureField('formDurationChoice', string.withDefault(''));
    state.ensureField('agendaOpening', bool_.withDefault(false));
  });
  app.editPage(ff.Pages.planningPage, (page) {
    page.ensureReplaced(
      ff.Pages.planningPage.widgets.byPath('PlanningPage.body[0]').single,
      _planningPageBodyV3(),
    );
  });
  app.editPage(ff.Pages.activityFormPage, (page) {
    page.update(
      ff.Pages.activityFormPage.widgets.byKey('Text_gnzhh4wv').single,
      (patch) => patch.text('Activiteit opslaan...'),
    );
    page.ensureReplaced(
      ff.Pages.activityFormPage.widgets
          .byPath(
            'ActivityFormPage.body[0].children[1].children[0].children[0].children[8].children[2]',
          )
          .single,
      _activityAgendaFormCardV3(agendaPicker: agendaPicker),
    );
    page.ensureActions(
      ff.Pages.activityFormPage.widgets
          .byPath(
            'ActivityFormPage.body[0].children[2].children[0].children[1]',
          )
          .single,
      triggerType: FFActionTriggerType.ON_TAP,
      actions: _activitySaveActionsV2(
        activity: activity,
        conflictSheet: conflictSheet,
        activityFormValidation: activityFormIsValid,
        activityValidationMessage: activityFormValidation,
        activityConflictWarning: activityHasConflict,
        activityConflictMessage: activityConflictWarning,
        durationMinutes: durationMinutes,
        activityDraftTitle: activityDraftTitle,
        locationNameFromDraft: locationNameFromDraft,
        providerFromDraft: providerFromDraft,
        notesFromDraft: notesFromDraft,
        customTitleFromDraft: customTitleFromDraft,
        locationTypeFromDraft: locationTypeFromDraft,
        endDateFromDraft: endDateFromDraft,
        allDayFromDraft: allDayFromDraft,
        endTimeFromDraft: endTimeFromDraft,
      ),
    );
  });
  app.editPage(ff.Pages.activityDetailPage, (page) {
    page.ensureReplaced(
      ff.Pages.activityDetailPage.widgets
          .byPath('ActivityDetailPage.body[0]')
          .single,
      _activityDetailPageBodyV2(
        activity: activity,
        activityDisplayTitle: activityDisplayTitle,
        activityDateLabel: activityDateLabel,
        activityScheduleLabel: activityScheduleLabel,
        activityAssigneeLabel: activityAssigneeLabel,
        effectiveCompletion: effectiveCompletion,
        deleteSheet: deleteSheet,
      ),
    );
  });

  app.raw((project) {
    updateCustomFunction(
      project,
      name: 'activityEndTimeFromDraftV2',
      code: r'''
final type = (activityType ?? '').trim();
if ((allDay ?? false) && (type == 'Wedstrijd' || type == 'Overig')) {
  return null;
}
if (type == 'Verzorging' &&
    startTime != null &&
    (durationMinutes ?? 0) > 0) {
  return startTime.add(Duration(minutes: durationMinutes ?? 0));
}
if (type == 'Training' ||
    type == 'Wedstrijd' ||
    type == 'Overig') {
  return endTime;
}
return startTime;
''',
      description:
          'Calculates care end time, keeps interval end times and normalizes point appointments.',
    );
    updateCustomFunction(
      project,
      name: 'todayActivities',
      code: r'''
final now = DateTime.now();
final today = DateTime(now.year, now.month, now.day);
final result = <ActivityDataStruct>[];
for (final item in activities ?? const <ActivityDataStruct>[]) {
  final rawStart = item.startDate ?? item.date;
  if (rawStart == null) continue;
  final rawEnd = item.endDate ?? rawStart;
  final start = DateTime(rawStart.year, rawStart.month, rawStart.day);
  final end = DateTime(rawEnd.year, rawEnd.month, rawEnd.day);
  if (!today.isBefore(start) && !today.isAfter(end)) result.add(item);
}
result.sort((a, b) {
  final at = a.startTime ?? a.time;
  final bt = b.startTime ?? b.time;
  if (at == null && bt == null) return a.id.compareTo(b.id);
  if (at == null) return 1;
  if (bt == null) return -1;
  return (at.hour * 60 + at.minute)
      .compareTo(bt.hour * 60 + bt.minute);
});
return result;
''',
      description:
          'Returns activities occurring today, including one shared multi-day competition record.',
    );
  });

  _applyActivityResponsiveVisibility(app, pageName: 'PlanningPage');
  _applyActivityResponsiveVisibility(app, pageName: 'ActivityDetailPage');
}

