  final activityConfirmationSheet = app.component(
    'ActivityConfirmationSheet',
    description:
        'Reusable AVARYN confirmation sheet with an explicit cancel-safe action.',
    params: {
      'title': string.withDefault('Bevestigen?'),
      'message': string.withDefault(''),
      'confirmText': string.withDefault('Bevestigen'),
      'onConfirmAction': action,
    },
