  final activityHorseName = CustomFunctionHandle(
    name: 'activityHorseName',
    args: {'horses': listOf(ff.Structs.horseProfileData), 'horseId': int_},
    returnType: string,
  );
  final horseListIsEmpty = CustomFunctionHandle(
    name: 'horseListIsEmpty',
    args: {'horses': listOf(ff.Structs.horseProfileData)},
    returnType: bool_,
  );
  final activityDeleteMessage = CustomFunctionHandle(
    name: 'activityDeleteMessage',
    args: {'title': string},
    returnType: string,
  );

  app.editComponent(ff.Components.activityHorsePickerSheet, (component) {
    component.ensureReplaced(
      ff.Components.activityHorsePickerSheet.widgets
          .byPath('ActivityHorsePickerSheet.children[0]')
          .single,
      _activityHorsePickerSheet(
        activityHorseName: activityHorseName,
        horseListIsEmpty: horseListIsEmpty,
      ),
    );
  });

  app.editPage(ff.Pages.activityFormPage, (page) {
    page.ensureActions(
      ff.Pages.activityFormPage.widgets.byKey('IconButton_v8cbqldo').single,
      triggerType: FFActionTriggerType.ON_TAP,
      actions: _activityDiscardActions(activityConfirmationSheet),
    );
  });

  app.editPage(ff.Pages.activityDetailPage, (page) {
    final selected = AppState(ff.AppState.selectedActivity);
    page.ensureActions(
      ff.Pages.activityDetailPage.widgets.byKey('Button_ck31wkn6').single,
      triggerType: FFActionTriggerType.ON_TAP,
      actions: [
        ShowBottomSheet(
          activityConfirmationSheet,
          params: {
            'title': 'Activiteit verwijderen?',
            'message': CustomFunction(
              activityDeleteMessage,
              args: {'title': selected['title']},
            ),
            'confirmText': 'Verwijderen',
            'onConfirmAction': [
              UpdateAppState.removeAtIndex(
                ff.AppState.activities,
                AppState(ff.AppState.selectedActivityIndex),
              ),
              ClearAppState(ff.AppState.selectedActivity),
              Snackbar('Activiteit verwijderd'),
              Navigate(ff.Pages.planningPage),
            ],
          },
        ),
      ],
    );
  });
}

