/// Adds the first complete local Planning and Activity flow while preserving
/// the responsive Today, horses and horse-detail foundations.
void buildPlanningActivityIteration(App app) {
  _configureAvarynTheme(app, existingProject: true);

  final activity = ff.Structs.activityData;

  final sortedActivities = app.customFunction(
    'sortedActivities',
    args: {'activities': listOf(activity)},
    returns: listOf(activity),
    code: r'''
final result = List<ActivityDataStruct>.from(
  activities ?? const <ActivityDataStruct>[],
);
result.sort((a, b) {
  final aDate = a.date;
  final bDate = b.date;
  if (aDate == null && bDate == null) return a.id.compareTo(b.id);
  if (aDate == null) return 1;
  if (bDate == null) return -1;
  final aDay = DateTime(aDate.year, aDate.month, aDate.day);
  final bDay = DateTime(bDate.year, bDate.month, bDate.day);
  final dateCompare = aDay.compareTo(bDay);
  if (dateCompare != 0) return dateCompare;
  final aTime = a.time;
  final bTime = b.time;
  if (aTime == null && bTime == null) return a.id.compareTo(b.id);
  if (aTime == null) return 1;
  if (bTime == null) return -1;
  final aMinutes = aTime.hour * 60 + aTime.minute;
  final bMinutes = bTime.hour * 60 + bTime.minute;
  final timeCompare = aMinutes.compareTo(bMinutes);
  return timeCompare != 0 ? timeCompare : a.id.compareTo(b.id);
});
return result;
''',
    description:
        'Sorts activities chronologically, placing untimed entries after timed entries on the same date.',
  );
  final todayActivities = app.customFunction(
    'todayActivities',
    args: {'activities': listOf(activity)},
    returns: listOf(activity),
    code: r'''
final now = DateTime.now();
final today = DateTime(now.year, now.month, now.day);
final result = <ActivityDataStruct>[];
for (final activity in activities ?? const <ActivityDataStruct>[]) {
  final date = activity.date;
  if (date == null) continue;
  final localDay = DateTime(date.year, date.month, date.day);
  if (localDay == today) result.add(activity);
}
result.sort((a, b) {
  final aTime = a.time;
  final bTime = b.time;
  if (aTime == null && bTime == null) return a.id.compareTo(b.id);
  if (aTime == null) return 1;
  if (bTime == null) return -1;
  final aMinutes = aTime.hour * 60 + aTime.minute;
  final bMinutes = bTime.hour * 60 + bTime.minute;
  final timeCompare = aMinutes.compareTo(bMinutes);
  return timeCompare != 0 ? timeCompare : a.id.compareTo(b.id);
});
return result;
''',
    description:
        'Returns only activities whose local calendar date is today, sorted by time.',
  );
  final activityListIsEmpty = app.customFunction(
    'activityListIsEmpty',
    args: {'activities': listOf(activity)},
    returns: bool_,
    code: 'return activities == null || activities.isEmpty;',
    description:
        'Safely reports whether a local activity list contains no records.',
  );
  final activityIsFirstOnDate = app.customFunction(
    'activityIsFirstOnDate',
    args: {'activities': listOf(activity), 'activityId': int_},
    returns: bool_,
    code: r'''
final values = List<ActivityDataStruct>.from(
  activities ?? const <ActivityDataStruct>[],
);
values.sort((a, b) {
  final aDate = a.date;
  final bDate = b.date;
  if (aDate == null && bDate == null) return a.id.compareTo(b.id);
  if (aDate == null) return 1;
  if (bDate == null) return -1;
  final aDay = DateTime(aDate.year, aDate.month, aDate.day);
  final bDay = DateTime(bDate.year, bDate.month, bDate.day);
  final dateCompare = aDay.compareTo(bDay);
  if (dateCompare != 0) return dateCompare;
  final aTime = a.time;
  final bTime = b.time;
  if (aTime == null && bTime == null) return a.id.compareTo(b.id);
  if (aTime == null) return 1;
  if (bTime == null) return -1;
  final aMinutes = aTime.hour * 60 + aTime.minute;
  final bMinutes = bTime.hour * 60 + bTime.minute;
  final timeCompare = aMinutes.compareTo(bMinutes);
  return timeCompare != 0 ? timeCompare : a.id.compareTo(b.id);
});
final index = values.indexWhere((item) => item.id == activityId);
if (index < 0) return false;
if (index == 0) return true;
final current = values[index].date;
final previous = values[index - 1].date;
if (current == null) return previous != null;
if (previous == null) return true;
return current.year != previous.year ||
    current.month != previous.month ||
    current.day != previous.day;
''',
    description:
        'Marks the first chronologically sorted activity in each calendar-date group.',
  );
  final activityIndexById = app.customFunction(
    'activityIndexById',
    args: {'activities': listOf(activity), 'activityId': int_},
    returns: int_,
    code: r'''
if (activities == null || activities.isEmpty) return 0;
final index = activities.indexWhere((item) => item.id == activityId);
return index < 0 ? 0 : index;
''',
    description:
        'Resolves the original app-state index for a unique activity ID.',
  );
  final activityHorseName = app.customFunction(
    'activityHorseName',
    args: {'horses': listOf(ff.Structs.horseProfileData), 'horseId': int_},
    returns: string,
    code: r'''
for (final horse in horses ?? const <HorseProfileDataStruct>[]) {
  if (horse.id != horseId) continue;
  final callName = horse.callName.trim();
  if (callName.isNotEmpty) return callName;
  final officialName = horse.officialName.trim();
  return officialName.isNotEmpty ? officialName : 'Onbekend paard';
}
return 'Onbekend paard';
''',
    description:
        'Resolves an activity horse dynamically, preferring its call name.',
  );
  final activityHorsePhoto = app.customFunction(
    'activityHorsePhoto',
    args: {'horses': listOf(ff.Structs.horseProfileData), 'horseId': int_},
    returns: string,
    code: r'''
for (final horse in horses ?? const <HorseProfileDataStruct>[]) {
  if (horse.id == horseId) return horse.photoData;
}
return '';
''',
    description:
        'Resolves the current photo data for the horse linked to an activity.',
  );
  final horseListIsEmpty = app.customFunction(
    'horseListIsEmpty',
    args: {'horses': listOf(ff.Structs.horseProfileData)},
    returns: bool_,
    code: 'return horses == null || horses.isEmpty;',
    description:
        'Safely reports whether the local prototype has no horses to select.',
  );
  final formatActivityDate = app.customFunction(
    'formatActivityDateDutch',
    args: {'date': dateTime},
    returns: string,
    code: r'''
if (date == null) return 'Datum onbekend';
const weekdays = <String>[
  'maandag',
  'dinsdag',
  'woensdag',
  'donderdag',
  'vrijdag',
  'zaterdag',
  'zondag',
];
const months = <String>[
  'januari',
  'februari',
  'maart',
  'april',
  'mei',
  'juni',
  'juli',
  'augustus',
  'september',
  'oktober',
  'november',
  'december',
];
return '${weekdays[date.weekday - 1]} ${date.day} ${months[date.month - 1]} ${date.year}';
''',
    description: 'Formats an activity date in natural Dutch.',
  );
  final formatActivityTime = app.customFunction(
    'formatActivityTimeDutch',
    args: {'time': dateTime},
    returns: string,
    code: r'''
if (time == null) return 'Geen tijd';
final hour = time.hour.toString().padLeft(2, '0');
final minute = time.minute.toString().padLeft(2, '0');
return '$hour:$minute';
''',
    description:
        'Formats an optional activity time, using a clear Dutch empty label.',
  );
  final activityFormIsValid = app.customFunction(
    'activityFormIsValid',
    args: {
      'activityType': string,
      'horseId': int_,
      'title': string,
      'date': dateTime,
    },
    returns: bool_,
    code: r'''
return (activityType ?? '').trim().isNotEmpty &&
    (horseId ?? 0) > 0 &&
    (title ?? '').trim().isNotEmpty &&
    date != null;
''',
    description:
        'Validates the four required activity fields before a local save.',
  );
  final activityDeleteMessage = app.customFunction(
    'activityDeleteMessage',
    args: {'title': string},
    returns: string,
    code: r'''
final safeTitle = (title ?? '').trim();
final label = safeTitle.isEmpty ? 'Deze activiteit' : 'â€œ$safeTitleâ€';
return '$label wordt verwijderd uit Planning en Vandaag. Dit kan niet ongedaan worden gemaakt.';
''',
    description:
        'Builds a calm Dutch deletion confirmation naming the activity.',
  );

  final composeActivityDate = CustomFunctionHandle(
    name: 'composeHorseDate',
    args: {
      'day': string,
      'month': string,
      'year': string,
      'allowFuture': bool_,
    },
    returnType: dateTime,
  );
  final activityDateSelectionIsValid = CustomFunctionHandle(
    name: 'horseDateSelectionIsValid',
    args: {
      'day': string,
      'month': string,
      'year': string,
      'allowFuture': bool_,
    },
    returnType: bool_,
  );
  final activityDateDay = CustomFunctionHandle(
    name: 'horseDateDay',
    args: {'date': dateTime},
    returnType: string,
  );
  final activityDateMonth = CustomFunctionHandle(
    name: 'horseDateMonth',
    args: {'date': dateTime},
    returnType: string,
  );
  final activityDateYear = CustomFunctionHandle(
    name: 'horseDateYear',
    args: {'date': dateTime},
    returnType: string,
  );
  final passportWarningVisible = CustomFunctionHandle(
    name: 'horsePassportWarningVisible',
    args: {'expiryDate': dateTime},
    returnType: bool_,
  );
  final passportWarningMessage = CustomFunctionHandle(
    name: 'horsePassportWarningMessage',
    args: {'expiryDate': dateTime, 'callName': string, 'officialName': string},
    returnType: string,
  );
  final formatHorseDate = CustomFunctionHandle(
    name: 'formatHorseDateDutch',
    args: {'date': dateTime},
    returnType: string,
  );
  final horseAgeLabel = CustomFunctionHandle(
    name: 'horseAgeLabel',
    args: {'date': dateTime},
    returnType: string,
  );

  final activityCard = app.component(
    'AvarynActivityCard',
    description: 'Reusable AVARYN activity row shared by Planning and Vandaag.',
    params: {
      'activityType': string.withDefault('Overig'),
