      'formDateMonth': string.withDefault(''),
      'formDateYear': string.withDefault(''),
      'hasChanges': bool_.withDefault(false),
      'isSaving': bool_.withDefault(false),
      'showTypeError': bool_.withDefault(false),
      'showHorseError': bool_.withDefault(false),
      'showTitleError': bool_.withDefault(false),
      'showDateError': bool_.withDefault(false),
    },
    onLoad: _activityFormOnLoad(
      activityDateDay: activityDateDay,
      activityDateMonth: activityDateMonth,
      activityDateYear: activityDateYear,
    ),
    body: _activityFormPageBody(
      activity: activity,
      horsePickerSheet: horsePickerSheet,
      activityConfirmationSheet: activityConfirmationSheet,
      activityHorseName: activityHorseName,
      activityHorsePhoto: activityHorsePhoto,
