        detailTarget: ff.Pages.orionProfilePage,
        formTarget: ff.Pages.horseFormPage,
        planningTarget: planningPage,
      ),
    );
  });
  app.editPage(ff.Pages.orionProfilePage, (page) {
    page.ensureReplaced(
      ff.Pages.orionProfilePage.widgets
          .byPath('OrionProfilePage.body[0]')
          .single,
      _dataDrivenHorseDetailPageBody(
        profileSectionState:
            ff.Pages.orionProfilePage.state.activeProfileSection,
        formTarget: ff.Pages.horseEditPage,
        planningTarget: planningPage,
        formatHorseDate: formatHorseDate,
        horseAgeLabel: horseAgeLabel,
      ),
    );
  });

  _applyTodayResponsiveVisibility(app);
  _applyHorsesResponsiveVisibility(app);
  _applyHorseDetailResponsiveVisibility(app);
  _applyActivityResponsiveVisibility(app, pageName: planningPage.name);
  _applyActivityResponsiveVisibility(app, pageName: activityDetailPage.name);

  // Keep these local handles part of the same compiled edit graph.
  assert(activityFormPage.name == 'ActivityFormPage');
}

/// Schema-first checkpoint for the optional horse passport expiry date.
///
/// Keeping this mutation separate lets FlutterFlow regenerate the typed project
/// SDK before the form, profile and Today widgets start referencing the field.
void buildPassportSchemaCheckpoint(App app) {
  _configureAvarynTheme(app, existingProject: true);
  app.state(
    'passportPrototypeVersion',
    int_.withDefault(0),
    persisted: true,
    description:
        'One-time local prototype migration guard for passport expiry sample data.',
  );
  app.raw((project) {
    ensureDataStructField(
      project,
      structName: 'HorseProfileData',
      fieldName: 'passportExpiryDate',
      type: dateTimeType,
      description:
          'Optional date through which the horse passport remains valid.',
    );
  });
}

final class _CliOptions {
  const _CliOptions({
    this.apiKey,
    this.baseUrl,
    this.projectName,
    this.projectId,
    this.findOrCreate = false,
    this.allowNewProject = false,
    this.dryRun = false,
    this.commitMessage,
  });

  final String? apiKey;
  final String? baseUrl;
  final String? projectName;
  final String? projectId;
  final bool findOrCreate;
  final bool allowNewProject;
  final bool dryRun;
  final String? commitMessage;
}

_CliOptions _parseCliOptions(List<String> args) {
  String? apiKey;
  String? baseUrl;
  String? projectName;
  String? projectId;
  String? commitMessage;
  var findOrCreate = false;
  var allowNewProject = false;
  var dryRun = false;

  for (var i = 0; i < args.length; i++) {
    final arg = args[i];
    switch (arg) {
      case '--help':
      case '-h':
        _printUsage();
        exit(0);
      case '--api-key':
        apiKey = _requireValue(args, ++i, '--api-key');
      case '--base-url':
        baseUrl = _requireValue(args, ++i, '--base-url');
      case '--project-name':
        projectName = _requireValue(args, ++i, '--project-name');
      case '--project-id':
        projectId = _requireValue(args, ++i, '--project-id');
      case '--commit-message':
        commitMessage = _requireValue(args, ++i, '--commit-message');
      case '--find-or-create':
        findOrCreate = true;
      case '--allow-new-project':
        allowNewProject = true;
      case '--dry-run':
        dryRun = true;
      default:
        stderr.writeln('Unknown option: $arg');
        _printUsage();
        exit(64);
    }
  }

  return _CliOptions(
    apiKey: apiKey,
    baseUrl: baseUrl,
    projectName: projectName,
    projectId: projectId,
    findOrCreate: findOrCreate,
    allowNewProject: allowNewProject,
    dryRun: dryRun,
    commitMessage: commitMessage,
  );
}

String _requireValue(List<String> args, int index, String flag) {
  if (index >= args.length) {
    stderr.writeln('Missing value for $flag.');
    _printUsage();
    exit(64);
  }
  return args[index];
}

void _printUsage() {
  stdout.writeln('''
Run the AVARYN FlutterFlow AI edit flow.

Usage:
  dart run dsl/edit.dart [options]

Options:
  --api-key <key>           FlutterFlow API key. Defaults to FF_API_KEY.
  --base-url <url>          Override the FlutterFlow API base URL.
  --project-name <name>     Create a new project with this name.
  --project-id <id>         Push into an existing project by ID.
  --find-or-create          Retry by reusing a same-name project before creating.
  --allow-new-project       Bypass the workspace binding guard and create a different project.
  --commit-message <text>   Commit message for the push.
  --dry-run                 Compile and validate without pushing.
  --help, -h                Show this help.
''');
}

void buildAvarynCheckpoint(App app) {
  _configureAvarynTheme(app, existingProject: true);

  final horse = app.struct(
    'HorseProfileData',
    {
      'id': int_,
      'officialName': string,
      'callName': string,
      'photoData': string,
      'discipline': string,
      'competitionClass': string,
      'birthDate': dateTime,
      'sex': string,
      'breed': string,
      'color': string,
      'passportNumber': string,
      'chipNumber': string,
      'owner': string,
      'rider': string,
      'stableLocation': string,
      'notes': string,
      'dayForm': string,
      'attention': string,
      'nextActivity': string,
    },
    description:
        'Persistent local prototype model shared by the AVARYN horse list, detail and edit flows.',
  );
  app.state(
    'horses',
    listOf(horse),
    persisted: true,
    description: 'Locally persisted prototype horses.',
  );
  app.state(
    'selectedHorse',
    horse,
    persisted: true,
    description: 'Horse currently rendered by the reusable detail template.',
  );
  app.state(
    'selectedHorseIndex',
    int_.withDefault(0),
    persisted: true,
    description: 'Index of the selected horse in the local prototype list.',
  );
  app.state(
    'nextHorseId',
    int_.withDefault(4),
    persisted: true,
    description: 'Next unique local prototype horse identifier.',
  );
  app.state(
    'nextHorseIndex',
    int_.withDefault(3),
    persisted: true,
    description: 'Next insertion index for a locally created horse.',
  );
  app.state(
    'horseSeedVersion',
    int_.withDefault(0),
    persisted: true,
    description: 'One-time version guard for AVARYN sample horses.',
  );

  app.pubDependency('file_picker', '^11.0.2');
  final pickHorsePhoto =
      app.customAction(
            'pickHorsePrototypePhoto',
            returns: string,
            code: r'''
import 'dart:convert';

import 'package:file_picker/file_picker.dart';

Future<String> pickHorsePrototypePhoto() async {
  final result = await FilePicker.pickFiles(
    type: FileType.image,
    allowMultiple: false,
    withData: true,
  );
  if (result == null || result.files.isEmpty) {
    return '';
  }
  final file = result.files.single;
  final bytes = file.bytes;
  if (bytes == null || bytes.isEmpty) {
    return '';
  }
  final extension = (file.extension ?? '').toLowerCase();
  final mimeType = switch (extension) {
    'png' => 'image/png',
    'webp' => 'image/webp',
    'gif' => 'image/gif',
    _ => 'image/jpeg',
  };
  return 'data:$mimeType;base64,${base64Encode(bytes)}';
}
''',
            description:
                'Selects one local horse photograph and returns an in-memory data URL for prototype state only.',
          )
          as CustomActionTarget;
  final formatHorseDate = app.customFunction(
    'formatHorseBirthDate',
    args: {'date': dateTime},
    returns: string,
    code: r'''
if (date == null) return '';
final day = date.day.toString().padLeft(2, '0');
final month = date.month.toString().padLeft(2, '0');
return '$day-$month-${date.year}';
''',
    description:
        'Formats an optional horse birth date as Dutch day-month-year.',
  );
  final horseAgeLabel = app.customFunction(
    'horseAgeLabel',
    args: {'date': dateTime},
    returns: string,
    code: r'''
if (date == null) return '';
final today = DateTime.now();
var years = today.year - date.year;
if (today.month < date.month ||
    (today.month == date.month && today.day < date.day)) {
  years--;
}
if (years < 0) return '';
return '$years jaar';
''',
    description:
        'Calculates a compact Dutch age label from a horse birth date.',
  );
  final parseHorseDate = app.customFunction(
    'parseHorsePrototypeDate',
    args: {'value': string},
    returns: dateTime,
    code: r'''
if (value == null || value.isEmpty) return null;
return DateTime.tryParse(value);
''',
    description: 'Parses ISO sample dates for local prototype horses.',
  );

  app.customWidget(
    'AvarynOrionPhoto',
    code: _orionPhotoCustomWidgetCode,
    description:
        'Embedded editorial photograph of Orion for the AVARYN mobile Today experience.',
  );
  _replaceAvarynComponents(app);

  final horseFormPage = app.page(
    'HorseFormPage',
    route: '/paarden/formulier',
    description:
        'Mobile-first AVARYN flow for locally adding and editing a horse.',
    params: {'editMode': bool_.withDefault(false)},
    state: {
      'formStep': int_.withDefault(0),
      'formBirthDate': dateTime,
      'formSex': string.withDefault(''),
      'formColor': string.withDefault(''),
      'formDiscipline': string.withDefault('Dressuur'),
      'formCompetitionClass': string.withDefault(''),
      'formPhotoData': string.withDefault(''),
      'isSaving': bool_.withDefault(false),
    },
    onLoad: _horseFormOnLoadActions(),
    body: _horseFormPageBody(
      horse: horse,
      pickHorsePhoto: pickHorsePhoto,
      formatHorseDate: formatHorseDate,
      composeHorseDate: CustomFunctionHandle(
        name: 'composeHorseDate',
        args: {
          'day': string,
          'month': string,
          'year': string,
          'allowFuture': bool_,
        },
        returnType: dateTime,
      ),
      horseDateSelectionIsValid: CustomFunctionHandle(
        name: 'horseDateSelectionIsValid',
        args: {
          'day': string,
          'month': string,
          'year': string,
          'allowFuture': bool_,
        },
        returnType: bool_,
      ),
      detailTarget: ff.Pages.orionProfilePage,
    ),
  );

  final seedActions = _seedHorsePrototypeActions(horse, parseHorseDate);
  app.editPageOnLoad(ff.Pages.horsesOverviewPage, seedActions);
  app.editPageOnLoad(ff.Pages.orionProfilePage, seedActions);

  app.editPageOnLoad(ff.Pages.todayDashboardPage, [
    SetState(ff.Pages.todayDashboardPage.state.selectedHorse, 'Orion'),
  ]);

  app.editPage(ff.Pages.todayDashboardPage, (page) {
    page.ensureReplaced(
      ff.Pages.todayDashboardPage.widgets
          .byPath('TodayDashboardPage.body[0]')
          .single,
      _todayDashboardBody(horsesTarget: ff.Pages.horsesOverviewPage),
    );
  });

  app.editPage(ff.Pages.horsesOverviewPage, (page) {
    page.ensureReplaced(
      ff.Pages.horsesOverviewPage.widgets
          .byPath('HorsesOverviewPage.body[0]')
          .single,
      _dataDrivenHorsesOverviewPageBody(
        detailTarget: ff.Pages.orionProfilePage,
        formTarget: horseFormPage,
      ),
    );
  });

  app.editPage(ff.Pages.orionProfilePage, (page) {
    page.ensureReplaced(
      ff.Pages.orionProfilePage.widgets
          .byPath('OrionProfilePage.body[0]')
          .single,
      _dataDrivenHorseDetailPageBody(
        profileSectionState:
            ff.Pages.orionProfilePage.state.activeProfileSection,
        formTarget: horseFormPage,
        formatHorseDate: formatHorseDate,
        horseAgeLabel: horseAgeLabel,
      ),
    );
  });

  app.raw((project) {
    updateCustomWidget(
      project,
      name: 'AvarynHorseshoeIcon',
      code: _horseshoeIconCustomWidgetCode,
      description:
          'Minimal theme-aware AVARYN horseshoe outline reserved for Paarden navigation.',
    );
    updateCustomWidget(
      project,
      name: 'AvarynHorseAvatar',
      code: _horseAvatarCustomWidgetCode,
      description:
          'Photo-ready horse profile visual with a refined horse-head fallback.',
    );

    final todayPage = findPage(project, name: 'TodayDashboardPage');
    if (todayPage == null) {
      throw StateError('Expected TodayDashboardPage to be present.');
    }

    FFNode findNamedNode(FFWidgetClass widgetClass, String name) {
      final matches = findDescendants(
        widgetClass.node,
        (node) => node.name == name,
      );
      if (matches.length != 1) {
        throw StateError(
          'Expected one $name widget in ${widgetClass.name}, '
          'found ${matches.length}.',
        );
      }
      return matches.single;
    }

    for (final name in const [
      'DesktopSideNavigation',
      'DesktopDashboardCanvas',
    ]) {
      setResponsiveVisibility(
        findNamedNode(todayPage, name),
        phoneHidden: true,
        tabletHidden: true,
        tabletLandscapeHidden: true,
        desktopHidden: false,
      );
    }

    for (final name in const [
      'CompactDashboardCanvas',
      'MobileBottomNavigation',
    ]) {
      setResponsiveVisibility(
        findNamedNode(todayPage, name),
        phoneHidden: false,
        tabletHidden: false,
        tabletLandscapeHidden: false,
        desktopHidden: true,
      );
    }

    final horsesPage = findPage(project, name: 'HorsesOverviewPage');
    if (horsesPage == null) {
      throw StateError('Expected HorsesOverviewPage to be present.');
    }

    for (final name in const [
      'HorsesDesktopSideNavigation',
      'HorsesDesktopCanvas',
    ]) {
      setResponsiveVisibility(
        findNamedNode(horsesPage, name),
        phoneHidden: true,
        tabletHidden: true,
        tabletLandscapeHidden: true,
        desktopHidden: false,
      );
    }

    for (final name in const [
      'HorsesCompactCanvas',
      'HorsesMobileBottomNavigation',
    ]) {
      setResponsiveVisibility(
        findNamedNode(horsesPage, name),
        phoneHidden: false,
        tabletHidden: false,
        tabletLandscapeHidden: false,
        desktopHidden: true,
      );
    }

    final orionPage = findPage(project, name: 'OrionProfilePage');
    if (orionPage == null) {
      throw StateError('Expected OrionProfilePage to be present.');
    }

    for (final name in const [
      'HorseDetailDesktopSideNavigation',
      'HorseDetailDesktopCanvas',
    ]) {
      setResponsiveVisibility(
        findNamedNode(orionPage, name),
        phoneHidden: true,
        tabletHidden: true,
        tabletLandscapeHidden: true,
        desktopHidden: false,
      );
    }

    for (final name in const [
      'HorseDetailCompactCanvas',
      'HorseDetailMobileBottomNavigation',
    ]) {
      setResponsiveVisibility(
        findNamedNode(orionPage, name),
        phoneHidden: false,
        tabletHidden: false,
        tabletLandscapeHidden: false,
        desktopHidden: true,
      );
    }

    updatePage(
      project,
      name: 'TodayDashboardPage',
      description:
          'Premium responsive AVARYN Vandaag-dashboard voor prestaties, '
          'aandachtspunten, planning en dagvorm.',
    );
    setPageRoute(project, pageName: 'TodayDashboardPage', route: '/today');
    updatePage(
      project,
      name: 'HorsesOverviewPage',
      description:
          'Premium responsive AVARYN paardenoverzicht met lokale sampledata.',
    );
    setPageRoute(project, pageName: 'HorsesOverviewPage', route: '/paarden');
    updatePage(
      project,
      name: 'OrionProfilePage',
      description:
          'Reusable responsive AVARYN horse detail template backed by local prototype state.',
    );
    setPageRoute(
      project,
      pageName: 'OrionProfilePage',
      route: '/paarden/detail',
    );

    const componentDescriptions = {
      'AvarynPrimaryButton':
          'Obsidian AVARYN primary action with premium pressed and hover states.',
      'AvarynSecondaryButton':
          'Restrained AVARYN secondary action for supporting decisions.',
      'AvarynStatusChip':
          'Accessible AVARYN status chip with icon and text semantics.',
      'AvarynProfileImage': 'Rose-gold framed rider portrait placeholder.',
      'AvarynHorseSelectorCard':
          'Responsieve paardenkaart met identiteit, discipline en dagvorm.',
      'AvarynMetricCard':
          'Warm-white AVARYN insight card with metric and progress cue.',
      'AvarynTaskRow':
          'Performance timeline row with horse portrait, state, and contextual action.',
      'AvarynMobileNavigation':
          'Minimal five-destination AVARYN mobile bottom navigation.',
      'AvarynDesktopNavigation':
          'Compact obsidian AVARYN desktop side navigation.',
      'AvarynLoadingState':
          'Branded AVARYN loading state with monogram, wordmark, and rose-bronze progress.',
    };
    for (final entry in componentDescriptions.entries) {
      updateComponent(project, name: entry.key, description: entry.value);
    }
  });
}

/// Brownfield refinement for the separated AVARYN create and edit flows.
///
/// The existing five-step HorseFormPage remains the creation flow. Editing is
/// handled by a dedicated tabbed page so switching sections never submits or
/// discards field state.
void buildHorseFormsRefinement(App app) {
  _configureAvarynTheme(app, existingProject: true);

  final horse = ff.Structs.horseProfileData;
  final pickHorsePhoto =
      app.existingCustomAction(
            'pickHorsePrototypePhoto',
            args: const {},
            returns: string,
          )
          as CustomActionTarget;
  final formatHorseDate = app.customFunction(
    'formatHorseDateDutch',
    args: {'date': dateTime},
    returns: string,
    code: r'''
if (date == null) return '';
const months = <String>[
  'januari',
  'februari',
  'maart',
  'april',
  'mei',
  'juni',
  'juli',
  'augustus',
  'september',
  'oktober',
  'november',
  'december',
];
return '${date.day} ${months[date.month - 1]} ${date.year}';
''',
    description:
        'Formats an optional horse date in natural Dutch, for example 17 april 2015.',
  );
  final composeHorseDate = app.customFunction(
    'composeHorseDate',
    args: {
      'day': string,
      'month': string,
      'year': string,
      'allowFuture': bool_,
    },
    returns: dateTime,
    code: r'''
if (day == null ||
    month == null ||
    year == null ||
    day.isEmpty ||
    month.isEmpty ||
    year.isEmpty) {
  return null;
}
const months = <String>[
  'januari',
  'februari',
  'maart',
  'april',
  'mei',
  'juni',
  'juli',
  'augustus',
  'september',
  'oktober',
  'november',
  'december',
];
final dayValue = int.tryParse(day);
final monthValue = months.indexOf(month.toLowerCase()) + 1;
final yearValue = int.tryParse(year);
if (dayValue == null || yearValue == null || monthValue < 1) return null;
final candidate = DateTime(yearValue, monthValue, dayValue);
if (candidate.year != yearValue ||
    candidate.month != monthValue ||
    candidate.day != dayValue) {
  return null;
}
if (allowFuture != true) {
  final now = DateTime.now();
  final today = DateTime(now.year, now.month, now.day);
  if (candidate.isAfter(today)) return null;
}
return candidate;
''',
    description:
        'Composes a validated DateTime from Dutch day, month and year controls.',
  );
  final horseDateSelectionIsValid = app.customFunction(
    'horseDateSelectionIsValid',
    args: {
      'day': string,
      'month': string,
      'year': string,
      'allowFuture': bool_,
    },
    returns: bool_,
    code: r'''
final values = <String?>[day, month, year];
final emptyCount = values.where((value) => value == null || value.isEmpty).length;
if (emptyCount == 3) return true;
if (emptyCount != 0) return false;
const months = <String>[
  'januari',
  'februari',
  'maart',
  'april',
  'mei',
  'juni',
  'juli',
  'augustus',
  'september',
  'oktober',
  'november',
  'december',
];
final dayValue = int.tryParse(day!);
final monthValue = months.indexOf(month!.toLowerCase()) + 1;
final yearValue = int.tryParse(year!);
if (dayValue == null || yearValue == null || monthValue < 1) return false;
final candidate = DateTime(yearValue, monthValue, dayValue);
if (candidate.year != yearValue ||
    candidate.month != monthValue ||
    candidate.day != dayValue) {
  return false;
}
if (allowFuture != true) {
  final now = DateTime.now();
  final today = DateTime(now.year, now.month, now.day);
  if (candidate.isAfter(today)) return false;
}
return true;
''',
    description:
        'Allows an empty optional date but rejects partial, impossible and disallowed future dates.',
  );
  final horseDateDay = app.customFunction(
    'horseDateDay',
    args: {'date': dateTime},
    returns: string,
    code: "if (date == null) return ''; return date.day.toString();",
    description: 'Extracts the day value for a Dutch horse date selector.',
  );
  final horseDateMonth = app.customFunction(
    'horseDateMonth',
    args: {'date': dateTime},
    returns: string,
    code: r'''
if (date == null) return '';
const months = <String>[
  'januari',
  'februari',
  'maart',
  'april',
  'mei',
  'juni',
  'juli',
  'augustus',
  'september',
  'oktober',
  'november',
  'december',
];
return months[date.month - 1];
''',
    description: 'Extracts the Dutch month name for a horse date selector.',
  );
  final horseDateYear = app.customFunction(
    'horseDateYear',
    args: {'date': dateTime},
    returns: string,
    code: "if (date == null) return ''; return date.year.toString();",
    description: 'Extracts the year value for a horse date selector.',
  );
  final passportWarningVisible = app.customFunction(
    'horsePassportWarningVisible',
    args: {'expiryDate': dateTime},
    returns: bool_,
    code: r'''
if (expiryDate == null) return false;
final now = DateTime.now();
final today = DateTime(now.year, now.month, now.day);
var thresholdYear = expiryDate.year;
var thresholdMonth = expiryDate.month - 6;
while (thresholdMonth <= 0) {
  thresholdMonth += 12;
  thresholdYear--;
}
final lastThresholdDay = DateTime(thresholdYear, thresholdMonth + 1, 0).day;
final thresholdDay =
    expiryDate.day > lastThresholdDay ? lastThresholdDay : expiryDate.day;
final threshold = DateTime(thresholdYear, thresholdMonth, thresholdDay);
return !today.isBefore(threshold);
''',
    description:
        'Shows a passport warning from exactly six calendar months before expiry.',
  );
  final passportWarningMessage = app.customFunction(
    'horsePassportWarningMessage',
    args: {'expiryDate': dateTime, 'callName': string, 'officialName': string},
    returns: string,
    code: r'''
if (expiryDate == null) return '';
final preferredCallName = (callName ?? '').trim();
final preferredOfficialName = (officialName ?? '').trim();
final name = preferredCallName.isNotEmpty
    ? preferredCallName
    : (preferredOfficialName.isNotEmpty ? preferredOfficialName : 'Onbekend paard');
final now = DateTime.now();
final today = DateTime(now.year, now.month, now.day);
final expiry = DateTime(expiryDate.year, expiryDate.month, expiryDate.day);
final days = expiry.difference(today).inDays;
if (days < -1) return 'Paspoort van $name is ${-days} dagen verlopen.';
if (days == -1) return 'Paspoort van $name is gisteren verlopen.';
if (days == 0) return 'Paspoort van $name vervalt vandaag.';
if (days == 1) return 'Paspoort van $name vervalt morgen.';
return 'Paspoort van $name vervalt over $days dagen.';
''',
    description:
        'Builds a dynamic Dutch passport warning with natural today and expiry wording.',
  );

  final horseEditPage = ff.Pages.horseEditPage;

  app.editPageState(ff.Pages.horseEditPage, (state) {
    state.ensureField('showDiscardConfirm', bool_.withDefault(false));
    state.ensureField('editBirthDate', dateTime);
