    state.ensureField('editCompetitionClass', string.withDefault(''));
    state.ensureField('editDiscipline', string.withDefault(''));
    state.ensureField('editNotes', string.withDefault(''));
    state.ensureField('editOfficialName', string.withDefault(''));
    state.ensureField('editOwner', string.withDefault(''));
    state.ensureField('editPassportNumber', string.withDefault(''));
    state.ensureField('editPhotoData', string.withDefault(''));
    state.ensureField('editRider', string.withDefault(''));
    state.ensureField('editSex', string.withDefault(''));
    state.ensureField('editStableLocation', string.withDefault(''));
    state.ensureField('hasChanges', bool_.withDefault(false));
    state.ensureField('isSaving', bool_.withDefault(false));
    state.ensureField('showNameError', bool_.withDefault(false));
    state.ensureField('showSexError', bool_.withDefault(false));
    state.ensureField('editBirthDay', string.withDefault(''));
    state.ensureField('editBirthMonth', string.withDefault(''));
    state.ensureField('editBirthYear', string.withDefault(''));
    state.ensureField('editPassportExpiryDate', dateTime);
    state.ensureField('editPassportExpiryDay', string.withDefault(''));
    state.ensureField('editPassportExpiryMonth', string.withDefault(''));
    state.ensureField('editPassportExpiryYear', string.withDefault(''));
  });
  app.editPageOnLoad(
    ff.Pages.horseEditPage,
