  app.editPage(ff.Pages.horseEditPage, (page) {
    page.ensureReplaced(
      ff.Pages.horseEditPage.widgets.byKey('Container_zmcaaip4').single,
      _horseDateSelector(
        name: 'EditHorseBirthDateSelector',
