  app.editPageOnLoad(ff.Pages.horseFormPage, [
    SetState(ff.Pages.horseFormPage.state.formStep, 0),
    SetState(ff.Pages.horseFormPage.state.formSex, ''),
    SetState(ff.Pages.horseFormPage.state.formColor, ''),
    SetState(ff.Pages.horseFormPage.state.formDiscipline, 'Dressuur'),
    SetState(ff.Pages.horseFormPage.state.formCompetitionClass, ''),
