  final parseHorseDate = CustomFunctionHandle(
    name: 'parseHorsePrototypeDate',
    args: {'value': string},
    returnType: dateTime,
  );
  final passportMigration = _passportPrototypeMigrationActions(
    horse,
    parseHorseDate,
  );
  app.editPageOnLoad(ff.Pages.todayDashboardPage, passportMigration);
  app.editPageOnLoad(ff.Pages.horsesOverviewPage, passportMigration);
  app.editPageOnLoad(ff.Pages.orionProfilePage, passportMigration);
  app.editPage(ff.Pages.todayDashboardPage, (page) {
    page.ensureReplaced(
      ff.Pages.todayDashboardPage.widgets
          .byPath('TodayDashboardPage.body[0]')
          .single,
      _todayDashboardBody(
        horsesTarget: ff.Pages.horsesOverviewPage,
        horseEditTarget: horseEditPage,
        passportWarningVisible: passportWarningVisible,
        passportWarningMessage: passportWarningMessage,
      ),
    );
  });

  _applyTodayResponsiveVisibility(app);
  app.raw((project) {
    final horseEdit = findPage(project, name: 'HorseEditPage');
    if (horseEdit == null) {
      throw StateError('Expected HorseEditPage to be present.');
    }
    final stakeholdersTabs = findDescendants(
      horseEdit.node,
      (node) => node.name == 'Tab: Omgeving',
    );
    if (stakeholdersTabs.length != 1) {
      throw StateError(
        'Expected one Omgeving tab in HorseEditPage, found ${stakeholdersTabs.length}.',
      );
    }
    final stakeholdersTab = stakeholdersTabs.single;
    stakeholdersTab.name = 'Tab: Betrokkenen & locatie';
    stakeholdersTab.props.tab.text.textValue.inputValue =
        'Betrokkenen & locatie';

    updatePage(
      project,
      name: 'HorseFormPage',
      description:
          'Calm five-step AVARYN creation flow for one locally stored prototype horse.',
    );
    updatePage(
      project,
      name: 'HorseEditPage',
      description:
          'Reusable AVARYN horse editor with validated Dutch date controls and local passport data.',
    );
    updatePage(
      project,
      name: 'OrionProfilePage',
      description:
          'Reusable AVARYN horse profile with dynamic identity and passport information.',
    );
  });
}

void _applyTodayResponsiveVisibility(App app) {
  app.raw((project) {
    final responsiveToday = findPage(project, name: 'TodayDashboardPage');
    if (responsiveToday == null) {
      throw StateError('Expected TodayDashboardPage to be present.');
    }

    FFNode findTodayResponsiveNode(String name) {
      final matches = findDescendants(
        responsiveToday.node,
        (node) => node.name == name,
      );
      if (matches.length != 1) {
        throw StateError(
          'Expected one $name widget in TodayDashboardPage, '
          'found ${matches.length}.',
        );
      }
      return matches.single;
    }

    setResponsiveVisibility(
      findTodayResponsiveNode('DesktopSideNavigation'),
      phoneHidden: true,
      tabletHidden: true,
      tabletLandscapeHidden: true,
      desktopHidden: false,
    );
    setResponsiveVisibility(
      findTodayResponsiveNode('DesktopDashboardCanvas'),
      phoneHidden: true,
      tabletHidden: true,
      tabletLandscapeHidden: true,
      desktopHidden: true,
    );
    setResponsiveVisibility(
      findTodayResponsiveNode('CompactDashboardCanvas'),
      phoneHidden: false,
      tabletHidden: false,
      tabletLandscapeHidden: false,
      desktopHidden: false,
    );
    setResponsiveVisibility(
      findTodayResponsiveNode('MobileBottomNavigation'),
      phoneHidden: false,
      tabletHidden: false,
      tabletLandscapeHidden: false,
      desktopHidden: true,
    );
  });
}

