/// Standalone compile-only smoke app used by test/app_test.dart.
void buildAvarynDesignSystemTestApp(App app) {
  _configureAvarynTheme(app, existingProject: false);
  app.customWidget(
    'AvarynOrionPhoto',
    code: _orionPhotoCustomWidgetCode,
    description: 'Embedded editorial photograph of Orion.',
  );
  app.customWidget(
    'AvarynHorseshoeIcon',
    parameters: {'active': bool_},
    code: _horseshoeIconCustomWidgetCode,
    description:
        'Minimal AVARYN horseshoe outline reserved for Paarden navigation.',
  );
  app.customWidget(
    'AvarynHorseAvatar',
    parameters: {'photoState': string},
    code: _horseAvatarCustomWidgetCode,
    description:
        'Photo-ready horse profile visual with a refined horse-head fallback.',
  );
  _declarePreviewComponents(app);

  app.page(
    'AvarynDesignPreviewPage',
    route: '/',
    isInitial: true,
    description: 'Compile-only preview of the redesigned AVARYN system.',
    body: Scaffold(
      body: Column(
        scrollable: true,
        crossAxis: CrossAxis.stretch,
        spacing: 20,
        padding: 24,
        children: [
          Text('Vandaag geregeld', style: Styles.headlineMedium),
          Text(
            'Warm, calm and precise equestrian performance design.',
            style: Styles.bodyLarge,
            color: Colors.secondaryText,
          ),
          _equestrianVisual(height: 150),
        ],
      ),
    ),
  );
  app.page(
    'TodayDashboardPage',
    route: '/today-preview',
    description: 'Compile-only navigation target for the horse overview test.',
    state: {'selectedHorse': string.withDefault('Orion')},
    body: _todayDashboardBody(),
  );
  app.page(
    'HorsesOverviewPage',
    route: '/paarden-preview',
    description: 'Compile-only preview of the AVARYN horse overview.',
    body: _horsesOverviewPageBody(),
  );
  app.page(
    'OrionProfilePage',
    route: '/paarden/orion-preview',
    description: 'Compile-only preview of the Orion horse profile.',
    state: {'activeProfileSection': string.withDefault('Overzicht')},
    body: _orionProfilePageBody(),
  );
}

void _configureAvarynTheme(App app, {required bool existingProject}) {
  // AVARYN semantic surfaces. Light values stay unchanged; every paired dark
  // value is an explicit brand token rather than an automatic inversion.
  app.themeColor('primary', 0xFF171518, dark: 0xFF1C191D);
  app.themeColor('secondary', 0xFFA96F68, dark: 0xFFC48A82);
  app.themeColor('tertiary', 0xFFE2C2BE, dark: 0xFFADA29E);
  app.themeColor('alternate', 0xFFF1EAE2, dark: 0xFF494047);
  app.themeColor('primaryBackground', 0xFFFCF8F3, dark: 0xFF151316);
  app.themeColor('secondaryBackground', 0xFFFCF8F3, dark: 0xFF252126);
  app.themeColor('primaryText', 0xFF171518, dark: 0xFFFCF8F3);
  app.themeColor('secondaryText', 0xFF6D6460, dark: 0xFFD8CFCA);
  app.themeColor('accent1', 0xFFFCF8F3, dark: 0xFFFCF8F3);
  app.themeColor('accent2', 0xFFF1EAE2, dark: 0xFF302A30);
  app.themeColor('accent3', 0xFFE2C2BE, dark: 0xFF4A3034);
  app.themeColor('accent4', 0xFFFCF8F3, dark: 0xFF1C191D);
  app.themeColor('success', 0xFF718577, dark: 0xFF8FA497);
  app.themeColor('warning', 0xFFE7ECE8, dark: 0xFF302A30);
  app.themeColor('error', 0xFFB65F58, dark: 0xFFD87870);
  app.themeColor('info', 0xFF713D43, dark: 0xFF8D525A);

  app.darkMode(enabled: true);
  app.primaryFont('Inter Tight');
  app.secondaryFont('Inter');
  app.breakpoints(small: 600, medium: 768, large: 1023);

  _headingStyle(app, 'displayLarge', 58, 600, lineHeight: 1.06);
  _headingStyle(app, 'displayMedium', 46, 600, lineHeight: 1.08);
  _headingStyle(app, 'displaySmall', 38, 600, lineHeight: 1.10);
  _headingStyle(app, 'headlineLarge', 36, 600, lineHeight: 1.12);
  _headingStyle(app, 'headlineMedium', 34, 600, lineHeight: 1.14);
  _headingStyle(app, 'headlineSmall', 24, 600, lineHeight: 1.20);
  _headingStyle(app, 'titleLarge', 22, 600, lineHeight: 1.24);
  _headingStyle(app, 'titleMedium', 17, 600, lineHeight: 1.30);
  _headingStyle(app, 'titleSmall', 15, 600, lineHeight: 1.32);

  _bodyStyle(app, 'bodyLarge', 16, 400, lineHeight: 1.55);
  _bodyStyle(app, 'bodyMedium', 14, 400, lineHeight: 1.50);
  _bodyStyle(app, 'bodySmall', 12, 400, lineHeight: 1.44);
  _bodyStyle(app, 'labelLarge', 15, 600, letterSpacing: 0.05);
  _bodyStyle(app, 'labelMedium', 13, 600, letterSpacing: 0.08);
  _bodyStyle(app, 'labelSmall', 11, 600, letterSpacing: 0.12);

  if (existingProject) {
    app.raw((project) {
      updateSpacingToken(project, name: 'xxs', value: 2);
      updateSpacingToken(project, name: 'xs', value: 4);
      updateSpacingToken(project, name: 'sm', value: 8);
      updateSpacingToken(project, name: 'md', value: 12);
      updateSpacingToken(project, name: 'lg', value: 16);
      updateSpacingToken(project, name: 'xl', value: 24);
      updateSpacingToken(project, name: 'xxl', value: 32);
      updateSpacingToken(project, name: 'section', value: 40);
      updateSpacingToken(project, name: 'canvas', value: 56);

      updateRadiusToken(project, name: 'xs', value: 6);
      updateRadiusToken(project, name: 'sm', value: 8);
      updateRadiusToken(project, name: 'md', value: 12);
      updateRadiusToken(project, name: 'lg', value: 16);
      updateRadiusToken(project, name: 'pill', value: 9999);

      updateShadowToken(
        project,
        name: 'soft',
        blurRadius: 14,
        dy: 4,
        spreadRadius: -3,
        color: ffColor(0x14786E69),
      );
      updateShadowToken(
        project,
        name: 'card',
        blurRadius: 24,
        dy: 10,
        spreadRadius: -7,
        color: ffColor(0x1A786E69),
      );
      updateShadowToken(
        project,
        name: 'floating',
        blurRadius: 34,
        dy: 16,
        spreadRadius: -9,
        color: ffColor(0x24171518),
      );
    });
  } else {
    app.spacingToken('xxs', 2);
    app.spacingToken('xs', 4);
    app.spacingToken('sm', 8);
    app.spacingToken('md', 12);
    app.spacingToken('lg', 16);
    app.spacingToken('xl', 24);
    app.spacingToken('xxl', 32);
    app.spacingToken('section', 40);
    app.spacingToken('canvas', 56);

    app.radiusToken('xs', 6);
    app.radiusToken('sm', 8);
    app.radiusToken('md', 12);
    app.radiusToken('lg', 16);
    app.radiusToken('pill', 9999);

    app.shadowToken(
      'soft',
      blurRadius: 14,
      dy: 4,
      spreadRadius: -3,
      color: 0x14786E69,
    );
    app.shadowToken(
      'card',
      blurRadius: 24,
      dy: 10,
      spreadRadius: -7,
      color: 0x1A786E69,
    );
    app.shadowToken(
      'floating',
      blurRadius: 34,
      dy: 16,
      spreadRadius: -9,
      color: 0x24171518,
    );
  }

  app.scrollbar(
    thumbVisible: true,
    trackVisible: false,
    thickness: 4,
    radius: 4,
    interactive: true,
    thumbColor: 0x66786E69,
    thumbHoverColor: 0x99A96F68,
  );
  app.pullToRefresh(
    indicatorColor: 0xFFA96F68,
    backgroundColor: 0xFFFCF8F3,
    strokeWidth: 2.5,
  );
}

void _headingStyle(
  App app,
  String slot,
  double size,
  int weight, {
  double? lineHeight,
}) {
  app.typography(
    slot,
    fontFamily: 'Inter Tight',
    fontSize: size,
    fontWeight: weight,
    lineHeight: lineHeight,
  );
}

void _bodyStyle(
  App app,
  String slot,
  double size,
  int weight, {
  double? lineHeight,
  double? letterSpacing,
}) {
  app.typography(
    slot,
    fontFamily: 'Inter',
    fontSize: size,
    fontWeight: weight,
    lineHeight: lineHeight,
    letterSpacing: letterSpacing,
  );
}

