void _declarePreviewComponents(App app) {
  app.component(
    'AvarynLoadingState',
    description: 'Branded AVARYN loading state.',
    body: _loadingStateBody(),
  );
  app.component(
    'AvarynPrimaryButton',
    description: 'Premium AVARYN primary action.',
    params: {'label': string.withDefault('Continue'), 'onTapAction': action},
    body: _primaryButtonBody(),
  );
  app.component(
    'AvarynSecondaryButton',
    description: 'Premium AVARYN secondary action.',
    params: {'label': string.withDefault('Review'), 'onTapAction': action},
    body: _secondaryButtonBody(),
  );
  app.component(
    'AvarynStatusChip',
    description: 'Accessible status chip.',
    params: {
      'label': string.withDefault('Ready'),
      'urgent': bool_.withDefault(false),
    },
    body: _statusChipBody(),
  );
  app.component(
    'AvarynProfileImage',
    description: 'Rider portrait placeholder.',
    params: {'initials': string.withDefault('AR')},
    body: _profileImageBody(),
  );
  app.component(
    'AvarynHorseSelectorCard',
    description: 'Paardenportret en selector voor dagvorm.',
    params: {
      'initials': string.withDefault('AV'),
      'horseName': string.withDefault('Horse'),
      'stableName': string.withDefault('Stable name'),
      'status': string.withDefault('Ready'),
      'selected': bool_.withDefault(false),
      'onTapAction': action,
    },
    body: _horseSelectorBody(),
  );
  app.component(
    'AvarynMetricCard',
    description: 'Premium insight card.',
    params: {
      'eyebrow': string.withDefault('Overview'),
      'value': string.withDefault('â€”'),
      'title': string.withDefault('Metric'),
      'helper': string.withDefault(''),
      'onTapAction': action,
    },
    body: _metricCardBody(),
  );
  app.component(
    'AvarynTaskRow',
    description: 'Performance timeline row.',
    params: {
      'initials': string.withDefault('AV'),
      'horseName': string.withDefault('Horse'),
      'time': string.withDefault('09:00'),
      'task': string.withDefault('Routine task'),
      'detail': string.withDefault(''),
      'completed': bool_.withDefault(false),
      'actionLabel': string.withDefault('Afronden'),
      'onTapAction': action,
    },
    body: _taskRowBody(),
  );

  final navParams = <String, DslType>{
    'todayAction': action,
    'horsesAction': action,
    'tasksAction': action,
    'competitionAction': action,
    'profileAction': action,
  };
  app.component(
    'AvarynMobileNavigation',
    description: 'Mobile navigation.',
    params: navParams,
    body: _mobileNavigationBody(),
  );
  app.component(
    'AvarynDesktopNavigation',
    description: 'Desktop navigation.',
    params: navParams,
    body: _desktopNavigationBody(),
  );
}

