DslWidget _horseSelectorWidget({
  required Object horseName,
  required Object stableName,
  required Object status,
  required Object selection,
  required DslAction onTap,
  Object photoState = '',
  String? name,
}) => Stack(
  name: name,
  children: [
    _horseSelectorSurface(
      activeSurface: true,
      horseName: horseName,
      stableName: stableName,
      status: status,
      selection: selection,
      onTap: onTap,
      photoState: photoState,
    ),
    _horseSelectorSurface(
      activeSurface: false,
      horseName: horseName,
      stableName: stableName,
      status: status,
      selection: selection,
      onTap: onTap,
      photoState: photoState,
    ),
  ],
);

DslWidget _horseSelectorSurface({
  required bool activeSurface,
  required Object horseName,
  required Object stableName,
  required Object status,
  required Object selection,
  required DslAction onTap,
  required Object photoState,
}) => Container(
  visible: activeSurface ? selection : Not(selection),
  width: double.infinity,
  padding: 14,
  borderRadius: 18,
  borderColor: activeSurface ? Colors.secondary : Colors.alternate,
  borderWidth: activeSurface ? 1.5 : 0.8,
  color: Colors.secondaryBackground,
  shadow: Shadow(
    blur: activeSurface ? 22 : 14,
    dy: activeSurface ? 8 : 4,
    spread: -7,
    color: Colors.hex(activeSurface ? 0x2AA96F68 : 0x12786E69),
  ),
  onTap: onTap,
  child: Row(
    spacing: 12,
    children: [
      Container(
        width: 3,
        height: 66,
        borderRadius: 999,
        color: activeSurface ? Colors.secondary : Colors.alternate,
      ),
      Container(
        width: 72,
        height: 72,
        borderRadius: 16,
        color: Colors.accent2,
        child: _horseAvatar(photoState),
      ),
      Expanded(
        Column(
          crossAxis: CrossAxis.start,
          spacing: 4,
          children: [
            Text(
              horseName,
              style: Styles.titleMedium,
              color: Colors.primaryText,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
            ),
            Text(
              stableName,
              style: Styles.bodySmall,
              color: Colors.secondaryText,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
            ),
            Text(
              status,
              style: Styles.labelSmall,
              color: activeSurface ? Colors.secondary : Colors.success,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
            ),
          ],
        ),
      ),
      Icon(
        activeSurface ? 'check_circle' : 'chevron_right',
        size: 20,
        color: activeSurface ? Colors.secondary : Colors.secondaryText,
      ),
    ],
  ),
);

