DslWidget _taskRowBody() => Stack(
  name: 'AvarynTaskRowBody',
  children: [
    _taskSurface('open'),
    _taskSurface('blocked'),
    _taskSurface('completed'),
    Text(
      Param('initials'),
      visible: false,
      style: Styles.labelSmall,
      name: 'LegacyTaskInitialsCompatibility',
    ),
  ],
);

DslWidget _taskSurface(String state) {
  final visible = switch (state) {
    'blocked' => Equals(Param('actionLabel'), 'Beoordelen'),
    'completed' => Param('completed'),
    _ => Equals(Param('actionLabel'), 'Afronden'),
  };
  final statusLabel = switch (state) {
    'blocked' => 'Geblokkeerd',
    'completed' => 'Voltooid',
    _ => 'Gepland',
  };
  final statusIcon = switch (state) {
    'blocked' => 'warning_amber',
    'completed' => 'check_circle',
    _ => 'schedule',
  };
  final statusColor = switch (state) {
    'blocked' => Colors.error,
    'completed' => Colors.success,
    _ => Colors.secondary,
  };
  final statusTextColor = state == 'blocked' ? Colors.primaryText : statusColor;
  final surfaceColor = switch (state) {
    'blocked' => Colors.accent3,
    'completed' => Colors.primaryBackground,
    _ => Colors.secondaryBackground,
  };

  return Container(
    visible: visible,
    padding: 14,
    borderRadius: 16,
    borderColor: state == 'blocked' ? Colors.error : Colors.alternate,
    borderWidth: state == 'blocked' ? 1 : 0.6,
    color: surfaceColor,
    onTap: ParamAction('onTapAction'),
    child: Row(
      spacing: 12,
      children: [
        Container(
          width: 48,
          child: Text(
            Param('time'),
            style: Styles.titleSmall,
            color:
                state == 'completed'
                    ? Colors.secondaryText
                    : Colors.primaryText,
            textAlign: TextAlign.center,
          ),
        ),
        Container(
          width: 44,
          height: 44,
          borderRadius: 12,
          color: Colors.accent2,
          child: _horseAvatar(''),
        ),
        Expanded(
          Column(
            crossAxis: CrossAxis.start,
            spacing: 5,
            children: [
              Text(
                Param('task'),
                style: Styles.titleSmall,
                color:
                    state == 'completed'
                        ? Colors.secondaryText
                        : Colors.primaryText,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
              ),
              Text(
                Param('horseName'),
                style: Styles.labelSmall,
                color: Colors.secondary,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
              ),
              Text(
                Param('detail'),
                style: Styles.bodySmall,
                color: Colors.secondaryText,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
              ),
              Row(
                spacing: 6,
                children: [
                  Icon(statusIcon, size: 14, color: statusColor),
                  Text(
                    statusLabel,
                    style: Styles.labelSmall,
                    color: statusTextColor,
                  ),
                  Text(
                    'Â·',
                    style: Styles.labelSmall,
                    color: Colors.secondaryText,
                  ),
                  Text(
                    Param('actionLabel'),
                    style: Styles.labelSmall,
                    color: Colors.primaryText,
                  ),
                ],
              ),
            ],
          ),
        ),
        Icon('chevron_right', size: 21, color: statusColor),
      ],
    ),
  );
}

DslWidget _pageTaskRow({
  required String time,
  required String horseName,
  required String task,
  required String detail,
  required String state,
  required DslAction onTap,
}) {
  final statusLabel = switch (state) {
    'blocked' => 'Geblokkeerd',
    'completed' => 'Voltooid',
    _ => 'Gepland',
  };
  final actionLabel = switch (state) {
    'blocked' => 'Beoordelen',
    'completed' => 'Bekijken',
    _ => 'Afronden',
  };
  final statusIcon = switch (state) {
    'blocked' => 'warning_amber',
    'completed' => 'check_circle',
    _ => 'schedule',
  };
  final statusColor = switch (state) {
    'blocked' => Colors.error,
    'completed' => Colors.success,
    _ => Colors.secondary,
  };
  final statusTextColor = state == 'blocked' ? Colors.primaryText : statusColor;
  final surfaceColor = switch (state) {
    'blocked' => Colors.accent3,
    'completed' => Colors.primaryBackground,
    _ => Colors.secondaryBackground,
  };

  return Container(
    padding: 14,
    borderRadius: 16,
    borderColor: state == 'blocked' ? Colors.error : Colors.alternate,
    borderWidth: state == 'blocked' ? 1 : 0.6,
    color: surfaceColor,
    onTap: onTap,
    child: Row(
      spacing: 12,
      children: [
        Container(
          width: 48,
          child: Text(
            time,
            style: Styles.titleSmall,
            color:
                state == 'completed'
                    ? Colors.secondaryText
                    : Colors.primaryText,
            textAlign: TextAlign.center,
          ),
        ),
        Container(
          width: 44,
          height: 44,
          borderRadius: 12,
          color: Colors.accent2,
          child: _horseAvatar(horseName == 'Orion' ? 'samplePhoto' : ''),
        ),
        Expanded(
          Column(
            crossAxis: CrossAxis.start,
            spacing: 5,
            children: [
              Text(
                task,
                style: Styles.titleSmall,
                color:
                    state == 'completed'
                        ? Colors.secondaryText
                        : Colors.primaryText,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
              ),
              Text(
                horseName,
                style: Styles.labelSmall,
                color: Colors.secondary,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
              ),
              Text(
                detail,
                style: Styles.bodySmall,
                color: Colors.secondaryText,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
              ),
              Row(
                spacing: 6,
                children: [
                  Icon(statusIcon, size: 14, color: statusColor),
                  Text(
                    statusLabel,
                    style: Styles.labelSmall,
                    color: statusTextColor,
                  ),
                  Text(
                    'Â·',
                    style: Styles.labelSmall,
                    color: Colors.secondaryText,
                  ),
                  Text(
                    actionLabel,
                    style: Styles.labelSmall,
                    color: Colors.primaryText,
                  ),
                ],
              ),
            ],
          ),
        ),
        Icon('chevron_right', size: 21, color: statusColor),
      ],
    ),
  );
}

