DslWidget _desktopHorseNavItem(
  String label,
  String actionName, {
  bool active = false,
  bool bindParam = true,
  String currentTab = 'Vandaag',
  Object? horsesTarget,
  Object? planningTarget,
  Object? profileTarget,
}) => Container(
  borderRadius: 10,
  color: active ? Colors.hex(0xFF292529) : Colors.primary,
  onTap:
      bindParam
          ? ParamAction(actionName)
          : _navigationAction(
