              ),
            ],
          ),
        ),
      ),
    ],
  ),
);

DslAction _navigationAction(
  String label, {
  String currentTab = 'Vandaag',
  Object? horsesTarget,
  Object? planningTarget,
  Object? profileTarget,
}) {
  if (label == currentTab) {
    return Snackbar('$label is al geselecteerd');
  }
  if (label == 'Vandaag') {
    return Navigate(ff.Pages.todayDashboardPage);
  }
  if (label == 'Paarden') {
    final target = horsesTarget;
    return target == null
        ? Snackbar('Paarden is al geselecteerd')
        : Navigate(target);
  }
  return switch (label) {
    'Planning' =>
      planningTarget == null
          ? Snackbar('Planning volgt in de volgende ontwerpcheckpoint')
          : Navigate(planningTarget),
    'Wedstrijden' => Snackbar(
      'Wedstrijden volgt in de volgende ontwerpcheckpoint',
    ),
    'Profiel' =>
      profileTarget == null
          ? Snackbar('Profiel volgt in de volgende ontwerpcheckpoint')
          : Navigate(profileTarget),
    _ => Snackbar('$label is nog niet beschikbaar'),
  };
}

