DslWidget _orionProfileHero({
  required double height,
  required bool desktop,
}) => Container(
  name:
      desktop
          ? 'OrionDesktopPhotographicHeader'
          : 'OrionMobilePhotographicHeader',
  width: double.infinity,
  height: height,
  borderRadius: desktop ? 20 : 0,
  color: Colors.primary,
  shadow: Shadow(blur: 30, dy: 14, spread: -13, color: Colors.hex(0x38171518)),
  child: Stack(
    children: [
      Container(
        width: double.infinity,
        height: height,
        borderRadius: desktop ? 20 : 0,
        child: CustomWidget(widgetName: 'AvarynOrionPhoto', arguments: {}),
      ),
      Container(
        width: double.infinity,
        height: height,
        padding: desktop ? 28 : 18,
        borderRadius: desktop ? 20 : 0,
