DslWidget _orionProfileTab(String section, Object profileSectionState) {
  final selected = Equals(State(profileSectionState), section);
  return Stack(
    children: [
      _orionProfileTabSurface(
        section,
        profileSectionState: profileSectionState,
        active: true,
        visible: selected,
      ),
      _orionProfileTabSurface(
        section,
        profileSectionState: profileSectionState,
        active: false,
        visible: Not(selected),
      ),
    ],
  );
}

DslWidget _orionProfileTabSurface(
  String section, {
  required Object profileSectionState,
  required bool active,
  required Object visible,
}) => Container(
  visible: visible,
  height: 44,
  padding: EdgeInsets.symmetric(horizontal: 13, vertical: 8),
  borderRadius: 9,
  color: active ? Colors.accent2 : Colors.secondaryBackground,
  onTap: SetState(profileSectionState, section),
  child: Column(
    mainAxis: MainAxis.center,
    spacing: 4,
    children: [
      Text(
        section,
        style: Styles.labelMedium,
        color: active ? Colors.secondary : Colors.primaryText,
        maxLines: 1,
        overflow: TextOverflow.ellipsis,
      ),
      Container(
        width: active ? 24 : 0,
        height: 2,
        borderRadius: 999,
        color: active ? Colors.secondary : Colors.secondaryBackground,
      ),
    ],
  ),
);

DslWidget _orionProfileSectionContent({
  required bool desktop,
