DslWidget _todayDashboardBody({
  Object? horsesTarget,
  Object? planningTarget,
  Object? horseEditTarget,
  CustomFunctionHandle? passportWarningVisible,
  CustomFunctionHandle? passportWarningMessage,
  StructHandle? activity,
  dynamic activityCard,
  CustomFunctionHandle? todayActivities,
  CustomFunctionHandle? activityListIsEmpty,
  CustomFunctionHandle? activityIndexById,
  CustomFunctionHandle? activityHorseName,
  CustomFunctionHandle? activityHorsePhoto,
  CustomFunctionHandle? formatActivityDate,
  CustomFunctionHandle? formatActivityTime,
  bool includeFeedingCard = false,
}) => Row(
  crossAxis: CrossAxis.stretch,
  name: 'TodayDashboardResponsiveShell',
  children: [
    Container(
      name: 'DesktopSideNavigation',
      child: _desktopNavigationBody(
        bindParams: false,
        horsesTarget: horsesTarget,
        planningTarget: planningTarget,
      ),
    ),
    Expanded(
      Column(
        crossAxis: CrossAxis.stretch,
        children: [
          Expanded(
            Column(
              scrollable: true,
              crossAxis: CrossAxis.stretch,
              children: [
                Container(
                  name: 'DesktopDashboardCanvas',
                  width: double.infinity,
                  child: Container(
                    name: 'DesktopDashboardContent',
                    padding: EdgeInsets.symmetric(horizontal: 28, vertical: 32),
                    child: _desktopDashboard(
                      horseEditTarget: horseEditTarget,
                      passportWarningVisible: passportWarningVisible,
                      passportWarningMessage: passportWarningMessage,
                      activity: activity,
                      activityCard: activityCard,
                      todayActivities: todayActivities,
                      activityListIsEmpty: activityListIsEmpty,
                      activityIndexById: activityIndexById,
                      activityHorseName: activityHorseName,
                      activityHorsePhoto: activityHorsePhoto,
                      formatActivityDate: formatActivityDate,
                      formatActivityTime: formatActivityTime,
                      includeFeedingCard: includeFeedingCard,
                    ),
                  ),
                ),
                Column(
                  name: 'CompactDashboardCanvas',
                  crossAxis: CrossAxis.stretch,
                  children: [
                    _mobileDashboard(
                      horseEditTarget: horseEditTarget,
                      passportWarningVisible: passportWarningVisible,
                      passportWarningMessage: passportWarningMessage,
                      activity: activity,
                      activityCard: activityCard,
                      todayActivities: todayActivities,
                      activityListIsEmpty: activityListIsEmpty,
                      activityIndexById: activityIndexById,
                      activityHorseName: activityHorseName,
                      activityHorsePhoto: activityHorsePhoto,
                      formatActivityDate: formatActivityDate,
                      formatActivityTime: formatActivityTime,
                      includeFeedingCard: includeFeedingCard,
                    ),
                  ],
                ),
              ],
            ),
          ),
