DslWidget _mobileHorseRow(String horseName, String stable, String status) {
  final selected = Equals(
    State(ff.Pages.todayDashboardPage.state.selectedHorse),
    horseName,
  );
  final onTap = SetState(
    ff.Pages.todayDashboardPage.state.selectedHorse,
    horseName,
  );
  return Stack(
    children: [
      _mobileHorseRowSurface(
        horseName,
        stable,
        status,
        active: true,
        visible: selected,
        onTap: onTap,
      ),
      _mobileHorseRowSurface(
        horseName,
        stable,
        status,
        active: false,
        visible: Not(selected),
        onTap: onTap,
      ),
    ],
  );
}

DslWidget _mobileHorseRowSurface(
  String horseName,
  String stable,
  String status, {
  required bool active,
  required Object visible,
  required DslAction onTap,
}) => Container(
  visible: visible,
  padding: EdgeInsets.symmetric(horizontal: 12, vertical: 10),
  color: active ? Colors.accent2 : Colors.secondaryBackground,
  onTap: onTap,
  child: Row(
    spacing: 11,
    children: [
      Container(
        width: 3,
        height: 42,
        color: active ? Colors.secondary : Colors.hex(0x00171518),
      ),
      Container(
        width: 46,
        height: 46,
        borderRadius: 2,
        color: Colors.accent2,
        child: _horseAvatar(horseName == 'Orion' ? 'samplePhoto' : ''),
      ),
      Expanded(
        Column(
          crossAxis: CrossAxis.start,
          spacing: 2,
          children: [
            Row(
              spacing: 7,
              children: [
                Text(
                  horseName,
                  style: Styles.titleMedium,
                  color: Colors.primaryText,
                ),
                Text(
                  stable,
                  style: Styles.bodySmall,
                  color: Colors.secondaryText,
                ),
              ],
            ),
            Text(
              status,
              style: Styles.bodySmall,
              color: active ? Colors.info : Colors.secondaryText,
            ),
          ],
        ),
      ),
      Icon(
        active ? 'check' : 'chevron_right',
        size: 19,
        color: active ? Colors.secondary : Colors.secondaryText,
      ),
    ],
  ),
);

