DslExpression _passportMigrationHorse(
  StructHandle horse,
  CustomFunctionHandle parseHorseDate,
  int id,
) {
  switch (id) {
    case 1:
      return Struct(horse, {
        'id': 1,
        'officialName': 'North Star',
        'callName': 'Orion',
        'photoData': 'samplePhoto',
        'discipline': 'Dressuur',
