List<DslAction> _passportPrototypeMigrationActions(
  StructHandle horse,
  CustomFunctionHandle parseHorseDate,
) => [
  ..._seedHorsePrototypeActions(horse, parseHorseDate),
  If(
    Equals(AppState(ff.AppState.passportPrototypeVersion), 0),
    then: [
      UpdateAppState.set(ff.AppState.selectedHorseIndex, 0),
      UpdateAppState.updateItemAtIndex(
        ff.AppState.horses,
        AppState(ff.AppState.selectedHorseIndex),
        _passportMigrationHorse(horse, parseHorseDate, 1),
      ),
      UpdateAppState.set(ff.AppState.selectedHorseIndex, 1),
      UpdateAppState.updateItemAtIndex(
        ff.AppState.horses,
        AppState(ff.AppState.selectedHorseIndex),
        _passportMigrationHorse(horse, parseHorseDate, 2),
      ),
      UpdateAppState.set(ff.AppState.selectedHorseIndex, 2),
      UpdateAppState.updateItemAtIndex(
        ff.AppState.horses,
        AppState(ff.AppState.selectedHorseIndex),
        _passportMigrationHorse(horse, parseHorseDate, 3),
      ),
      UpdateAppState.set(
        ff.AppState.selectedHorse,
        _passportMigrationHorse(horse, parseHorseDate, 1),
      ),
      UpdateAppState.set(ff.AppState.selectedHorseIndex, 0),
      UpdateAppState.set(ff.AppState.passportPrototypeVersion, 1),
    ],
  ),
];

