List<DslAction> _horseEditSaveActions(
  StructHandle horse, {
  required CustomFunctionHandle horseDateSelectionIsValid,
}) {
  final persist = <DslAction>[
    SetState('isSaving', true),
    UpdateAppState.updateItemAtIndex(
      ff.AppState.horses,
      AppState(ff.AppState.selectedHorseIndex),
      _horseFromEditForm(horse),
    ),
    UpdateAppState.set(ff.AppState.selectedHorse, _horseFromEditForm(horse)),
    SetState('hasChanges', false),
    Snackbar('Wijzigingen opgeslagen'),
    NavigateBack(),
  ];
  final validatePassportDate = <DslAction>[
    If(
      _horseDateSelectionValidExpression(
        dayState: 'editPassportExpiryDay',
        monthState: 'editPassportExpiryMonth',
        yearState: 'editPassportExpiryYear',
        allowFuture: true,
        horseDateSelectionIsValid: horseDateSelectionIsValid,
      ),
      then: persist,
      orElse: [
        Snackbar('Controleer de geldigheidsdatum van het paspoort.'),
        TabBarControl.jumpTo('HorseEditTabs', 2),
      ],
    ),
  ];
  final validateBirthDate = <DslAction>[
    If(
      _horseDateSelectionValidExpression(
        dayState: 'editBirthDay',
        monthState: 'editBirthMonth',
        yearState: 'editBirthYear',
        allowFuture: false,
        horseDateSelectionIsValid: horseDateSelectionIsValid,
      ),
      then: validatePassportDate,
      orElse: [
        Snackbar('Controleer de geboortedatum.'),
        TabBarControl.jumpTo('HorseEditTabs', 0),
      ],
    ),
  ];
  final validateSex = <DslAction>[
    If(
      Equals(State('editSex'), ''),
      then: [
        SetState('showSexError', true),
        TabBarControl.jumpTo('HorseEditTabs', 0),
      ],
      orElse: validateBirthDate,
    ),
  ];

  return [
    If(
      State(ff.Pages.horseEditPage.state.hasChanges),
      then: [
        If(
          Not(State('isSaving')),
          then: [
            If(
              Equals(State('editOfficialName'), ''),
              then: [
                If(
                  Equals(State('editCallName'), ''),
                  then: [
                    SetState('showNameError', true),
                    TabBarControl.jumpTo('HorseEditTabs', 0),
                  ],
                  orElse: validateSex,
                ),
              ],
              orElse: validateSex,
            ),
          ],
        ),
      ],
    ),
  ];
}

DslExpression _horseFromEditForm(StructHandle horse) => Struct(horse, {
  'id': AppState(ff.AppState.selectedHorse)['id'],
  'officialName': State('editOfficialName'),
  'callName': State('editCallName'),
  'photoData': State('editPhotoData'),
  'discipline': State('editDiscipline'),
  'competitionClass': State('editCompetitionClass'),
  'birthDate': State('editBirthDate'),
  'sex': State('editSex'),
  'breed': State('editBreed'),
  'color': State('editColor'),
  'passportNumber': State('editPassportNumber'),
  'passportExpiryDate': State('editPassportExpiryDate'),
  'chipNumber': State('editChipNumber'),
  'owner': State('editOwner'),
  'rider': State('editRider'),
  'stableLocation': State('editStableLocation'),
  'notes': State('editNotes'),
  'dayForm': AppState(ff.AppState.selectedHorse)['dayForm'],
  'attention': AppState(ff.AppState.selectedHorse)['attention'],
  'nextActivity': AppState(ff.AppState.selectedHorse)['nextActivity'],
});

