List<DslAction> _horseFormSubmitActions(
  StructHandle horse, {
  required bool editMode,
  required Object detailTarget,
  required CustomFunctionHandle horseDateSelectionIsValid,
}) {
  final persistActions =
      editMode
          ? _persistEditedHorseActions(horse)
          : _persistNewHorseActions(horse, detailTarget);
  final validatePassportDate = <DslAction>[
    If(
      _horseDateSelectionValidExpression(
        dayState: 'formPassportExpiryDay',
        monthState: 'formPassportExpiryMonth',
        yearState: 'formPassportExpiryYear',
        allowFuture: true,
        horseDateSelectionIsValid: horseDateSelectionIsValid,
      ),
      then: persistActions,
      orElse: [
        SetState('formStep', 2),
        Snackbar('Controleer de geldigheidsdatum van het paspoort.'),
      ],
    ),
  ];
  final validateBirthDate = <DslAction>[
    If(
      _horseDateSelectionValidExpression(
        dayState: 'formBirthDay',
        monthState: 'formBirthMonth',
        yearState: 'formBirthYear',
        allowFuture: false,
        horseDateSelectionIsValid: horseDateSelectionIsValid,
      ),
      then: validatePassportDate,
      orElse: [
        SetState('formStep', 0),
        Snackbar('Controleer de geboortedatum.'),
      ],
    ),
  ];
  final validateSex = <DslAction>[
    If(
      Equals(State('formSex'), ''),
      then: Snackbar('Kies het geslacht van het paard.'),
      orElse: validateBirthDate,
    ),
  ];
  return [
    If(
      Not(State('isSaving')),
      then: [
        If(
          Equals(State('formOfficialName'), ''),
          then: [
            If(
              Equals(State('formCallName'), ''),
              then: Snackbar('Vul een officiÃ«le naam of roepnaam in.'),
              orElse: validateSex,
            ),
          ],
          orElse: validateSex,
        ),
      ],
    ),
  ];
}

DslExpression _horseFromForm(StructHandle horse, {required bool editMode}) =>
    Struct(horse, {
      'id':
          editMode ? AppState('selectedHorse')['id'] : AppState('nextHorseId'),
      'officialName': State('formOfficialName'),
      'callName': State('formCallName'),
      'photoData': State('formPhotoData'),
      'discipline': State('formDiscipline'),
      'competitionClass': State('formCompetitionClass'),
      'birthDate': State('formBirthDate'),
      'sex': State('formSex'),
      'breed': State('formBreed'),
      'color': State('formColor'),
      'passportNumber': State('formPassportNumber'),
      'passportExpiryDate': State('formPassportExpiryDate'),
      'chipNumber': State('formChipNumber'),
      'owner': State('formOwner'),
      'rider': State('formRider'),
      'stableLocation': State('formStableLocation'),
      'notes': State('formNotes'),
      'dayForm':
          editMode ? AppState('selectedHorse')['dayForm'] : 'Nog niet gemeten',
      'attention': editMode ? AppState('selectedHorse')['attention'] : '',
      'nextActivity': editMode ? AppState('selectedHorse')['nextActivity'] : '',
    });

List<DslAction> _persistNewHorseActions(
  StructHandle horse,
  Object detailTarget,
) => [
  SetState('isSaving', true),
  UpdateAppState.set('selectedHorseIndex', AppState('nextHorseIndex')),
  UpdateAppState.set('selectedHorse', _horseFromForm(horse, editMode: false)),
  UpdateAppState.addToList('horses', _horseFromForm(horse, editMode: false)),
  UpdateAppState.increment('nextHorseId', 1),
  UpdateAppState.increment('nextHorseIndex', 1),
  Snackbar('Paard opgeslagen'),
  Navigate.to(detailTarget, replaceRoute: true),
];

List<DslAction> _persistEditedHorseActions(StructHandle horse) => [
  SetState('isSaving', true),
  UpdateAppState.updateItemAtIndex(
    'horses',
    AppState('selectedHorseIndex'),
    _horseFromForm(horse, editMode: true),
  ),
  UpdateAppState.set('selectedHorse', _horseFromForm(horse, editMode: true)),
  Snackbar('Wijzigingen opgeslagen'),
  NavigateBack(),
];

