    horseAgeLabel,
    args: {'date': selectedHorse['birthDate']},
  );
  return Container(
    name:
        desktop
            ? 'HorseDetailDesktopPhotographicHeader'
            : 'HorseDetailMobilePhotographicHeader',
    width: double.infinity,
    height: height,
    borderRadius: desktop ? 20 : 0,
    color: Colors.primary,
    shadow: Shadow(
      blur: 30,
      dy: 14,
      spread: -13,
      color: Colors.hex(0x38171518),
    ),
    child: Stack(
      children: [
        Container(
          width: double.infinity,
          height: height,
          borderRadius: desktop ? 20 : 0,
          color: Colors.accent2,
          child: _horseAvatar(selectedHorse['photoData']),
        ),
        Container(
          width: double.infinity,
          height: height,
