    spacing: 6,
    children: [
      _horseDetailTab('Overzicht', profileSectionState, nutritionTarget),
      _horseDetailTab('Gezondheid', profileSectionState, nutritionTarget),
      _horseDetailTab('Training', profileSectionState, nutritionTarget),
      _horseDetailTab('Voeding', profileSectionState, nutritionTarget),
      _horseDetailTab('Gegevens', profileSectionState, nutritionTarget),
    ],
  ),
);

DslWidget _horseDetailTab(
  String section,
  Object profileSectionState, [
  Object? nutritionTarget,
]) {
  final selected = Equals(State(profileSectionState), section);
  return Stack(
    children: [
      _horseDetailTabSurface(
        section,
        profileSectionState: profileSectionState,
        active: true,
        visible: selected,
        nutritionTarget: nutritionTarget,
      ),
      _horseDetailTabSurface(
        section,
        profileSectionState: profileSectionState,
        active: false,
        visible: Not(selected),
        nutritionTarget: nutritionTarget,
      ),
    ],
  );
}

DslWidget _horseDetailTabSurface(
  String section, {
  required Object profileSectionState,
  required bool active,
  required Object visible,
  Object? nutritionTarget,
}) => Container(
  visible: visible,
  height: 44,
  padding: EdgeInsets.symmetric(horizontal: 13, vertical: 8),
  borderRadius: 9,
  color: active ? Colors.accent2 : Colors.secondaryBackground,
  onTap:
      section == 'Voeding' && nutritionTarget != null
          ? Navigate.to(nutritionTarget)
          : SetState(profileSectionState, section),
  child: Column(
    mainAxis: MainAxis.center,
    spacing: 4,
    children: [
      Text(
        section,
        style: Styles.labelMedium,
        color: active ? Colors.secondary : Colors.primaryText,
        maxLines: 1,
        overflow: TextOverflow.ellipsis,
      ),
      Container(
        width: active ? 24 : 0,
        height: 2,
        borderRadius: 999,
        color: active ? Colors.secondary : Colors.secondaryBackground,
      ),
    ],
  ),
);

