DslWidget _horseDetailDataContent(
  Object formTarget,
  CustomFunctionHandle formatHorseDate,
) {
  final horse = AppState('selectedHorse');
  final formattedBirthDate = CustomFunction(
    formatHorseDate,
    args: {'date': horse['birthDate']},
  );
  final formattedPassportExpiryDate = CustomFunction(
    formatHorseDate,
    args: {'date': horse['passportExpiryDate']},
  );
  return Column(
    crossAxis: CrossAxis.stretch,
    spacing: 18,
    children: [
      Row(
        mainAxis: MainAxis.spaceBetween,
        crossAxis: CrossAxis.end,
        spacing: 14,
        children: [
          Expanded(
            Column(
              crossAxis: CrossAxis.start,
