                  maxLines: 2,
                  overflow: TextOverflow.ellipsis,
                ),
              ],
            ),
          ),
          Container(
            width: 120,
            child: Button(
              'Bewerken',
              name: 'EditHorseFromData',
              icon: 'edit',
              variant: ButtonVariant.outlined,
              height: 44,
              color: Colors.alternate,
              textColor: Colors.primaryText,
              borderRadius: 9,
              onTap: Navigate.to(formTarget),
            ),
          ),
        ],
      ),
      _horseDataGroup('Basisgegevens', 'badge', [
        _horseDataRow(
          'OfficiÃ«le naam',
          horse['officialName'],
          visible: Not(Equals(horse['officialName'], '')),
        ),
        _horseDataRow(
          'Roepnaam',
          horse['callName'],
          visible: Not(Equals(horse['callName'], '')),
        ),
        _horseDataRow(
          'Geboortedatum',
          formattedBirthDate,
          visible: Not(Equals(formattedBirthDate, '')),
        ),
        _horseDataRow('Geslacht', horse['sex']),
        _horseDataRow(
          'Ras',
          horse['breed'],
          visible: Not(Equals(horse['breed'], '')),
        ),
        _horseDataRow(
          'Kleur',
          horse['color'],
          visible: Not(Equals(horse['color'], '')),
