List<DslAction> _activityFormOnLoadV2({
  required StructHandle activity,
  required CustomFunctionHandle defaultAssigneeIds,
  required CustomFunctionHandle effectiveStartDate,
  required CustomFunctionHandle effectiveEndDate,
  required CustomFunctionHandle effectiveStartTime,
  required CustomFunctionHandle effectiveAssigneeIds,
  required CustomFunctionHandle effectiveCustomTitle,
  required CustomFunctionHandle durationChoiceForMinutes,
  required CustomFunctionHandle durationCustomText,
}) => [
  SetState(ff.Pages.activityFormPage.state.isSaving, false),
  SetState(ff.Pages.activityFormPage.state.formValidationMessage, ''),
  UpdateAppState.set(ff.AppState.activitySaveInProgress, false),
  If(
    PageParam('editMode'),
    then: [
      UpdateAppState.set(
        ff.AppState.activityDraftPendingType,
        AppState(ff.AppState.selectedActivity)['activityType'],
      ),
      UpdateAppState.set(
        ff.AppState.activityDraftHorseId,
        AppState(ff.AppState.selectedActivity)['horseId'],
      ),
      UpdateAppState.set(
        ff.AppState.activityDraftAssigneeUserIds,
        CustomFunction(
          effectiveAssigneeIds,
          args: {
            'activity': AppState(ff.AppState.selectedActivity),
            'currentUserId': AppState(ff.AppState.currentLocalUserId),
          },
        ),
      ),
      UpdateAppState.set(
        ff.AppState.activityDraftStartDate,
        CustomFunction(
          effectiveStartDate,
          args: {'activity': AppState(ff.AppState.selectedActivity)},
        ),
      ),
      UpdateAppState.set(
        ff.AppState.activityDraftEndDate,
        CustomFunction(
          effectiveEndDate,
          args: {'activity': AppState(ff.AppState.selectedActivity)},
        ),
      ),
      UpdateAppState.set(
        ff.AppState.activityDraftStartTime,
        CustomFunction(
          effectiveStartTime,
          args: {'activity': AppState(ff.AppState.selectedActivity)},
        ),
      ),
      UpdateAppState.set(
        ff.AppState.activityDraftEndTime,
        AppState(ff.AppState.selectedActivity)['endTime'],
      ),
      UpdateAppState.set(
        ff.AppState.activityDraftAllDay,
        AppState(ff.AppState.selectedActivity)['allDay'],
      ),
      UpdateAppState.set(
        ff.AppState.activityDraftDurationMinutes,
        AppState(ff.AppState.selectedActivity)['durationMinutes'],
      ),
      UpdateAppState.set(
        ff.AppState.activityDraftLocationType,
        AppState(ff.AppState.selectedActivity)['locationType'],
      ),
      SetState(
        'formDurationChoice',
        CustomFunction(
          durationChoiceForMinutes,
          args: {
            'minutes':
                AppState(ff.AppState.selectedActivity)['durationMinutes'],
          },
        ),
      ),
      SetFormField(
        'ActivityCustomDurationField',
        CustomFunction(
          durationCustomText,
          args: {
            'minutes':
                AppState(ff.AppState.selectedActivity)['durationMinutes'],
          },
        ),
      ),
      SetFormField(
        'ActivityCustomTitleField',
        CustomFunction(
          effectiveCustomTitle,
          args: {'activity': AppState(ff.AppState.selectedActivity)},
        ),
      ),
      SetFormField(
        'ActivityTrainingLocationField',
        AppState(ff.AppState.selectedActivity)['locationName'],
      ),
      SetFormField(
        'ActivityCompetitionLocationField',
        AppState(ff.AppState.selectedActivity)['locationName'],
      ),
      SetFormField(
        'ActivityOtherLocationField',
        AppState(ff.AppState.selectedActivity)['locationName'],
      ),
      SetFormField(
        'ActivityProviderField',
        AppState(ff.AppState.selectedActivity)['serviceProviderName'],
      ),
      SetFormField(
        'ActivityNotesFieldV2',
        AppState(ff.AppState.selectedActivity)['notes'],
      ),
    ],
    orElse: [
      UpdateAppState.set(ff.AppState.activityDraftPendingType, ''),
      UpdateAppState.set(ff.AppState.activityDraftHorseId, 0),
      UpdateAppState.set(
        ff.AppState.activityDraftAssigneeUserIds,
        CustomFunction(
          defaultAssigneeIds,
          args: {'currentUserId': AppState(ff.AppState.currentLocalUserId)},
        ),
      ),
      ClearAppState(ff.AppState.activityDraftStartDate),
      ClearAppState(ff.AppState.activityDraftEndDate),
      ClearAppState(ff.AppState.activityDraftStartTime),
      ClearAppState(ff.AppState.activityDraftEndTime),
      UpdateAppState.set(ff.AppState.activityDraftAllDay, false),
      UpdateAppState.set(ff.AppState.activityDraftDurationMinutes, 0),
      UpdateAppState.set(ff.AppState.activityDraftLocationType, ''),
      SetState(ff.Pages.activityFormPage.state.formDurationChoice, ''),
      SetFormField('ActivityCustomDurationField', ''),
      SetFormField('ActivityCustomTitleField', ''),
      SetFormField('ActivityTrainingLocationField', ''),
      SetFormField('ActivityCompetitionLocationField', ''),
      SetFormField('ActivityOtherLocationField', ''),
      SetFormField('ActivityProviderField', ''),
      SetFormField('ActivityNotesFieldV2', ''),
    ],
  ),
  SetState(ff.Pages.activityFormPage.state.hasChanges, false),
];

