DslExpression _activityFromFormV2({
  required StructHandle activity,
  required bool editMode,
  required CustomFunctionHandle durationMinutes,
  required CustomFunctionHandle activityDraftTitle,
  required CustomFunctionHandle locationNameFromDraft,
  required CustomFunctionHandle providerFromDraft,
  required CustomFunctionHandle notesFromDraft,
  required CustomFunctionHandle customTitleFromDraft,
  required CustomFunctionHandle locationTypeFromDraft,
  required CustomFunctionHandle endDateFromDraft,
  required CustomFunctionHandle allDayFromDraft,
  required CustomFunctionHandle endTimeFromDraft,
}) {
  final type = AppState(ff.AppState.activityDraftPendingType);
  final provider = CustomFunction(
    providerFromDraft,
    args: {
      'activityType': type,
      'providerName': WidgetState(
        'ActivityProviderField',
        WidgetStateProperty.text,
      ),
    },
  );
  final customTitle = CustomFunction(
    customTitleFromDraft,
    args: {
      'activityType': type,
      'customTitle': WidgetState(
        'ActivityCustomTitleField',
        WidgetStateProperty.text,
      ),
    },
  );
  final duration = _activityDurationFromFormV2(durationMinutes);
  final allDay = CustomFunction(
    allDayFromDraft,
    args: {
      'activityType': type,
      'allDay': AppState(ff.AppState.activityDraftAllDay),
    },
  );
  return Struct(activity, {
    'id':
        editMode
            ? AppState(ff.AppState.selectedActivity)['id']
            : AppState(ff.AppState.nextActivityId),
    'horseId': AppState(ff.AppState.activityDraftHorseId),
    'stableId':
        editMode ? AppState(ff.AppState.selectedActivity)['stableId'] : '',
    'activityType': type,
    'customTitle': customTitle,
    'assigneeUserIds': AppState(ff.AppState.activityDraftAssigneeUserIds),
    'startDate': AppState(ff.AppState.activityDraftStartDate),
    'endDate': CustomFunction(
      endDateFromDraft,
      args: {
        'activityType': type,
        'startDate': AppState(ff.AppState.activityDraftStartDate),
        'endDate': AppState(ff.AppState.activityDraftEndDate),
      },
    ),
    'startTime': AppState(ff.AppState.activityDraftStartTime),
    'endTime': CustomFunction(
      endTimeFromDraft,
      args: {
        'activityType': type,
        'startTime': AppState(ff.AppState.activityDraftStartTime),
        'endTime': AppState(ff.AppState.activityDraftEndTime),
        'allDay': allDay,
        'durationMinutes': duration,
      },
    ),
    'allDay': allDay,
    'durationMinutes': duration,
    'locationType': CustomFunction(
      locationTypeFromDraft,
      args: {
        'activityType': type,
        'locationType': AppState(ff.AppState.activityDraftLocationType),
      },
    ),
    'locationName': _activityLocationFromFormV2(locationNameFromDraft),
    'serviceProviderName': provider,
    'notes': CustomFunction(
      notesFromDraft,
      args: {
        'activityType': type,
        'notes': WidgetState('ActivityNotesFieldV2', WidgetStateProperty.text),
      },
    ),
    'completionStatus':
        editMode
            ? AppState(ff.AppState.selectedActivity)['completionStatus']
            : 'open',
    'createdAt':
        editMode
            ? AppState(ff.AppState.selectedActivity)['createdAt']
            : Global(GlobalProperty.currentTimestamp),
    'updatedAt': Global(GlobalProperty.currentTimestamp),
    // Previous fields remain mirrored so already-built cards and local records
    // remain compatible while the app transitions to the typed interval model.
    'title': CustomFunction(
      activityDraftTitle,
      args: {
        'activityType': type,
        'customTitle': customTitle,
        'serviceProviderName': provider,
      },
    ),
    'date': AppState(ff.AppState.activityDraftStartDate),
    'time': AppState(ff.AppState.activityDraftStartTime),
    'isCompleted':
        editMode
            ? AppState(ff.AppState.selectedActivity)['isCompleted']
            : false,
  });
}

List<DslAction> _commitActivityV2({
  required DslExpression Function() candidateBuilder,
  required bool editMode,
}) {
  final persistenceActions =
      editMode
          ? <DslAction>[
            UpdateAppState.updateItemAtIndex(
              ff.AppState.activities,
              AppState(ff.AppState.selectedActivityIndex),
              candidateBuilder(),
            ),
            UpdateAppState.set(
              ff.AppState.selectedActivity,
              candidateBuilder(),
            ),
          ]
          : <DslAction>[
            UpdateAppState.addToList(
              ff.AppState.activities,
              candidateBuilder(),
            ),
            UpdateAppState.increment(ff.AppState.nextActivityId, 1),
          ];
  return [
    UpdateAppState.set(ff.AppState.activitySaveInProgress, true),
    SetState(ff.Pages.activityFormPage.state.isSaving, true),
    ...persistenceActions,
    SetState(ff.Pages.activityFormPage.state.hasChanges, false),
    SetState(ff.Pages.activityFormPage.state.isSaving, false),
    UpdateAppState.set(ff.AppState.activitySaveInProgress, false),
    Snackbar('Activiteit opgeslagen'),
    Navigate(ff.Pages.planningPage),
  ];
}

DslExpression _activityDirectCandidateV2({
  required StructHandle activity,
  required bool editMode,
  required Object locationName,
  required Object customTitle,
  required Object serviceProviderName,
  required Object notes,
  required Object title,
}) => Struct(activity, {
  'id':
      editMode
          ? AppState(ff.AppState.selectedActivity)['id']
          : AppState(ff.AppState.nextActivityId),
  'horseId': AppState(ff.AppState.activityDraftHorseId),
  'stableId':
      editMode ? AppState(ff.AppState.selectedActivity)['stableId'] : '',
  'activityType': AppState(ff.AppState.activityDraftPendingType),
  'customTitle': customTitle,
  'assigneeUserIds': AppState(ff.AppState.activityDraftAssigneeUserIds),
  'startDate': AppState(ff.AppState.activityDraftStartDate),
  'endDate': AppState(ff.AppState.activityDraftEndDate),
  'startTime': AppState(ff.AppState.activityDraftStartTime),
  'endTime': AppState(ff.AppState.activityDraftEndTime),
  'allDay': AppState(ff.AppState.activityDraftAllDay),
  'durationMinutes': AppState(ff.AppState.activityDraftDurationMinutes),
  'locationType': AppState(ff.AppState.activityDraftLocationType),
  'locationName': locationName,
  'serviceProviderName': serviceProviderName,
  'notes': notes,
  'completionStatus':
      editMode
          ? AppState(ff.AppState.selectedActivity)['completionStatus']
          : 'open',
  'createdAt':
      editMode
          ? AppState(ff.AppState.selectedActivity)['createdAt']
          : Global(GlobalProperty.currentTimestamp),
  'updatedAt': Global(GlobalProperty.currentTimestamp),
  'title': title,
  'date': AppState(ff.AppState.activityDraftStartDate),
  'time': AppState(ff.AppState.activityDraftStartTime),
  'isCompleted':
      editMode ? AppState(ff.AppState.selectedActivity)['isCompleted'] : false,
});

List<DslAction> _activitySaveOrWarnV2({
  required DslExpression Function() candidateBuilder,
  required bool editMode,
  required dynamic conflictSheet,
  required CustomFunctionHandle activityConflictWarning,
  required CustomFunctionHandle activityConflictMessage,
}) {
  final conflict = CustomFunction(
    activityConflictWarning,
    args: {
      'activities': AppState(ff.AppState.activities),
      'candidate': candidateBuilder(),
      'currentUserId': AppState(ff.AppState.currentLocalUserId),
    },
  );
  final conflictMessage = CustomFunction(
    activityConflictMessage,
    args: {
      'activities': AppState(ff.AppState.activities),
      'candidate': candidateBuilder(),
      'currentUserId': AppState(ff.AppState.currentLocalUserId),
    },
  );
  return [
    If(
      Equals(conflict, false),
      then: _commitActivityV2(
        candidateBuilder: candidateBuilder,
        editMode: editMode,
      ),
      orElse: [
        ShowBottomSheet(
          conflictSheet,
          params: {
            'message': conflictMessage,
            'editMode': editMode,
            'pendingActivity': candidateBuilder(),
          },
        ),
      ],
    ),
  ];
}

List<DslAction> _activitySaveActionsV2({
  required StructHandle activity,
  required dynamic conflictSheet,
  required CustomFunctionHandle durationMinutes,
  required CustomFunctionHandle activityFormValidation,
  required CustomFunctionHandle activityValidationMessage,
  required CustomFunctionHandle activityConflictWarning,
  required CustomFunctionHandle activityConflictMessage,
  required CustomFunctionHandle activityDraftTitle,
  required CustomFunctionHandle locationNameFromDraft,
  required CustomFunctionHandle providerFromDraft,
  required CustomFunctionHandle notesFromDraft,
  required CustomFunctionHandle customTitleFromDraft,
  required CustomFunctionHandle locationTypeFromDraft,
  required CustomFunctionHandle endDateFromDraft,
  required CustomFunctionHandle allDayFromDraft,
  required CustomFunctionHandle endTimeFromDraft,
}) {
  DslExpression candidateFor(String type, bool editMode) {
    final isService = type == 'Hoefsmid' || type == 'Dierenarts';
    final locationName =
        type == 'Training'
            ? WidgetState(
              'ActivityTrainingLocationField',
              WidgetStateProperty.text,
            )
            : type == 'Wedstrijd'
            ? WidgetState(
              'ActivityCompetitionLocationField',
              WidgetStateProperty.text,
            )
            : type == 'Overig'
            ? WidgetState(
              'ActivityOtherLocationField',
              WidgetStateProperty.text,
            )
            : '';
    return _activityDirectCandidateV2(
      activity: activity,
      editMode: editMode,
      locationName: locationName,
      customTitle:
          type == 'Overig'
              ? WidgetState(
                'ActivityCustomTitleField',
                WidgetStateProperty.text,
              )
              : '',
      serviceProviderName:
          isService
              ? WidgetState('ActivityProviderField', WidgetStateProperty.text)
              : '',
      notes:
          type == 'Verzorging'
              ? ''
              : WidgetState('ActivityNotesFieldV2', WidgetStateProperty.text),
      title:
          type == 'Overig'
              ? WidgetState(
                'ActivityCustomTitleField',
                WidgetStateProperty.text,
              )
              : type,
    );
  }

  DslExpression validationFor(CustomFunctionHandle handle, String type) {
    final locationName =
        type == 'Training'
            ? WidgetState(
              'ActivityTrainingLocationField',
              WidgetStateProperty.text,
            )
            : type == 'Wedstrijd'
            ? WidgetState(
              'ActivityCompetitionLocationField',
              WidgetStateProperty.text,
            )
            : '';
    return CustomFunction(
      handle,
      args: {
        'activityType': AppState(ff.AppState.activityDraftPendingType),
        'horseId': AppState(ff.AppState.activityDraftHorseId),
        'assigneeUserIds': AppState(ff.AppState.activityDraftAssigneeUserIds),
        'startDate': AppState(ff.AppState.activityDraftStartDate),
        'endDate': AppState(ff.AppState.activityDraftEndDate),
        'startTime': AppState(ff.AppState.activityDraftStartTime),
        'endTime': AppState(ff.AppState.activityDraftEndTime),
        'allDay': AppState(ff.AppState.activityDraftAllDay),
        'durationMinutes': AppState(ff.AppState.activityDraftDurationMinutes),
        'locationType': AppState(ff.AppState.activityDraftLocationType),
        'locationName': locationName,
        'serviceProviderName':
            type == 'Hoefsmid' || type == 'Dierenarts'
                ? WidgetState('ActivityProviderField', WidgetStateProperty.text)
                : '',
        'customTitle':
            type == 'Overig'
                ? WidgetState(
                  'ActivityCustomTitleField',
                  WidgetStateProperty.text,
                )
                : '',
      },
    );
  }

  List<SwitchCase> cases(bool editMode) => [
    for (final type in const [
      'Training',
      'Verzorging',
      'Hoefsmid',
      'Dierenarts',
      'Wedstrijd',
      'Overig',
    ])
      SwitchCase(
        type,
        then: If(
          Equals(validationFor(activityFormValidation, type), true),
          then: _activitySaveOrWarnV2(
            candidateBuilder: () => candidateFor(type, editMode),
            editMode: editMode,
            conflictSheet: conflictSheet,
            activityConflictWarning: activityConflictWarning,
            activityConflictMessage: activityConflictMessage,
          ),
          orElse: SetState(
            ff.Pages.activityFormPage.state.formValidationMessage,
            validationFor(activityValidationMessage, type),
          ),
        ),
      ),
  ];

  return [
    SetState(ff.Pages.activityFormPage.state.formValidationMessage, ''),
    If(
      Not(AppState(ff.AppState.activitySaveInProgress)),
      then: [
        If(
          PageParam('editMode'),
          then: [
            Switch(
              AppState(ff.AppState.activityDraftPendingType),
              cases: cases(true),
            ),
          ],
          orElse: [
            Switch(
              AppState(ff.AppState.activityDraftPendingType),
              cases: cases(false),
            ),
          ],
        ),
      ],
    ),
  ];
}

