        children: [
          _horseFieldLabel('Duur', requiredField: true),
          Dropdown(
            name: 'ActivityDurationDropdown',
            label: 'Duur',
            hint: 'Selecteer een duur',
            options: const [
              '15 minuten',
              '30 minuten',
              '45 minuten',
              '1 uur',
              '1,5 uur',
              '2 uur',
              'Aangepast',
            ],
            value: State(ff.Pages.activityFormPage.state.formDurationChoice),
            onChanged: [
              SetState(
                ff.Pages.activityFormPage.state.formDurationChoice,
                WidgetValue(),
              ),
              Switch(
                WidgetValue(),
                cases: [
                  SwitchCase(
                    '15 minuten',
                    then: UpdateAppState.set(
                      ff.AppState.activityDraftDurationMinutes,
                      15,
                    ),
                  ),
                  SwitchCase(
                    '30 minuten',
                    then: UpdateAppState.set(
                      ff.AppState.activityDraftDurationMinutes,
                      30,
                    ),
                  ),
                  SwitchCase(
                    '45 minuten',
                    then: UpdateAppState.set(
                      ff.AppState.activityDraftDurationMinutes,
                      45,
                    ),
                  ),
                  SwitchCase(
                    '1 uur',
                    then: UpdateAppState.set(
                      ff.AppState.activityDraftDurationMinutes,
                      60,
                    ),
                  ),
                  SwitchCase(
                    '1,5 uur',
                    then: UpdateAppState.set(
                      ff.AppState.activityDraftDurationMinutes,
                      90,
                    ),
                  ),
                  SwitchCase(
                    '2 uur',
                    then: UpdateAppState.set(
                      ff.AppState.activityDraftDurationMinutes,
                      120,
                    ),
                  ),
                  SwitchCase(
                    'Aangepast',
                    then: UpdateAppState.set(
                      ff.AppState.activityDraftDurationMinutes,
                      0,
                    ),
                  ),
                ],
              ),
              SetState(ff.Pages.activityFormPage.state.hasChanges, true),
              SetState(
                ff.Pages.activityFormPage.state.formValidationMessage,
                '',
              ),
            ],
          ),
          TextField(
            name: 'ActivityCustomDurationField',
            visible: Equals(
              State(ff.Pages.activityFormPage.state.formDurationChoice),
              'Aangepast',
            ),
            label: 'Aantal minuten',
            hint: 'Bijvoorbeeld 75',
            onChanged: [
              UpdateAppState.set(
                ff.AppState.activityDraftDurationMinutes,
                TextValue().asInt(),
              ),
              SetState(ff.Pages.activityFormPage.state.hasChanges, true),
              SetState(
                ff.Pages.activityFormPage.state.formValidationMessage,
                '',
              ),
            ],
          ),
        ],
      ),
      Column(
        visible: Equals(type, 'Overig'),
        crossAxis: CrossAxis.stretch,
        spacing: 8,
        children: [
          _horseFieldLabel('Locatie'),
          TextField(
            name: 'ActivityOtherLocationField',
