  );
}

DslWidget _activityAgendaFormCardV3({required dynamic agendaPicker}) {
  final type = AppState(ff.AppState.activityDraftPendingType);
  final formatDate = CustomFunctionHandle(
    name: 'formatActivityDateDutch',
    args: {'date': dateTime},
    returnType: string,
  );
  final formatTime = CustomFunctionHandle(
    name: 'formatActivityTimeDutch',
    args: {'time': dateTime},
    returnType: string,
  );
  final usesEndTime = CustomFunctionHandle(
    name: 'activityTypeUsesEndTimeV2',
    args: {'activityType': string, 'allDay': bool_},
    returnType: bool_,
  );
  return Container(
    name: 'ActivityAgendaEntryCardV3',
    padding: 10,
    borderRadius: 10,
    borderColor: Colors.alternate,
    borderWidth: 0.8,
    color: Colors.secondaryBackground,
    child: Column(
      crossAxis: CrossAxis.stretch,
      spacing: 4,
      children: [
        _activityAgendaSummaryRowV2(
          'calendar_today',
          'Datum',
          CustomFunction(
            formatDate,
            args: {'date': AppState(ff.AppState.activityDraftStartDate)},
          ),
          onTap: _openAgendaFromFormV3(
            agendaPicker: agendaPicker,
            activityType: type,
            initialMode: 'date',
          ),
        ),
        _activityAgendaSummaryRowV2(
          'event',
          'Tot en met',
          CustomFunction(
            formatDate,
            args: {'date': AppState(ff.AppState.activityDraftEndDate)},
          ),
          visible: Equals(type, 'Wedstrijd'),
          onTap: _openAgendaFromFormV3(
            agendaPicker: agendaPicker,
            activityType: type,
            initialMode: 'endDate',
          ),
        ),
        _activityAgendaSummaryRowV2(
          'schedule',
          'Starttijd',
          CustomFunction(
            formatTime,
            args: {'time': AppState(ff.AppState.activityDraftStartTime)},
          ),
          visible: Not(AppState(ff.AppState.activityDraftAllDay)),
          onTap: _openAgendaFromFormV3(
            agendaPicker: agendaPicker,
            activityType: type,
            initialMode: 'startTime',
          ),
        ),
        _activityAgendaSummaryRowV2(
          'more_time',
          'Eindtijd',
          CustomFunction(
            formatTime,
            args: {'time': AppState(ff.AppState.activityDraftEndTime)},
          ),
          visible: CustomFunction(
            usesEndTime,
            args: {
              'activityType': type,
              'allDay': AppState(ff.AppState.activityDraftAllDay),
            },
          ),
          onTap: _openAgendaFromFormV3(
            agendaPicker: agendaPicker,
            activityType: type,
            initialMode: 'endTime',
          ),
        ),
        Container(
          height: 44,
          padding: EdgeInsets.symmetric(horizontal: 4),
          alignment: Alignment.center,
          onTap: _openAgendaFromFormV3(
            agendaPicker: agendaPicker,
            activityType: type,
            initialMode: 'overview',
          ),
          child: Row(
            mainAxis: MainAxis.end,
            children: [
              Text(
                'Open agenda',
                style: Styles.labelMedium,
                color: Colors.secondary,
              ),
              Icon('chevron_right', size: 20, color: Colors.secondary),
            ],
          ),
        ),
      ],
    ),
  );
}

DslWidget _activityAgendaSummaryRowV2(
  String icon,
  String label,
  Object value, {
  Object visible = true,
  Object? onTap,
}) => Container(
  visible: visible,
