        Text(
          value,
          style: Styles.bodyMedium,
          color: Colors.primaryText,
          textAlign: TextAlign.end,
          maxLines: 2,
          overflow: TextOverflow.ellipsis,
        ),
      ),
      Icon('chevron_right', size: 18, color: Colors.secondaryText),
