  ),
);

List<DslAction> _openAgendaFromFormV3({
  required dynamic agendaPicker,
  required Object activityType,
  required String initialMode,
}) => [
  If(
    Not(State(ff.Pages.activityFormPage.state.agendaOpening)),
    then: [
      SetState(ff.Pages.activityFormPage.state.agendaOpening, true),
      ShowBottomSheet(
        agendaPicker,
        params: {'activityType': activityType, 'initialMode': initialMode},
      ),
      SetState(ff.Pages.activityFormPage.state.agendaOpening, false),
    ],
  ),
];

