DslWidget _activityAgendaPickerSheetV2({
  required CustomFunctionHandle agendaMarkedDates,
  required CustomFunctionHandle agendaInitialDate,
  required CustomFunctionHandle agendaMonthShift,
  required CustomFunctionHandle agendaCalendarDays,
  required CustomFunctionHandle agendaMonthLabel,
  required CustomFunctionHandle agendaDateLabel,
  required CustomFunctionHandle agendaTimeLabel,
  required CustomFunctionHandle agendaDayNumber,
  required CustomFunctionHandle agendaDayStyle,
  required CustomFunctionHandle agendaDateIsBefore,
  required CustomFunctionHandle agendaInitialTime,
  required CustomFunctionHandle agendaAdjustTime,
  required CustomFunctionHandle agendaCandidateTimeIsValid,
  required CustomFunctionHandle agendaModeTitle,
  required CustomFunctionHandle agendaIsCalendarMode,
  required CustomFunctionHandle agendaIsTimeMode,
  required CustomFunctionHandle agendaTextIsEmpty,
  required CustomFunctionHandle agendaReady,
  required CustomFunctionHandle agendaPlannedSummary,
}) {
  final agendaState = ff.Components.avarynAgendaPickerSheet.state;
  final usesEndTime = CustomFunctionHandle(
    name: 'activityTypeUsesEndTimeV2',
    args: {'activityType': string, 'allDay': bool_},
    returnType: bool_,
  );
  final calendarVisible = CustomFunction(
    agendaIsCalendarMode,
    args: {'mode': State(agendaState.agendaMode)},
  );
  final timeVisible = CustomFunction(
    agendaIsTimeMode,
    args: {'mode': State(agendaState.agendaMode)},
  );
  final plannedSummary = CustomFunction(
    agendaPlannedSummary,
    args: {
      'activities': AppState(ff.AppState.activities),
      'selectedDate': State(agendaState.agendaDraftStartDate),
    },
  );
  final ready = CustomFunction(
    agendaReady,
    args: {
      'activityType': Param('activityType'),
      'startDate': State(agendaState.agendaDraftStartDate),
      'endDate': State(agendaState.agendaDraftEndDate),
      'startTime': State(agendaState.agendaDraftStartTime),
      'endTime': State(agendaState.agendaDraftEndTime),
    },
  );
  return Container(
    name: 'AvarynAgendaPickerSheetBody',
    height: 690,
    padding: EdgeInsets.only(left: 18, top: 16, right: 18, bottom: 18),
    color: Colors.primaryBackground,
