                                    args: {
                                      'value': State(
                                        agendaState.agendaTimeDraft,
                                      ),
                                      'deltaMinutes': -5,
                                    },
                                  ),
                                ),
                              ),
                            ),
                            Expanded(
                              Button(
                                '+ 5 min',
                                variant: ButtonVariant.outlined,
                                height: 44,
                                borderRadius: 9,
                                onTap: SetState(
                                  agendaState.agendaTimeDraft,
                                  CustomFunction(
                                    agendaAdjustTime,
                                    args: {
                                      'value': State(
                                        agendaState.agendaTimeDraft,
                                      ),
                                      'deltaMinutes': 5,
                                    },
                                  ),
                                ),
                              ),
                            ),
                          ],
                        ),
                      ],
                    ),
                  ),
                  Row(
                    spacing: 10,
                    children: [
                      Expanded(
                        Button(
                          'Annuleren',
                          variant: ButtonVariant.outlined,
                          height: 46,
                          borderRadius: 10,
                          onTap: _agendaCancelTimeV3(),
                        ),
                      ),
                      Expanded(
                        Button(
                          'Bevestigen',
                          height: 46,
                          color: Colors.secondary,
                          textColor: Colors.primary,
                          borderRadius: 10,
                          onTap: _agendaConfirmTimeV3(
                            agendaCandidateTimeIsValid:
                                agendaCandidateTimeIsValid,
                          ),
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ],
          ),
        ),
        Button(
