DslWidget _agendaDayCellV3({
  required Object day,
  required CustomFunctionHandle agendaDayNumber,
  required CustomFunctionHandle agendaDayStyle,
  required CustomFunctionHandle agendaDateIsBefore,
}) {
  final agendaState = ff.Components.avarynAgendaPickerSheet.state;
  final style = CustomFunction(
    agendaDayStyle,
    args: {
      'date': day,
      'month': State(agendaState.agendaDisplayedMonth),
      'startDate': State(agendaState.agendaDraftStartDate),
      'endDate': State(agendaState.agendaDraftEndDate),
    },
  );
  final dayNumber = CustomFunction(agendaDayNumber, args: {'date': day});
  return Container(
    height: 34,
    alignment: Alignment.center,
    onTap: [
      SetState(agendaState.agendaDisplayedMonth, day),
      If(
        Equals(Param('activityType'), 'Wedstrijd'),
        then: [
          If(
            Equals(State(agendaState.agendaRangeStep), 'start'),
            then: [
              SetState(agendaState.agendaDraftStartDate, day),
              SetState.clear(agendaState.agendaDraftEndDate),
              SetState(agendaState.agendaRangeStep, 'end'),
            ],
            orElse: [
              If(
                CustomFunction(
                  agendaDateIsBefore,
                  args: {
                    'candidate': day,
                    'startDate': State(agendaState.agendaDraftStartDate),
                  },
                ),
                then: Snackbar('Tot en met kan niet vóór Datum van liggen.'),
                orElse: SetState(agendaState.agendaDraftEndDate, day),
              ),
            ],
          ),
        ],
        orElse: [
          SetState(agendaState.agendaDraftStartDate, day),
          SetState(agendaState.agendaDraftEndDate, day),
        ],
      ),
    ],
    child: Stack(
      alignment: Alignment.center,
      children: [
        Container(
          visible: Equals(style, 'range'),
          width: 48,
          height: 34,
          borderRadius: 5,
          color: Colors.accent2,
        ),
        Container(
          visible: Equals(style, 'start'),
          width: 34,
          height: 34,
          borderRadius: 999,
          color: Colors.secondary,
        ),
        Container(
          visible: Equals(style, 'end'),
          width: 34,
          height: 34,
          borderRadius: 999,
          color: Colors.secondary,
        ),
        Container(
          visible: Equals(style, 'startEnd'),
          width: 34,
          height: 34,
          borderRadius: 999,
          color: Colors.secondary,
        ),
        Text(
          dayNumber,
          visible: Equals(style, 'normal'),
          style: Styles.bodySmall,
          color: Colors.primaryText,
        ),
        Text(
          dayNumber,
          visible: Equals(style, 'outside'),
          style: Styles.bodySmall,
          color: Colors.secondaryText,
        ),
        Text(
          dayNumber,
          visible: Equals(style, 'range'),
          style: Styles.bodySmall,
          color: Colors.secondary,
        ),
        Text(
          dayNumber,
          visible: Equals(style, 'start'),
          style: Styles.labelMedium,
          color: Colors.primary,
        ),
        Text(
          dayNumber,
          visible: Equals(style, 'end'),
          style: Styles.labelMedium,
          color: Colors.primary,
        ),
        Text(
          dayNumber,
          visible: Equals(style, 'startEnd'),
          style: Styles.labelMedium,
          color: Colors.primary,
        ),
      ],
    ),
  );
}

List<DslAction> _activityAgendaPickerOnInitV3({
  required CustomFunctionHandle agendaInitialDate,
  required CustomFunctionHandle agendaInitialTime,
}) {
  final state = ff.Components.avarynAgendaPickerSheet.state;
  return [
    SetState(state.agendaMode, Param('initialMode')),
    SetState(
      state.agendaDraftStartDate,
      AppState(ff.AppState.activityDraftStartDate),
    ),
    SetState(
      state.agendaDraftEndDate,
      AppState(ff.AppState.activityDraftEndDate),
    ),
    SetState(
      state.agendaDraftStartTime,
      AppState(ff.AppState.activityDraftStartTime),
    ),
    SetState(
      state.agendaDraftEndTime,
      AppState(ff.AppState.activityDraftEndTime),
    ),
    SetState(
      state.agendaDisplayedMonth,
      CustomFunction(
        agendaInitialDate,
        args: {'value': AppState(ff.AppState.activityDraftStartDate)},
      ),
    ),
    SetState(state.agendaRangeStep, 'start'),
    If(
      Equals(Param('initialMode'), 'endDate'),
      then: SetState(state.agendaRangeStep, 'end'),
    ),
    If(
      Equals(Param('initialMode'), 'endTime'),
      then: [
        SetState(state.agendaTimeTarget, 'end'),
        SetState(
          state.agendaTimeDraft,
          CustomFunction(
            agendaInitialTime,
            args: {'value': AppState(ff.AppState.activityDraftEndTime)},
          ),
        ),
      ],
      orElse: [
        SetState(state.agendaTimeTarget, 'start'),
        SetState(
          state.agendaTimeDraft,
          CustomFunction(
            agendaInitialTime,
            args: {'value': AppState(ff.AppState.activityDraftStartTime)},
          ),
        ),
      ],
    ),
  ];
}

List<DslAction> _agendaOpenTimeV3({
  required String target,
  required CustomFunctionHandle agendaInitialTime,
}) {
  final state = ff.Components.avarynAgendaPickerSheet.state;
  return [
    SetState(state.agendaTimeTarget, target),
    SetState(
      state.agendaTimeDraft,
      CustomFunction(
        agendaInitialTime,
        args: {
          'value':
              target == 'start'
                  ? State(state.agendaDraftStartTime)
                  : State(state.agendaDraftEndTime),
        },
      ),
    ),
    SetState(state.agendaMode, target == 'start' ? 'startTime' : 'endTime'),
  ];
}

List<DslAction> _agendaCancelTimeV3() {
  final state = ff.Components.avarynAgendaPickerSheet.state;
  return [
    If(
      Equals(Param('initialMode'), 'startTime'),
      then: NavigateBack(),
      orElse: [
        If(
          Equals(Param('initialMode'), 'endTime'),
          then: NavigateBack(),
          orElse: SetState(state.agendaMode, 'overview'),
        ),
      ],
    ),
  ];
}

List<DslAction> _agendaConfirmTimeV3({
  required CustomFunctionHandle agendaCandidateTimeIsValid,
}) {
  final state = ff.Components.avarynAgendaPickerSheet.state;
  return [
    If(
      CustomFunction(
        agendaCandidateTimeIsValid,
        args: {
          'target': State(state.agendaTimeTarget),
          'activityType': Param('activityType'),
          'startDate': State(state.agendaDraftStartDate),
          'endDate': State(state.agendaDraftEndDate),
          'startTime': State(state.agendaDraftStartTime),
          'endTime': State(state.agendaDraftEndTime),
          'candidate': State(state.agendaTimeDraft),
        },
      ),
      then: [
        If(
          Equals(State(state.agendaTimeTarget), 'start'),
          then: [
            SetState(state.agendaDraftStartTime, State(state.agendaTimeDraft)),
            If(
              Equals(Param('initialMode'), 'startTime'),
              then: [
                UpdateAppState.set(
                  ff.AppState.activityDraftStartTime,
                  State(state.agendaTimeDraft),
                ),
                NavigateBack(),
              ],
              orElse: SetState(state.agendaMode, 'overview'),
            ),
          ],
          orElse: [
            SetState(state.agendaDraftEndTime, State(state.agendaTimeDraft)),
            If(
              Equals(Param('initialMode'), 'endTime'),
              then: [
                UpdateAppState.set(
                  ff.AppState.activityDraftEndTime,
                  State(state.agendaTimeDraft),
                ),
                NavigateBack(),
              ],
              orElse: SetState(state.agendaMode, 'overview'),
            ),
          ],
        ),
      ],
      orElse: Snackbar('Eindtijd moet na Starttijd liggen.'),
    ),
  ];
}

List<DslAction> _agendaCommitV3() {
  final state = ff.Components.avarynAgendaPickerSheet.state;
  return [
    UpdateAppState.set(
      ff.AppState.activityDraftStartDate,
      State(state.agendaDraftStartDate),
    ),
    If(
      Equals(Param('activityType'), 'Wedstrijd'),
      then: UpdateAppState.set(
        ff.AppState.activityDraftEndDate,
        State(state.agendaDraftEndDate),
      ),
      orElse: UpdateAppState.set(
        ff.AppState.activityDraftEndDate,
        State(state.agendaDraftStartDate),
      ),
    ),
    UpdateAppState.set(
      ff.AppState.activityDraftStartTime,
      State(state.agendaDraftStartTime),
    ),
    UpdateAppState.set(
      ff.AppState.activityDraftEndTime,
      State(state.agendaDraftEndTime),
    ),
    NavigateBack(),
  ];
}

