              If(
                Param('editMode'),
                then: [
                  UpdateAppState.updateItemAtIndex(
                    ff.AppState.activities,
                    AppState(ff.AppState.selectedActivityIndex),
                    Param('pendingActivity'),
                  ),
                  UpdateAppState.set(
                    ff.AppState.selectedActivity,
                    Param('pendingActivity'),
                  ),
                ],
                orElse: [
                  UpdateAppState.addToList(
                    ff.AppState.activities,
                    Param('pendingActivity'),
                  ),
                  UpdateAppState.increment(ff.AppState.nextActivityId, 1),
                ],
              ),
              UpdateAppState.set(ff.AppState.activitySaveInProgress, false),
              Snackbar('Activiteit opgeslagen met planningsconflict'),
              Navigate(ff.Pages.planningPage),
            ],
          ),
        ],
      ),
    ],
  ),
);

DslExpression _activityWithCompletionV2(
  StructHandle activity,
  DslExpression source,
  Object completed,
) {
  final statusFromBool = CustomFunctionHandle(
    name: 'activityCompletionStatusFromBoolV2',
    args: {'completed': bool_},
    returnType: string,
  );
  return Struct(activity, {
    'id': source['id'],
    'horseId': source['horseId'],
    'stableId': source['stableId'],
    'activityType': source['activityType'],
    'customTitle': source['customTitle'],
    'assigneeUserIds': source['assigneeUserIds'],
    'startDate': source['startDate'],
    'endDate': source['endDate'],
    'startTime': source['startTime'],
    'endTime': source['endTime'],
    'allDay': source['allDay'],
    'durationMinutes': source['durationMinutes'],
    'locationType': source['locationType'],
    'locationName': source['locationName'],
    'serviceProviderName': source['serviceProviderName'],
    'notes': source['notes'],
    'completionStatus': CustomFunction(
      statusFromBool,
      args: {'completed': completed},
    ),
    'createdAt': source['createdAt'],
    'updatedAt': Global(GlobalProperty.currentTimestamp),
    'title': source['title'],
    'date': source['date'],
    'time': source['time'],
    'isCompleted': completed,
  });
}

List<DslAction> _selectedActivityToggleActionsV2(
  StructHandle activity,
  CustomFunctionHandle effectiveCompletion,
) {
  final next = Not(
    CustomFunction(
      effectiveCompletion,
      args: {'activity': AppState(ff.AppState.selectedActivity)},
    ),
  );
  final updated = _activityWithCompletionV2(
    activity,
    AppState(ff.AppState.selectedActivity),
    next,
  );
  return [
    UpdateAppState.updateItemAtIndex(
      ff.AppState.activities,
      AppState(ff.AppState.selectedActivityIndex),
      updated,
    ),
    UpdateAppState.set(ff.AppState.selectedActivity, updated),
    Snackbar('Activiteitsstatus bijgewerkt'),
  ];
}

