void _applyActivityResponsiveVisibility(App app, {required String pageName}) {
  app.raw((project) {
    final page = findPage(project, name: pageName);
    if (page == null) {
      throw StateError('Expected $pageName to be present.');
    }

    FFNode requireNamedNode(String suffix) {
      final name = '$pageName$suffix';
      final matches = findDescendants(page.node, (node) => node.name == name);
      if (matches.length != 1) {
        throw StateError(
          'Expected one $name widget in $pageName, found ${matches.length}.',
        );
      }
      return matches.single;
    }

    setResponsiveVisibility(
      requireNamedNode('DesktopSideNavigation'),
      phoneHidden: true,
      tabletHidden: true,
      tabletLandscapeHidden: true,
      desktopHidden: false,
    );
    setResponsiveVisibility(
      requireNamedNode('CompactCanvas'),
      phoneHidden: false,
      tabletHidden: false,
      tabletLandscapeHidden: false,
      desktopHidden: false,
    );
    setResponsiveVisibility(
      requireNamedNode('MobileBottomNavigation'),
      phoneHidden: false,
      tabletHidden: false,
      tabletLandscapeHidden: false,
      desktopHidden: true,
    );
  });
}

