List<DslAction> _activityFormOnLoad({
  required CustomFunctionHandle activityDateDay,
  required CustomFunctionHandle activityDateMonth,
  required CustomFunctionHandle activityDateYear,
}) => [
  SetState('isSaving', false),
  SetState('showTypeError', false),
  SetState('showHorseError', false),
  SetState('showTitleError', false),
  SetState('showDateError', false),
  If(
    PageParam('editMode'),
    then: [
      SetState(
        'formActivityType',
        AppState(ff.AppState.selectedActivity)['activityType'],
      ),
      UpdateAppState.set(
        ff.AppState.activityDraftHorseId,
        AppState(ff.AppState.selectedActivity)['horseId'],
      ),
      SetState('formDate', AppState(ff.AppState.selectedActivity)['date']),
      SetState('formTime', AppState(ff.AppState.selectedActivity)['time']),
      SetState(
        'formDateDay',
        CustomFunction(
          activityDateDay,
          args: {'date': AppState(ff.AppState.selectedActivity)['date']},
        ),
      ),
      SetState(
        'formDateMonth',
        CustomFunction(
          activityDateMonth,
          args: {'date': AppState(ff.AppState.selectedActivity)['date']},
        ),
      ),
      SetState(
        'formDateYear',
        CustomFunction(
          activityDateYear,
          args: {'date': AppState(ff.AppState.selectedActivity)['date']},
        ),
      ),
      SetFormField(
        'ActivityTitleField',
        AppState(ff.AppState.selectedActivity)['title'],
      ),
      SetFormField(
        'ActivityNotesField',
        AppState(ff.AppState.selectedActivity)['notes'],
      ),
    ],
    orElse: [
      SetState('formActivityType', ''),
      UpdateAppState.set(ff.AppState.activityDraftHorseId, 0),
      SetState.clear('formDate'),
      SetState.clear('formTime'),
      SetState('formDateDay', ''),
      SetState('formDateMonth', ''),
      SetState('formDateYear', ''),
      SetFormField('ActivityTitleField', ''),
      SetFormField('ActivityNotesField', ''),
    ],
  ),
  SetState('hasChanges', false),
];

List<DslAction> _activityDiscardActions(dynamic activityConfirmationSheet) => [
  If(
    State('hasChanges'),
    then: [
      ShowBottomSheet(
        activityConfirmationSheet,
        params: {
          'title': 'Wijzigingen verwerpen?',
          'message':
              'Je invoer is nog niet opgeslagen. Wil je zonder opslaan teruggaan?',
          'confirmText': 'Verwerpen',
          'onConfirmAction': [SetState('hasChanges', false), NavigateBack()],
        },
      ),
    ],
    orElse: [NavigateBack()],
  ),
];

DslExpression _activityFromForm(
  StructHandle activity, {
  required bool editMode,
}) => Struct(activity, {
  'id':
      editMode
          ? AppState(ff.AppState.selectedActivity)['id']
          : AppState(ff.AppState.nextActivityId),
  'activityType': State('formActivityType'),
  'horseId': AppState(ff.AppState.activityDraftHorseId),
  'title': WidgetState('ActivityTitleField', WidgetStateProperty.text),
  'date': State('formDate'),
  'time': State('formTime'),
  'notes': WidgetState('ActivityNotesField', WidgetStateProperty.text),
  'isCompleted':
      editMode ? AppState(ff.AppState.selectedActivity)['isCompleted'] : false,
  'createdAt':
      editMode
          ? AppState(ff.AppState.selectedActivity)['createdAt']
          : Global(GlobalProperty.currentTimestamp),
  'updatedAt': Global(GlobalProperty.currentTimestamp),
});

List<DslAction> _activitySaveActions({
  required StructHandle activity,
  required CustomFunctionHandle activityFormIsValid,
}) => [
  SetState('showTypeError', Equals(State('formActivityType'), '')),
  SetState(
    'showHorseError',
    Equals(AppState(ff.AppState.activityDraftHorseId), 0),
  ),
  SetState(
    'showTitleError',
    Equals(WidgetState('ActivityTitleField', WidgetStateProperty.text), ''),
  ),
  SetState('showDateError', Equals(State('formDateDay'), '')),
  If(
    Not(State('isSaving')),
    then: [
      If(
        Equals(
          CustomFunction(
            activityFormIsValid,
            args: {
              'activityType': State('formActivityType'),
              'horseId': AppState(ff.AppState.activityDraftHorseId),
              'title': WidgetState(
                'ActivityTitleField',
                WidgetStateProperty.text,
              ),
              'date': State('formDate'),
            },
          ),
          true,
        ),
        then: [
          SetState('isSaving', true),
          If(
            PageParam('editMode'),
            then: [
              UpdateAppState.updateItemAtIndex(
                ff.AppState.activities,
                AppState(ff.AppState.selectedActivityIndex),
                _activityFromForm(activity, editMode: true),
              ),
              UpdateAppState.set(
                ff.AppState.selectedActivity,
                _activityFromForm(activity, editMode: true),
              ),
            ],
            orElse: [
              UpdateAppState.addToList(
                ff.AppState.activities,
                _activityFromForm(activity, editMode: false),
              ),
              UpdateAppState.increment(ff.AppState.nextActivityId, 1),
            ],
          ),
          SetState('hasChanges', false),
          SetState('isSaving', false),
          Snackbar('Activiteit opgeslagen'),
          Navigate(ff.Pages.planningPage),
        ],
      ),
    ],
  ),
];

