DslExpression _activityWithCompletion(
  StructHandle activity,
  DslExpression source,
  Object completed,
) => Struct(activity, {
  'id': source['id'],
  'activityType': source['activityType'],
  'horseId': source['horseId'],
  'title': source['title'],
  'date': source['date'],
  'time': source['time'],
  'notes': source['notes'],
  'isCompleted': completed,
  'createdAt': source['createdAt'],
  'updatedAt': Global(GlobalProperty.currentTimestamp),
});

List<DslAction> _activityToggleFromList({
  required StructHandle activity,
  required DslExpression activityItem,
  required CustomFunctionHandle activityIndexById,
}) => [
  UpdateAppState.updateItemAtIndex(
    ff.AppState.activities,
    CustomFunction(
      activityIndexById,
      args: {
        'activities': AppState(ff.AppState.activities),
        'activityId': activityItem['id'],
      },
    ),
    _activityWithCompletion(
      activity,
      activityItem,
      Not(activityItem['isCompleted']),
    ),
  ),
  Snackbar('Activiteitsstatus bijgewerkt'),
];

List<DslAction> _selectedActivityToggleActions(StructHandle activity) => [
  UpdateAppState.updateItemAtIndex(
    ff.AppState.activities,
    AppState(ff.AppState.selectedActivityIndex),
    _activityWithCompletion(
      activity,
      AppState(ff.AppState.selectedActivity),
      Not(AppState(ff.AppState.selectedActivity)['isCompleted']),
    ),
  ),
  UpdateAppState.set(
    ff.AppState.selectedActivity,
    _activityWithCompletion(
      activity,
      AppState(ff.AppState.selectedActivity),
      Not(AppState(ff.AppState.selectedActivity)['isCompleted']),
    ),
  ),
  Snackbar('Activiteitsstatus bijgewerkt'),
];

