DslWidget _todayActivitiesSection({
  required StructHandle activity,
  required dynamic activityCard,
  required CustomFunctionHandle todayActivities,
  required CustomFunctionHandle activityListIsEmpty,
  required CustomFunctionHandle activityIndexById,
  required CustomFunctionHandle activityHorseName,
  required CustomFunctionHandle activityHorsePhoto,
  required CustomFunctionHandle formatActivityDate,
  required CustomFunctionHandle formatActivityTime,
  required bool compact,
}) {
  final todaySource = CustomFunction(
    todayActivities,
    args: {'activities': AppState(ff.AppState.activities)},
  );
  return Column(
    name: compact ? 'TodayPlannedMobileSection' : 'TodayPlannedDesktopSection',
    crossAxis: CrossAxis.stretch,
    spacing: 12,
    children: [
      Row(
        mainAxis: MainAxis.spaceBetween,
        crossAxis: CrossAxis.center,
        spacing: 10,
        children: [
          Expanded(
            Column(
              crossAxis: CrossAxis.start,
              spacing: 3,
              children: [
                Text(
                  'Vandaag gepland',
                  style: Styles.titleLarge,
                  color: Colors.primaryText,
                ),
                Text(
                  'Je lokale activiteiten voor vandaag.',
                  style: Styles.bodySmall,
                  color: Colors.secondaryText,
                  maxLines: 2,
                  overflow: TextOverflow.ellipsis,
                ),
              ],
            ),
          ),
          IconButton(
            'arrow_forward',
            size: 21,
            color: Colors.secondary,
            fillColor: Colors.accent2,
            borderRadius: 8,
            onTap: Navigate(ff.Pages.planningPage),
          ),
        ],
      ),
      ListView(
        name:
            compact
                ? 'TodayPlannedActivityListMobile'
                : 'TodayPlannedActivityListDesktop',
        source: todaySource,
        spacing: 10,
        shrinkWrap: true,
        itemBuilder:
            (activityItem) => activityCard(
              name: 'TodayPlannedActivityCard',
              activityType: activityItem['activityType'],
              title: activityItem['title'],
              horseName: CustomFunction(
                activityHorseName,
                args: {
                  'horses': AppState(ff.AppState.horses),
                  'horseId': activityItem['horseId'],
                },
              ),
              horsePhoto: CustomFunction(
                activityHorsePhoto,
                args: {
                  'horses': AppState(ff.AppState.horses),
                  'horseId': activityItem['horseId'],
                },
              ),
              dateLabel: CustomFunction(
                formatActivityDate,
                args: {'date': activityItem['date']},
              ),
              timeLabel: CustomFunction(
                formatActivityTime,
                args: {'time': activityItem['time']},
              ),
              completed: activityItem['isCompleted'],
              showCompleteAction: Not(activityItem['isCompleted']),
              showReopenAction: activityItem['isCompleted'],
              showDetailsAction: false,
              onOpenAction: [
                UpdateAppState.set(
                  ff.AppState.selectedActivityIndex,
                  CustomFunction(
                    activityIndexById,
                    args: {
                      'activities': AppState(ff.AppState.activities),
                      'activityId': activityItem['id'],
                    },
                  ),
                ),
                UpdateAppState.set(ff.AppState.selectedActivity, activityItem),
                Navigate(ff.Pages.activityDetailPage),
              ],
              onToggleAction: _activityToggleFromList(
                activity: activity,
                activityItem: activityItem,
                activityIndexById: activityIndexById,
              ),
            ),
      ),
      Container(
        visible: CustomFunction(
          activityListIsEmpty,
          args: {'activities': todaySource},
        ),
        padding: EdgeInsets.symmetric(horizontal: 16, vertical: 18),
        borderRadius: 12,
        borderColor: Colors.alternate,
        borderWidth: 0.7,
        color: Colors.secondaryBackground,
        child: Row(
          spacing: 10,
          children: [
            Icon('event_available', size: 21, color: Colors.secondary),
            Expanded(
              Text(
                'Geen activiteiten gepland voor vandaag.',
                style: Styles.bodyMedium,
                color: Colors.secondaryText,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
              ),
            ),
          ],
        ),
      ),
    ],
  );
}
